tokio::task_local! {
    /// Verified HTTP owner capability for this exact chat request. Internal
    /// drains, background continuations, voice, tasks and tests enter with
    /// `None`; task-local absence is a denial for owner-only app tools.
    static CHAT_APP_OWNER_EXECUTION_CREDENTIAL:
        Option<Arc<crate::magician_v2::apps::boundary::AppOwnerExecutionCredential>>;
}

fn current_chat_app_owner_execution_credential(
) -> Option<Arc<crate::magician_v2::apps::boundary::AppOwnerExecutionCredential>> {
    CHAT_APP_OWNER_EXECUTION_CREDENTIAL
        .try_with(Clone::clone)
        .ok()
        .flatten()
}

/// Poll one server-owned voice/chat continuation under the exact in-process
/// owner capability. The capability itself has no wire/durable form; callers
/// without a boundary-minted value can only pass `None`, which is a denial.
pub async fn scope_app_owner_execution_credential<T, F>(
    credential: Option<Arc<crate::magician_v2::apps::boundary::AppOwnerExecutionCredential>>,
    future: F,
) -> T
where
    F: Future<Output = T>,
{
    CHAT_APP_OWNER_EXECUTION_CREDENTIAL
        .scope(credential, future)
        .await
}

impl ChatService {
    /// Preflight the server-selected realtime profile before opening any
    /// physical provider session for an authenticated governed call.
    pub fn attest_realtime_voice_profile(&self, profile_name: &str) -> bool {
        let Some(resources) = self
            .scoped_capability_resolver
            .as_ref()
            .and_then(|resolver| resolver.agent_resources())
        else {
            return false;
        };
        let config = resources.magician_config_snapshot();
        config
            .llm
            .router
            .as_ref()
            .and_then(|router| router.realtime_voice.profiles.get(profile_name))
            .is_some_and(|profile| profile.fallback.is_empty())
            && crate::magician_v2::apps::processing_boundary::current_realtime_voice_provider_grant(
                &config,
                profile_name,
                Utc::now(),
            )
            .is_ok()
    }

    pub fn attest_realtime_voice_route(
        &self,
        profile_name: &str,
        provider: &str,
        model: &str,
        base_url: Option<&str>,
        topology: &str,
    ) -> bool {
        let Some(resources) = self
            .scoped_capability_resolver
            .as_ref()
            .and_then(|resolver| resolver.agent_resources())
        else {
            return false;
        };
        let config = resources.magician_config_snapshot();
        config
            .llm
            .router
            .as_ref()
            .and_then(|router| router.realtime_voice.profiles.get(profile_name))
            .is_some_and(|profile| {
                let current_base_url =
                    crate::magician_v2::apps::processing_boundary::effective_realtime_voice_base_url(
                        profile.provider.as_str(),
                        profile.base_url.as_deref(),
                    );
                profile.provider == provider
                    && profile.model == model
                    && current_base_url == base_url
                    && profile.fallback.is_empty()
                    && topology == "backend_proxied"
            })
            && crate::magician_v2::apps::processing_boundary::current_realtime_voice_provider_grant(
                &config,
                profile_name,
                Utc::now(),
            )
            .is_ok()
    }

    /// Re-open the live operator trust catalog for the exact backend-proxied
    /// realtime route carried by a server-only owner credential.
    pub fn revalidate_realtime_voice_owner_credential(
        &self,
        credential: &crate::magician_v2::apps::boundary::AppOwnerExecutionCredential,
    ) -> bool {
        let Some(resources) = self
            .scoped_capability_resolver
            .as_ref()
            .and_then(|resolver| resolver.agent_resources())
        else {
            return false;
        };
        let Some((voice_session_id, profile_name, _, _, _, _, storage_policy, _)) =
            credential.realtime_physical_binding()
        else {
            return false;
        };
        let config = resources.magician_config_snapshot();
        let Some(profile) = config
            .llm
            .router
            .as_ref()
            .and_then(|router| router.realtime_voice.profiles.get(profile_name))
        else {
            return false;
        };
        let Some(effective_base_url) =
            crate::magician_v2::apps::processing_boundary::effective_realtime_voice_base_url(
                profile.provider.as_str(),
                profile.base_url.as_deref(),
            )
        else {
            return false;
        };
        credential
            .ensure_realtime_physical_route(
                voice_session_id,
                profile_name,
                &profile.provider,
                &profile.model,
                Some(effective_base_url),
                "backend_proxied",
                storage_policy,
                Utc::now(),
            )
            .is_ok()
            && crate::magician_v2::apps::processing_boundary::current_realtime_voice_provider_grant(
                &config,
                profile_name,
                Utc::now(),
            )
            .is_ok()
    }
}

impl crate::magician_v2::apps::boundary::AppRealtimeVoiceRouteAuthorizer for ChatService {
    fn ensure_current_realtime_voice_route(
        &self,
        credential: &crate::magician_v2::apps::boundary::AppOwnerExecutionCredential,
        _now: DateTime<Utc>,
    ) -> bool {
        self.revalidate_realtime_voice_owner_credential(credential)
    }
}

