#[derive(Serialize)]
struct ChatPromptDumpSizes {
    system_prompt_chars: usize,
    history_chars: usize,
    tool_specs_chars: usize,
    total_chars: usize,
    message_count: usize,
    tool_count: usize,
}

#[derive(Serialize)]
struct ChatPromptDumpInput {
    chat_turn_id: String,
    session_id: String,
    principal: String,
    workspace: String,
    agent_id: String,
    model: Option<String>,
    iteration: usize,
    error: Option<String>,
    sizes: ChatPromptDumpSizes,
    system_prompt: String,
    history: Vec<ChatLlmTranscriptEntry>,
    tool_specs: Vec<LLMToolSpec>,
}

#[derive(Serialize)]
struct ChatPromptDumpOmission {
    chat_turn_id: String,
    session_id: String,
    principal: String,
    workspace: String,
    agent_id: String,
    model: Option<String>,
    iteration: usize,
    error: Option<String>,
    sizes: ChatPromptDumpSizes,
    full_payload_omitted: bool,
    omission_reason: String,
}

impl ChatPromptDumpInput {
    #[allow(clippy::too_many_arguments)]
    fn from_owned(
        session: &ChatSession,
        agent_id: &str,
        chat_turn_id: &str,
        iteration: usize,
        profile: Option<&str>,
        system_prompt: String,
        history: Vec<ChatLlmTranscriptEntry>,
        tool_specs: Vec<LLMToolSpec>,
        system_prompt_chars: usize,
        history_chars: usize,
        tool_specs_chars: usize,
        total_chars: usize,
        error: Option<String>,
    ) -> Self {
        let message_count = history.len();
        let tool_count = tool_specs.len();
        Self {
            chat_turn_id: chat_turn_id.to_string(),
            session_id: session.id.clone(),
            principal: session.principal.clone(),
            workspace: session.workspace.clone(),
            agent_id: agent_id.to_string(),
            model: profile.map(str::to_string),
            iteration,
            error,
            sizes: ChatPromptDumpSizes {
                system_prompt_chars,
                history_chars,
                tool_specs_chars,
                total_chars,
                message_count,
                tool_count,
            },
            system_prompt,
            history,
            tool_specs,
        }
    }

    fn omission(&self, reason: &str) -> ChatPromptDumpOmission {
        ChatPromptDumpOmission {
            chat_turn_id: bounded_chat_prompt_dump_text(&self.chat_turn_id, 512),
            session_id: bounded_chat_prompt_dump_text(&self.session_id, 512),
            principal: bounded_chat_prompt_dump_text(&self.principal, 512),
            workspace: bounded_chat_prompt_dump_text(&self.workspace, 512),
            agent_id: bounded_chat_prompt_dump_text(&self.agent_id, 512),
            model: self
                .model
                .as_deref()
                .map(|value| bounded_chat_prompt_dump_text(value, 512)),
            iteration: self.iteration,
            error: self.error.as_deref().map(|value| {
                bounded_chat_prompt_dump_text(value, MAX_CHAT_PROMPT_DUMP_ERROR_BYTES)
            }),
            sizes: ChatPromptDumpSizes {
                system_prompt_chars: self.sizes.system_prompt_chars,
                history_chars: self.sizes.history_chars,
                tool_specs_chars: self.sizes.tool_specs_chars,
                total_chars: self.sizes.total_chars,
                message_count: self.sizes.message_count,
                tool_count: self.sizes.tool_count,
            },
            full_payload_omitted: true,
            omission_reason: bounded_chat_prompt_dump_text(reason, 2_048),
        }
    }
}

fn bounded_chat_prompt_dump_text(value: &str, max_bytes: usize) -> String {
    if value.len() <= max_bytes {
        return value.to_string();
    }
    let boundary = value
        .char_indices()
        .take_while(|(index, _)| *index <= max_bytes)
        .map(|(index, _)| index)
        .last()
        .unwrap_or(0);
    value[..boundary].to_string()
}

fn chat_success_prompt_dumps_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var(CHAT_SUCCESS_PROMPT_DUMPS_ENV)
            .ok()
            .is_some_and(|value| {
                matches!(
                    value.trim().to_ascii_lowercase().as_str(),
                    "1" | "true" | "yes" | "on"
                )
            })
    })
}

fn build_success_chat_prompt_dump_if_enabled<T>(
    enabled: bool,
    build: impl FnOnce() -> Option<T>,
) -> Option<T> {
    enabled.then(build).flatten()
}

fn admit_chat_prompt_dump_json(value: &Value, remaining_nodes: &mut usize) -> bool {
    let Some(metrics) = inspect_json_bounded(value, *remaining_nodes) else {
        return false;
    };
    if metrics.max_depth > MAX_CHAT_PROMPT_DUMP_JSON_DEPTH {
        return false;
    }
    *remaining_nodes = remaining_nodes.saturating_sub(metrics.nodes);
    true
}

fn chat_prompt_dump_values_are_bounded(
    history: &[ChatLlmTranscriptEntry],
    tool_specs: &[LLMToolSpec],
) -> bool {
    let mut remaining_nodes = MAX_CHAT_PROMPT_DUMP_JSON_NODES;
    for spec in tool_specs {
        if !admit_chat_prompt_dump_json(&spec.parameters, &mut remaining_nodes) {
            return false;
        }
    }
    for entry in history {
        match entry {
            ChatLlmTranscriptEntry::AssistantTurn {
                tool_calls,
                provider_state,
                ..
            } => {
                if tool_calls
                    .iter()
                    .any(|call| !admit_chat_prompt_dump_json(&call.arguments, &mut remaining_nodes))
                {
                    return false;
                }
                let native_values = match provider_state {
                    Some(AssistantProviderState::Gemini { parts }) => Some(parts.as_slice()),
                    Some(AssistantProviderState::AnthropicMessages { content }) => {
                        Some(content.as_slice())
                    },
                    _ => None,
                };
                if native_values.is_some_and(|values| {
                    values
                        .iter()
                        .any(|value| !admit_chat_prompt_dump_json(value, &mut remaining_nodes))
                }) {
                    return false;
                }
            },
            ChatLlmTranscriptEntry::ToolResultProjected { projection, .. } => {
                if !admit_chat_prompt_dump_json(&projection.model.value, &mut remaining_nodes) {
                    return false;
                }
                let display_value = match &projection.display {
                    crate::magician_v2::tool_result_projection::DisplayResultProjection::Inline {
                        value,
                        ..
                    }
                    | crate::magician_v2::tool_result_projection::DisplayResultProjection::InlineAndReferenced {
                        value,
                        ..
                    } => Some(value),
                    crate::magician_v2::tool_result_projection::DisplayResultProjection::Referenced {
                        ..
                    } => None,
                };
                if display_value
                    .is_some_and(|value| !admit_chat_prompt_dump_json(value, &mut remaining_nodes))
                {
                    return false;
                }
            },
            _ => {},
        }
    }
    true
}

fn discard_chat_prompt_dump_input_iteratively(mut input: ChatPromptDumpInput) {
    for spec in &mut input.tool_specs {
        discard_json_iteratively(std::mem::take(&mut spec.parameters));
    }
    for entry in &mut input.history {
        match entry {
            ChatLlmTranscriptEntry::AssistantTurn {
                tool_calls,
                provider_state,
                ..
            } => {
                for call in tool_calls {
                    discard_json_iteratively(std::mem::take(&mut call.arguments));
                }
                match provider_state {
                    Some(AssistantProviderState::Gemini { parts }) => {
                        for value in parts.drain(..) {
                            discard_json_iteratively(value);
                        }
                    },
                    Some(AssistantProviderState::AnthropicMessages { content }) => {
                        for value in content.drain(..) {
                            discard_json_iteratively(value);
                        }
                    },
                    _ => {},
                }
            },
            ChatLlmTranscriptEntry::ToolResultProjected { projection, .. } => {
                discard_json_iteratively(std::mem::take(&mut projection.model.value));
                match &mut projection.display {
                    crate::magician_v2::tool_result_projection::DisplayResultProjection::Inline {
                        value,
                        ..
                    }
                    | crate::magician_v2::tool_result_projection::DisplayResultProjection::InlineAndReferenced {
                        value,
                        ..
                    } => discard_json_iteratively(std::mem::take(value)),
                    crate::magician_v2::tool_result_projection::DisplayResultProjection::Referenced {
                        ..
                    } => {},
                }
            },
            _ => {},
        }
    }
}

async fn persist_chat_prompt_dump(
    workspace: ArtifactV2Workspace,
    path: PathBuf,
    input: ChatPromptDumpInput,
) -> Result<PathBuf, ArtifactV2Error> {
    persist_chat_prompt_dump_with_limits(
        workspace,
        path,
        input,
        MAX_CHAT_PROMPT_DUMP_BYTES,
        MAX_CHAT_PROMPT_DUMP_FALLBACK_BYTES,
    )
    .await
}

async fn persist_chat_prompt_dump_with_limits(
    workspace: ArtifactV2Workspace,
    path: PathBuf,
    input: ChatPromptDumpInput,
    max_full_bytes: usize,
    max_fallback_bytes: usize,
) -> Result<PathBuf, ArtifactV2Error> {
    let omission = input.omission("full prompt exceeded JSON depth or node safety limits");
    if !chat_prompt_dump_values_are_bounded(&input.history, &input.tool_specs) {
        discard_chat_prompt_dump_input_iteratively(input);
        workspace
            .write_json_value_atomic_stream_path(&path, omission, max_fallback_bytes)
            .await?;
        return Ok(path);
    }

    if let Err(error) = workspace
        .write_json_value_atomic_stream_path(&path, input, max_full_bytes)
        .await
    {
        let mut omission = omission;
        omission.omission_reason = bounded_chat_prompt_dump_text(
            &format!("full prompt dump was not persisted: {error}"),
            2_048,
        );
        workspace
            .write_json_value_atomic_stream_path(&path, omission, max_fallback_bytes)
            .await?;
    }
    Ok(path)
}

/// Hard cap on tool-call iterations within a single chat turn. Set high enough
/// to let a turn chain many tools inline, but still bounded as a runaway guard
/// so the LLM eventually converges to a final text reply even if it loops on
/// the same kind of action. Deep multi-step work should still become a task
/// (its own larger iteration budget + async, resumable progress) rather than
/// grinding synchronously inside one chat turn.
const CHAT_INLINE_MAX_TOOL_LOOP: usize = 50;
const CHAT_INLINE_MAX_TUTOR_CONTINUATION_GUARDS: usize = 2;
