fn choose_fair_ready_queue_index<'a, F>(
    ready_indices: &[usize],
    last_contact_key: Option<&str>,
    mut contact_key_for_index: F,
) -> Option<usize>
where
    F: FnMut(usize) -> &'a str,
{
    if ready_indices.is_empty() {
        return None;
    }
    if let Some(last_contact_key) = last_contact_key {
        if let Some(index) = ready_indices
            .iter()
            .copied()
            .find(|index| contact_key_for_index(*index) != last_contact_key)
        {
            return Some(index);
        }
    }
    ready_indices.first().copied()
}

