impl PublicChatAdmissionManager {
    fn new(policy: PublicChatPolicyConfig) -> Self {
        let paid_semaphore = Arc::new(Semaphore::new(policy.max_paid_concurrent));
        let fallback_semaphore = Arc::new(Semaphore::new(policy.max_fallback_concurrent));
        let first_contact_paid_semaphore = Arc::new(Semaphore::new(
            policy
                .first_contact
                .as_ref()
                .map(|first_contact| first_contact.max_paid_concurrent)
                .unwrap_or(policy.max_paid_concurrent),
        ));
        let daily_reset_timezone = policy
            .daily_paid_limit
            .reset_timezone
            .trim()
            .parse::<chrono_tz::Tz>()
            .unwrap_or(chrono_tz::UTC);
        Self {
            policy,
            paid_semaphore,
            fallback_semaphore,
            first_contact_paid_semaphore,
            daily_reset_timezone,
            daily_ledger: StdMutex::new(PublicChatDailyLedger::default()),
        }
    }

    fn admit(
        self: &Arc<Self>,
        paid_operation_override: Option<&str>,
        first_contact_paid: bool,
    ) -> PublicChatAdmissionDecision {
        let first_contact_permit = if first_contact_paid {
            match self
                .first_contact_paid_semaphore
                .clone()
                .try_acquire_owned()
            {
                Ok(permit) => Some(permit),
                Err(_) => {
                    return self
                        .try_fallback("first_contact_concurrency")
                        .unwrap_or_else(|| self.reject("first_contact_capacity"));
                },
            }
        } else {
            None
        };

        match self.paid_semaphore.clone().try_acquire_owned() {
            Ok(semaphore_permit) => {
                if let Some(reason) = self.try_reserve_paid_call() {
                    return self
                        .try_fallback(reason)
                        .unwrap_or_else(|| self.reject("fallback_capacity"));
                }
                let operation = paid_operation_override
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .unwrap_or(&self.policy.paid_operation)
                    .to_string();
                PublicChatAdmissionDecision::Run {
                    operation,
                    route: PublicChatAdmissionRoute::Paid,
                    permit: PublicChatAdmissionPermit {
                        manager: Arc::clone(self),
                        route: PublicChatAdmissionRoute::Paid,
                        _semaphore_permit: semaphore_permit,
                        _first_contact_permit: first_contact_permit,
                        reserved_paid_call: true,
                        committed: false,
                    },
                }
            },
            Err(_) => self
                .try_fallback("paid_concurrency")
                .unwrap_or_else(|| self.reject("capacity")),
        }
    }

    fn try_fallback(self: &Arc<Self>, reason: &'static str) -> Option<PublicChatAdmissionDecision> {
        let semaphore_permit = self.fallback_semaphore.clone().try_acquire_owned().ok()?;
        tracing::debug!(
            reason,
            operation = %self.policy.fallback_operation,
            "[PUBLIC-CHAT] admitted fallback turn"
        );
        Some(PublicChatAdmissionDecision::Run {
            operation: self.policy.fallback_operation.clone(),
            route: PublicChatAdmissionRoute::Fallback,
            permit: PublicChatAdmissionPermit {
                manager: Arc::clone(self),
                route: PublicChatAdmissionRoute::Fallback,
                _semaphore_permit: semaphore_permit,
                _first_contact_permit: None,
                reserved_paid_call: false,
                committed: true,
            },
        })
    }

    fn reject(&self, reason: &'static str) -> PublicChatAdmissionDecision {
        PublicChatAdmissionDecision::Reject {
            notice: self.policy.overload_reply.clone(),
            template_allowed: matches!(
                self.policy
                    .outside_window_template_policy
                    .queued_and_overload,
                PublicChatTemplatePolicy::Allow
            ),
            reason: reason.to_string(),
        }
    }

    fn try_reserve_paid_call(&self) -> Option<&'static str> {
        let mut ledger = self.daily_ledger.lock().unwrap_or_else(|e| e.into_inner());
        self.refresh_ledger_day(&mut ledger);
        if ledger.paid_calls >= self.policy.daily_paid_limit.max_calls {
            return Some("daily_calls");
        }
        if ledger.paid_tokens >= self.policy.daily_paid_limit.max_tokens {
            return Some("daily_tokens");
        }
        if ledger.paid_cost_unknown {
            return Some("unreported_cost");
        }
        if ledger.paid_cost_usd >= self.policy.daily_paid_limit.max_cost_usd {
            return Some("daily_cost");
        }
        ledger.paid_calls = ledger.paid_calls.saturating_add(1);
        None
    }

    fn rollback_paid_call(&self) {
        let mut ledger = self.daily_ledger.lock().unwrap_or_else(|e| e.into_inner());
        self.refresh_ledger_day(&mut ledger);
        ledger.paid_calls = ledger.paid_calls.saturating_sub(1);
    }

    fn commit_paid_usage(&self, usage: Option<&ChatTurnUsage>) {
        let mut ledger = self.daily_ledger.lock().unwrap_or_else(|e| e.into_inner());
        self.refresh_ledger_day(&mut ledger);
        if let Some(usage) = usage {
            ledger.paid_tokens = ledger
                .paid_tokens
                .saturating_add(u64::from(usage.total_tokens));
            // Unknown spend blocks further paid admission without inventing
            // a dollar amount; the configured fallback can still answer.
            if let Some(cost) = usage
                .cost_usd
                .filter(|cost| cost.is_finite() && *cost >= 0.0)
            {
                ledger.paid_cost_usd += cost;
            } else {
                ledger.paid_cost_unknown = true;
            }
        }
    }

    fn refresh_ledger_day(&self, ledger: &mut PublicChatDailyLedger) {
        let day_key = self.current_day_key();
        if ledger.day_key != day_key {
            *ledger = PublicChatDailyLedger {
                day_key,
                paid_calls: 0,
                paid_tokens: 0,
                paid_cost_usd: 0.0,
                paid_cost_unknown: false,
            };
        }
    }

    fn current_day_key(&self) -> String {
        Utc::now()
            .with_timezone(&self.daily_reset_timezone)
            .date_naive()
            .to_string()
    }

    fn ledger_snapshot(&self) -> PublicChatDailyLedger {
        let mut ledger = self.daily_ledger.lock().unwrap_or_else(|e| e.into_inner());
        self.refresh_ledger_day(&mut ledger);
        ledger.clone()
    }

    fn restore_ledger(&self, ledger: PublicChatDailyLedger) {
        let mut current = self.daily_ledger.lock().unwrap_or_else(|e| e.into_inner());
        *current = ledger;
        self.refresh_ledger_day(&mut current);
    }

    fn snapshot(&self) -> PublicChatAdmissionSnapshot {
        let mut ledger = self.daily_ledger.lock().unwrap_or_else(|e| e.into_inner());
        self.refresh_ledger_day(&mut ledger);
        let max_first_contact_paid_concurrent = self
            .policy
            .first_contact
            .as_ref()
            .map(|first_contact| first_contact.max_paid_concurrent)
            .unwrap_or(self.policy.max_paid_concurrent);
        let fallback_reason = if ledger.paid_calls >= self.policy.daily_paid_limit.max_calls {
            Some("daily_calls".to_string())
        } else if ledger.paid_tokens >= self.policy.daily_paid_limit.max_tokens {
            Some("daily_tokens".to_string())
        } else if ledger.paid_cost_unknown {
            Some("unreported_cost".to_string())
        } else if ledger.paid_cost_usd >= self.policy.daily_paid_limit.max_cost_usd {
            Some("daily_cost".to_string())
        } else {
            None
        };
        let paid_available = self.paid_semaphore.available_permits();
        let fallback_available = self.fallback_semaphore.available_permits();
        let first_contact_paid_available = self.first_contact_paid_semaphore.available_permits();
        PublicChatAdmissionSnapshot {
            max_paid_concurrent: self.policy.max_paid_concurrent,
            paid_available,
            paid_in_use: self
                .policy
                .max_paid_concurrent
                .saturating_sub(paid_available),
            max_fallback_concurrent: self.policy.max_fallback_concurrent,
            fallback_available,
            fallback_in_use: self
                .policy
                .max_fallback_concurrent
                .saturating_sub(fallback_available),
            max_first_contact_paid_concurrent,
            first_contact_paid_available,
            first_contact_paid_in_use: max_first_contact_paid_concurrent
                .saturating_sub(first_contact_paid_available),
            day_key: ledger.day_key.clone(),
            paid_calls: ledger.paid_calls,
            paid_calls_limit: self.policy.daily_paid_limit.max_calls,
            paid_tokens: ledger.paid_tokens,
            paid_tokens_limit: self.policy.daily_paid_limit.max_tokens,
            paid_cost_usd: (!ledger.paid_cost_unknown).then_some(ledger.paid_cost_usd),
            paid_cost_limit_usd: self.policy.daily_paid_limit.max_cost_usd,
            fallback_reason,
        }
    }
}

impl PublicChatAdmissionPermit {
    fn commit_usage(&mut self, usage: Option<&ChatTurnUsage>) {
        if self.route == PublicChatAdmissionRoute::Paid && self.reserved_paid_call {
            self.manager.commit_paid_usage(usage);
        }
        self.committed = true;
    }
}

impl Drop for PublicChatAdmissionPermit {
    fn drop(&mut self) {
        if self.route == PublicChatAdmissionRoute::Paid
            && self.reserved_paid_call
            && !self.committed
        {
            self.manager.rollback_paid_call();
        }
    }
}

