/// Assemble a [`CatalogBuildContext`] from an agent definition's tool list and
/// delegation targets. The chat-mode catalog reuses
/// [`build_execution_native_catalog`] under `is_chat_mode: true` so common
/// metadata fields are stripped and Phase 2.5 chat-only tools are included.
///
/// Each resolved agent tool (explicit grant or trust-aware universal pack) is
/// exposed with its real parameter schema (sourced from
/// `CapabilityRegistry::get_pack_definition`) so the LLM can pass the user's
/// prompt / query / etc. directly. When a pack
/// definition isn't loaded into the registry yet (e.g., not-yet-hot-reloaded
/// or compiled-but-undeclared), we fall back to a permissive object schema
/// so the LLM can still emit args; a registered pack overrides this on the
/// next request. Task-backed non-compiled packs also get the chat-owned
/// `reference_task_ids` control field because they route through
/// `dispatch_capability_pack` and create internal task shells. Chat-local
/// transports such as screen draw deliberately omit that task-only field.
fn chat_inline_adapter_for_tool(
    registry: Option<&CapabilityRegistry>,
    tool_name: &str,
) -> Option<ChatInlineAdapter> {
    registry?
        .resolve_tool_definition(tool_name)
        .and_then(|resolved| resolved.definition.execution)
        .and_then(|metadata| metadata.chat_inline_adapter)
}

fn chat_inline_pack_names(
    registry: &CapabilityRegistry,
    adapter: ChatInlineAdapter,
) -> Vec<String> {
    let mut names = registry
        .all_pack_definitions()
        .into_iter()
        .filter(|definition| {
            definition
                .execution
                .as_ref()
                .and_then(|metadata| metadata.chat_inline_adapter)
                == Some(adapter)
        })
        .map(|definition| definition.name)
        .collect::<Vec<_>>();
    names.sort();
    names.dedup();
    names
}

fn chat_inline_leaf_names(
    capability_snapshot: &ScopedCapabilitySnapshot,
    adapter: ChatInlineAdapter,
) -> HashSet<String> {
    chat_inline_pack_names(capability_snapshot.registry.as_ref(), adapter)
        .into_iter()
        .flat_map(|pack_name| {
            let leaves = capability_snapshot
                .surface_tool_index
                .leaf_names_for_pack(&pack_name);
            if leaves.is_empty() {
                vec![pack_name]
            } else {
                leaves
            }
        })
        .collect()
}

fn build_chat_catalog_context(
    agent_tools: &[String],
    delegation_targets: &[String],
    capability_registry: Option<&CapabilityRegistry>,
) -> CatalogBuildContext {
    let direct_capabilities = agent_tools
        .iter()
        .filter(|name| !name.trim().is_empty())
        .map(|name| {
            let resolved_pack =
                capability_registry.and_then(|registry| registry.resolve_tool_definition(name));
            let pack = resolved_pack.as_ref().map(|resolved| &resolved.definition);
            let accepts_reference_task_ids =
                chat_inline_adapter_for_tool(capability_registry, name).is_none()
                    && !matches!(
                        pack.map(|p| &p.implementation),
                        Some(ImplementationType::Compiled { .. })
                    );
            let mut description = pack
                .and_then(|p| p.description.clone())
                .unwrap_or_else(|| format!("Capability pack `{name}`."));
            let mut schema = pack
                .map(|p| pack_parameters_to_schema(&p.parameters))
                .unwrap_or_else(|| {
                    serde_json::json!({
                        "type": "object",
                        "properties": {},
                        "additionalProperties": true,
                    })
                });
            if accepts_reference_task_ids {
                add_chat_internal_task_reference_schema(&mut schema);
                description = append_chat_internal_task_reference_description(&description);
            }
            (name.clone(), description, schema)
        })
        .collect();
    let has_delegation_targets = !delegation_targets.is_empty()
        && delegation_targets
            .iter()
            .any(|target| !target.trim().is_empty());
    CatalogBuildContext {
        allowed_action_types: None,
        credentials_enabled: true,
        has_delegation_targets,
        direct_capabilities,
        // BUG-4 / BUG-8: chat path. Schema-strip + Phase 2.5 chat-only tools
        // included.
        is_chat_mode: true,
        // Procedure-skill availability is enriched after this projection from
        // the workspace catalogue. The compiled activate/deactivate providers
        // are already present in `direct_capabilities`; leave this native-only
        // hint empty so it cannot introduce a second registration.
        available_procedure_skills: Vec::new(),
        denied_tool_names: Vec::new(),
        // FIX #4: chat is never a VibeDev coding-coordinator run (coordinators
        // run task-backed, not chat-inline), so the grant gate is always off here.
        delegate_only_grant_gate: None,
    }
}

fn add_chat_internal_task_reference_schema(schema: &mut Value) {
    let Some(obj) = schema.as_object_mut() else {
        *schema = json!({
            "type": "object",
            "properties": {
                "reference_task_ids": chat_internal_task_reference_ids_schema(),
            },
            "required": [],
            "additionalProperties": false
        });
        return;
    };
    obj.entry("type".to_string())
        .or_insert_with(|| json!("object"));
    let props_value = obj
        .entry("properties".to_string())
        .or_insert_with(|| json!({}));
    if !props_value.is_object() {
        *props_value = json!({});
    }
    if let Some(props) = props_value.as_object_mut() {
        props
            .entry("reference_task_ids".to_string())
            .or_insert_with(chat_internal_task_reference_ids_schema);
    }
}

fn chat_internal_task_reference_ids_schema() -> Value {
    json!({
        "type": "array",
        "items": {"type": "string"},
        "description": "Completed task ids whose outputs/artifacts should seed this chat-owned internal task. Use for continuation work after get_task_details confirms the source task is completed."
    })
}

fn append_chat_internal_task_reference_description(description: &str) -> String {
    format!(
        "{} Optional: for continuation work, pass completed source task ids in \
         `reference_task_ids` so the chat-owned internal task receives the prior continuation \
         pack/artifact index.",
        description.trim_end()
    )
}

/// Convert a pack's [`ParameterDef`] list to the JSON Schema shape the LLM
/// tool catalog uses. Mirrors
/// Build the chat-mode JSON Schema for a pack's parameter list. Each
/// parameter's canonical `schema` field is the source of truth; we just
/// gather them under a parent object and attach the `required` array. The
/// `schema` field is always populated by `ParameterDef`'s custom Deserialize
/// (either taken verbatim from the YAML's `schema:` block, or synthesized
/// from the legacy shorthand fields). In-memory literals built outside the
/// YAML loader may have `schema: Value::Null`; in that case we fall back to
/// the legacy derivation so the LLM still gets a usable schema.
fn pack_parameters_to_schema(params: &[ParameterDef]) -> serde_json::Value {
    let mut properties = serde_json::Map::new();
    let mut required: Vec<String> = Vec::new();

    for param in params {
        let property = if param.schema.is_null() {
            crate::magician_v2::execution::capability::derive_param_schema_for_emission(param)
        } else {
            param.schema.clone()
        };
        properties.insert(param.name.clone(), property);
        if param.required {
            required.push(param.name.clone());
        }
    }

    let mut schema = serde_json::Map::new();
    schema.insert("type".to_string(), serde_json::json!("object"));
    schema.insert(
        "properties".to_string(),
        serde_json::Value::Object(properties),
    );
    if !required.is_empty() {
        schema.insert("required".to_string(), serde_json::json!(required));
    }
    serde_json::Value::Object(schema)
}

/// Trim a tool description to a short single line for the chat tool-catalog
/// presentation in the system prompt.
/// Output of `render_chat_outer_loop_prompt`. `system_prompt` is the
/// cache-stable system message; `dynamic_context` holds the per-turn
/// memory / procedure / delegate / file blocks the caller injects as a
/// first user-turn `<context>` envelope so they don't break the prefix
/// cache. `None` when every dynamic block is empty (cold session).
pub struct BuiltSystemPrompt {
    pub system_prompt: String,
    pub dynamic_context: Option<String>,
    pub memory_candidate_keys: Vec<String>,
    pub memory_candidates: Vec<crate::magician_v2::agents::MemoryPromptSelectedCandidate>,
    pub local_only_app_memory_rendered: bool,
}

struct ChatMemoryBlock {
    text: String,
    selected_candidate_keys: Vec<String>,
    selected_candidates: Vec<crate::magician_v2::agents::MemoryPromptSelectedCandidate>,
    index_query_ms: f64,
    user_render_ms: f64,
    agent_render_ms: f64,
    retrieval_backend: &'static str,
    local_only_app_memory_rendered: bool,
}

impl crate::magician_v2::context_retrieval::ContextContributionSource for ChatMemoryBlock {
    fn context_contributions(
        &self,
    ) -> Vec<crate::magician_v2::context_retrieval::ContextContributionDraft> {
        use crate::magician_v2::context_retrieval::{
            ContextContributionDraft, ContextEvidenceCompleteness, ContextEvidenceKey,
        };
        if self.selected_candidates.is_empty() {
            let text = self.text.trim();
            if text.is_empty() {
                return Vec::new();
            }
            let digest = blake3::hash(text.as_bytes()).to_hex().to_string();
            return vec![ContextContributionDraft {
                evidence_key: ContextEvidenceKey::new("memory-render", digest.clone()),
                text: text.to_string(),
                evidence_refs: Vec::new(),
                candidate_count: 0,
                retrieval_backend: self.retrieval_backend.to_string(),
                completeness: ContextEvidenceCompleteness::Complete,
                rank: 0,
            }];
        }
        self.selected_candidates
            .iter()
            .enumerate()
            .map(|(rank, candidate)| ContextContributionDraft {
                evidence_key: ContextEvidenceKey::new(
                    candidate.source_key.clone(),
                    candidate.source_text_hash.clone(),
                ),
                text: candidate.text.clone(),
                evidence_refs: candidate.source_ids.clone(),
                candidate_count: 1,
                retrieval_backend: self.retrieval_backend.to_string(),
                completeness: if candidate.projection_used {
                    ContextEvidenceCompleteness::Excerpt
                } else {
                    ContextEvidenceCompleteness::Complete
                },
                rank: u32::try_from(rank).unwrap_or(u32::MAX),
            })
            .collect()
    }
}

fn merge_fast_and_hybrid_memory_blocks(
    fast: Option<ChatMemoryBlock>,
    hybrid: Option<ChatMemoryBlock>,
) -> Option<ChatMemoryBlock> {
    let (fast, mut hybrid) = match (fast, hybrid) {
        (None, hybrid) => return hybrid,
        (fast, None) => return fast,
        (Some(fast), Some(hybrid)) => (fast, hybrid),
    };
    let mut known = hybrid
        .selected_candidate_keys
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let supplements = fast
        .selected_candidates
        .iter()
        .filter(|candidate| known.insert(candidate.memory_candidate_key.clone()))
        .cloned()
        .collect::<Vec<_>>();
    hybrid.local_only_app_memory_rendered =
        hybrid.local_only_app_memory_rendered || fast.local_only_app_memory_rendered;
    if !supplements.is_empty() {
        hybrid.text.push_str("\n\n<fast-memory-supplement>\n");
        for candidate in &supplements {
            hybrid.text.push_str("- ");
            hybrid.text.push_str(candidate.text.trim());
            hybrid.text.push('\n');
        }
        hybrid.text.push_str("</fast-memory-supplement>");
        hybrid.selected_candidate_keys.extend(
            supplements
                .iter()
                .map(|candidate| candidate.memory_candidate_key.clone()),
        );
        hybrid.selected_candidates.extend(supplements);
        hybrid.retrieval_backend = "lancedb_hybrid+fast_snapshot";
    }
    Some(hybrid)
}

struct ChatProcedureBlock {
    text: String,
    retrieval_backend: &'static str,
    selected_count: usize,
    candidate_count: usize,
}

impl crate::magician_v2::context_retrieval::ContextContributionSource for ChatProcedureBlock {
    fn context_contributions(
        &self,
    ) -> Vec<crate::magician_v2::context_retrieval::ContextContributionDraft> {
        use crate::magician_v2::context_retrieval::{
            ContextContributionDraft, ContextEvidenceCompleteness, ContextEvidenceKey,
        };
        let text = self.text.trim();
        if text.is_empty() {
            return Vec::new();
        }
        let digest = blake3::hash(text.as_bytes()).to_hex().to_string();
        vec![ContextContributionDraft {
            evidence_key: ContextEvidenceKey::new("procedure-render", digest.clone()),
            text: text.to_string(),
            evidence_refs: Vec::new(),
            candidate_count: self.candidate_count,
            retrieval_backend: self.retrieval_backend.to_string(),
            completeness: ContextEvidenceCompleteness::Complete,
            rank: 0,
        }]
    }
}

/// Concatenate the per-turn dynamic blocks into a single `<context>`
/// envelope. Returns `None` when nothing meaningful is present so the
/// caller can skip the injection entirely (saves one synthetic
/// `user → assistant("Understood.")` turn pair on cold sessions).
fn build_dynamic_context_block(
    delegate_targets_block: &str,
    memory_tiers_block: &str,
    procedure_memory_block: &str,
    environment_knowledge: &str,
    recent_session_files_block: &str,
) -> Option<String> {
    let mut sections: Vec<&str> = Vec::new();
    for block in [
        delegate_targets_block,
        memory_tiers_block,
        procedure_memory_block,
        environment_knowledge,
        recent_session_files_block,
    ] {
        let trimmed = block.trim();
        if !trimmed.is_empty() {
            sections.push(trimmed);
        }
    }
    if sections.is_empty() {
        return None;
    }
    let body = sections.join("\n\n");
    Some(format!("<context>\n{body}\n</context>"))
}

/// Prepend a dynamic-context block to the latest user-side turn in
/// `history`. Mutates in place. Used by the chat-inline +
/// delegate-for-voice paths to inject the per-turn `<context>` envelope
/// so it lands in the LLM call regardless of OpenAI Responses
/// continuation state.
///
/// Falls back to inserting a fresh `UserText` containing the context
/// block at the end of history when no user turn is present (cold
/// session bootstrap or post-tool-result iterations where the latest
/// entry is a `ToolResult`). The fallback case is rare in practice —
/// every chat turn begins with a user message — but keeps the call
/// site total without panicking on empty / unusual histories.
fn inject_dynamic_context_into_latest_user_turn(
    history: &mut Vec<ChatLlmTranscriptEntry>,
    context_block: &str,
) {
    if let Some(idx) = history.iter().rposition(|entry| {
        matches!(
            entry,
            ChatLlmTranscriptEntry::UserText { .. } | ChatLlmTranscriptEntry::UserTurn { .. }
        )
    }) {
        match &mut history[idx] {
            ChatLlmTranscriptEntry::UserText { text } => {
                *text = format!("{context_block}\n\n{text}");
            },
            ChatLlmTranscriptEntry::UserTurn { content } => {
                content.insert(
                    0,
                    TranscriptBlock::Text {
                        text: context_block.to_string(),
                    },
                );
            },
            _ => {},
        }
    } else {
        history.push(ChatLlmTranscriptEntry::UserText {
            text: context_block.to_string(),
        });
    }
}

fn tutor_quick_allowed_native_tools(
    draw_tool_names: &HashSet<String>,
    is_app_copilot: bool,
) -> HashSet<String> {
    let mut allowed = draw_tool_names.clone();
    if is_app_copilot {
        allowed.insert("delegate_to_agent".to_string());
    }
    allowed
}

fn tutor_quick_allowed_chat_tools(is_app_copilot: bool) -> &'static [&'static str] {
    if is_app_copilot {
        APP_COPILOT_QUICK_CHAT_TOOLS
    } else {
        TUTOR_QUICK_CHAT_TOOLS
    }
}

#[cfg(any(test, feature = "test-fixtures"))]
fn retain_tutor_quick_native_tools(
    tools: &mut Vec<NativeExecutionTool>,
    draw_tool_names: &HashSet<String>,
    is_app_copilot: bool,
) -> usize {
    let before = tools.len();
    let allowed = tutor_quick_allowed_native_tools(draw_tool_names, is_app_copilot);
    tools.retain(|tool| allowed.contains(&tool.name));
    before.saturating_sub(tools.len())
}

fn retain_tutor_quick_chat_tool_specs(specs: &mut Vec<LLMToolSpec>, is_app_copilot: bool) -> usize {
    let before = specs.len();
    let allowed = tutor_quick_allowed_chat_tools(is_app_copilot);
    specs.retain(|spec| allowed.contains(&spec.name.as_str()));
    before.saturating_sub(specs.len())
}

fn is_tutor_chat_runtime_tool_name(name: &str) -> bool {
    TUTOR_CHAT_RUNTIME_TOOL_NAMES.contains(&name)
}

fn retain_tutor_runtime_tools_for_current_turn(
    specs: &mut Vec<LLMToolSpec>,
    feature_mode: crate::magician_v2::agents::FeatureMode,
) -> usize {
    if lane_keeps_tutor_runtime_tools(feature_mode) {
        return 0;
    }
    let before = specs.len();
    specs.retain(|spec| !is_tutor_chat_runtime_tool_name(&spec.name));
    before.saturating_sub(specs.len())
}

/// Resolve the chat-owned runtime surface once, with the same trust, deny and
/// current-turn Tutor gates for typed chat, realtime voice catalogues, and
/// external voice dispatch. Keeping this projection shared is important: a
/// tool omitted from the provider catalogue must also be absent from the
/// deterministic dispatch ceiling reconstructed by external surfaces.
fn chat_runtime_tool_specs_for_turn(
    tools: &[Arc<dyn ChatRuntimeTool>],
    definition: Option<&crate::magician_v2::agents::types::AgentDefinition>,
    feature_mode: crate::magician_v2::agents::FeatureMode,
) -> (Vec<LLMToolSpec>, usize) {
    let Some(definition) = definition else {
        return (Vec::new(), 0);
    };
    let mut specs = tools
        .iter()
        .filter(|tool| chat_runtime_tool_is_allowed(definition, tool.name()))
        .map(|tool| tool.to_tool_spec())
        .collect();
    let tutor_tools_dropped = retain_tutor_runtime_tools_for_current_turn(&mut specs, feature_mode);
    (specs, tutor_tools_dropped)
}

/// Governed trace lineage for one inline chat turn.
///
/// Every fact the turn produces — the logical call, its provider attempts, and
/// each tool execution — is stamped from THIS context, so anything left unset
/// here is unset everywhere downstream.
///
/// `execution_id` is stamped here rather than left for the activation layer to
/// backfill from the `LLMResponseReceived` event. That backfill
/// (`assert_or_fill_lineage`) only ever sees the call event, so the call fact
/// silently acquired the chat-turn id while every tool fact from the same turn
/// kept `NULL`. The read service's cross-dataset integrity guard requires tool
/// rows and their owning call to agree on every shared context column, so the
/// asymmetry failed EVERY governed LLM read (`/llm` capture health and call/
/// tool lineage both 400'd) until the drift was repaired.
///
/// An inline chat turn has no task execution of its own, so the chat turn id is
/// the execution identity — the same value the turn already broadcasts as
/// `execution_id` on its runtime events.
fn chat_turn_trace_context(
    principal: &str,
    workspace: &str,
    chat_session_id: &str,
    chat_turn_id: &str,
    user_message_id: Option<String>,
) -> magicllm::LlmTraceContext {
    let mut context = magicllm::LlmTraceContext::new(
        magicllm::LlmScope::new(principal, workspace),
        magicllm::LlmWorkloadClass::ForegroundChat,
    );
    context.trace_id = chat_turn_id.to_string();
    context.chat_session_id = Some(chat_session_id.to_string());
    context.chat_turn_id = Some(chat_turn_id.to_string());
    context.execution_id = Some(chat_turn_id.to_string());
    context.user_message_id = user_message_id;
    if context.activity_id.is_none() {
        context.set_activity_id(current_activity_id().map(|id| id.to_string()));
    }
    context
}

/// The one `source_surface` value that marks a room. Produced server-side by
/// `voice_source_surface` from a registered `SurfaceType::MeetingBot` session.
///
/// A client *may* send it and will get the meeting surface — that is a
/// **narrowing**, and the design permits narrowing by request because it can
/// only ever restrict the caller. What no label may do is the reverse: escape a
/// room onto an owner surface. That is the property the tests assert.
pub const MEETING_ROOM_SOURCE_SURFACE: &str = "meeting_room";

/// `shared_room` is **server-derived and trusted**, exactly like `public_envoy`
/// beside it. It must never be computed from `source_surface`, `ui_thread_id`,
/// a display label, or anything else the caller can assert: a room is the one
/// audience where the speaker is not known to be the owner, so a label that
/// could mint it would be an authority a stranger controls.
///
/// See [OPC · Outward Agent Boundary](../../../../docs/plans/2026-08-07-opc-outward-agent-boundary.md).
fn chat_invocation_context_for_turn(
    session: &ChatSession,
    source_surface: Option<&str>,
    current_user_text: Option<&str>,
    chat_turn_id: &str,
    _voice_origin: bool,
    public_envoy: bool,
    shared_room: bool,
) -> crate::magician_v2::agents::AgentInvocationContext {
    use crate::magician_v2::agents::{
        AgentInvocationContext, FeatureMode, InvocationSourceKind, InvocationSurface,
    };

    let normalized_surface = source_surface.unwrap_or_default().trim();
    // Product-lane admission lives behind the lane seam (plan 1.2):
    // Brainstorm's session-shape check, and the Tutor/App Copilot
    // conjunction of a recognized product-source label with an exact
    // leading invoke — a client-supplied label alone mints nothing. The
    // probe below names exactly the session and turn fields those
    // decisions read. The remaining arms in this chain stay inline until
    // their slice; VibeDev's invoke-grammar-driven arm below is one, and
    // the active-run continuation that may resume a started Tutor/App
    // Copilot lane without repeating the marker lives in the turn
    // handler, not here.
    let leading_feature = current_user_text
        .map(crate::magician_v2::execution::agentic::parse_leading_feature_invocation)
        .unwrap_or_default();
    let product_lane_admission =
        super::lane_seam::authenticated_product_lane(&super::lane_seam::LaneSessionProbe {
            surface_label: normalized_surface,
            agent_id: &session.agent_id,
            ui_thread_id: &session.ui_thread_id,
            origin_channel_type: &session.origin_channel.channel_type,
            origin_channel_address: session.origin_channel.address.as_deref(),
            leading_feature,
        });
    let (surface, feature_mode, source_kind) = if public_envoy {
        (
            InvocationSurface::PublicEnvoy,
            FeatureMode::None,
            InvocationSourceKind::Public,
        )
    } else if shared_room {
        // Second, and deliberately behind public envoy rather than ahead of it:
        // if a turn were somehow both, envoy is the stricter of the two (it is
        // tool-free by definition), and the fail-closed choice is the stricter
        // one. Everything below this arm — thinking map, tutor, app copilot,
        // vibedev, realtime voice — is unreachable in a room, which is the
        // point: a feature label spoken aloud by a participant must not select
        // a lane.
        (
            InvocationSurface::Meeting,
            FeatureMode::None,
            InvocationSourceKind::Public,
        )
    } else if let Some(admission) = product_lane_admission {
        (
            admission.surface,
            admission.feature_mode,
            admission.invocation_source_kind,
        )
    } else if leading_feature == FeatureMode::Vibedev {
        // The VibeDev rail owns no surface of its own: it rides an ordinary
        // conversation — typed, or spoken hands-free — and hands the work to a
        // task. Since plan 3.4 the triple this arm answers with is the seam's
        // (`vibedev::rail::rail_turn_lane`, with the full rationale in its
        // docs); what stays here is the arm's PLACE in the chain, and that
        // placement is load-bearing:
        //
        // **It sits BEFORE the realtime-voice arm, and that placement is the
        // whole of voice support.** While it sat after, a spoken invoke
        // classified as `RealtimeVoice`/`None` and never diverted; widening
        // `feature_surface_is_authorized` alone would not have changed that,
        // because the mode it authorizes was never minted. Moving the arm and
        // widening the predicate are one change, and either alone is a rail
        // that silently does nothing.
        //
        // Public envoy and shared rooms still win over this (their arms are
        // first), deliberately: a stranger on a public channel cannot start a
        // build no matter what they say. The session-admitted seam arm above
        // is unreachable from here anyway — `leading_feature` is a single
        // value and it is `Vibedev`.
        crate::magician_v2::vibedev::rail::rail_turn_lane(normalized_surface)
    } else if normalized_surface == "authenticated_realtime_voice" {
        (
            InvocationSurface::RealtimeVoice,
            FeatureMode::None,
            InvocationSourceKind::Direct,
        )
    } else {
        (
            InvocationSurface::Chat,
            FeatureMode::None,
            InvocationSourceKind::Direct,
        )
    };

    AgentInvocationContext {
        principal: session.principal.clone(),
        workspace: session.workspace.clone(),
        source_agent_id: None,
        target_agent_id: session.agent_id.clone(),
        surface,
        feature_mode,
        source_kind,
        chat_session_id: Some(session.id.clone()),
        chat_turn_id: Some(chat_turn_id.to_string()),
    }
}

fn chat_child_invocation_context(
    session: &ChatSession,
    source_agent_id: &str,
    target_agent_id: &str,
    surface: crate::magician_v2::agents::InvocationSurface,
    source_kind: crate::magician_v2::agents::InvocationSourceKind,
    chat_turn_id: Option<&str>,
) -> crate::magician_v2::agents::AgentInvocationContext {
    crate::magician_v2::agents::AgentInvocationContext {
        principal: session.principal.clone(),
        workspace: session.workspace.clone(),
        source_agent_id: Some(source_agent_id.to_string()),
        target_agent_id: target_agent_id.to_string(),
        surface,
        feature_mode: crate::magician_v2::agents::FeatureMode::None,
        source_kind,
        chat_session_id: Some(session.id.clone()),
        chat_turn_id: chat_turn_id.map(str::to_string),
    }
}

fn chat_sub_goal_invocation_context(
    session: &ChatSession,
    agent_id: &str,
    chat_turn_id: Option<&str>,
    policy_snapshot: Option<&crate::magician_v2::execution::agentic::EffectiveToolPolicySnapshot>,
) -> Result<crate::magician_v2::agents::AgentInvocationContext, String> {
    let snapshot = policy_snapshot.ok_or_else(|| "policy_snapshot_missing".to_string())?;
    if snapshot.agent_id != agent_id
        || snapshot.invocation.target_agent_id != agent_id
        || snapshot.invocation.principal != session.principal
        || snapshot.invocation.workspace != session.workspace
    {
        return Err("policy_snapshot_owner_scope_mismatch".to_string());
    }

    let mut invocation = snapshot.invocation.clone();
    invocation.chat_session_id = Some(session.id.clone());
    invocation.chat_turn_id = chat_turn_id.map(str::to_string);
    Ok(invocation)
}

fn delegated_introspection_invocation_context(
    session: &ChatSession,
    source_agent_id: &str,
    target_agent_id: &str,
    source_snapshot: Option<&crate::magician_v2::execution::agentic::EffectiveToolPolicySnapshot>,
) -> Result<crate::magician_v2::agents::AgentInvocationContext, String> {
    let snapshot = source_snapshot.ok_or_else(|| "policy_snapshot_missing".to_string())?;
    if snapshot.agent_id != source_agent_id
        || snapshot.invocation.target_agent_id != source_agent_id
        || snapshot.invocation.principal != session.principal
        || snapshot.invocation.workspace != session.workspace
        || !snapshot.permits_delegation_target(target_agent_id)
    {
        return Err("delegated_introspection_source_scope_mismatch".to_string());
    }

    Ok(crate::magician_v2::agents::AgentInvocationContext {
        principal: snapshot.invocation.principal.clone(),
        workspace: snapshot.invocation.workspace.clone(),
        source_agent_id: Some(source_agent_id.to_string()),
        target_agent_id: target_agent_id.to_string(),
        surface: crate::magician_v2::agents::InvocationSurface::Delegation,
        feature_mode: crate::magician_v2::agents::FeatureMode::None,
        source_kind: crate::magician_v2::agents::InvocationSourceKind::Delegated,
        chat_session_id: Some(session.id.clone()),
        chat_turn_id: snapshot.invocation.chat_turn_id.clone(),
    })
}

fn tutor_lane_exit_requested(text: Option<&str>) -> bool {
    let Some(normalized) = text
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_ascii_lowercase())
    else {
        return false;
    };
    const EXIT_PREFIXES: &[&str] = &[
        "@tutor stop",
        "@tutor exit",
        "@tutor end",
        "@copilot stop",
        "@copilot exit",
        "@copilot end",
        "@app-copilot stop",
        "@app-copilot exit",
        "@app-copilot end",
        "stop tutor",
        "exit tutor",
        "end tutor",
        "stop copilot",
        "exit copilot",
        "end copilot",
    ];
    EXIT_PREFIXES.iter().any(|prefix| {
        normalized == *prefix
            || normalized
                .strip_prefix(prefix)
                .and_then(|rest| rest.chars().next())
                .is_some_and(|ch| ch.is_whitespace() || ch == '.')
    })
}

fn compact_history_for_tutor_quick_path(history: &mut Vec<ChatLlmTranscriptEntry>) -> usize {
    let before = history.len();
    let Some(latest_user_idx) = history.iter().rposition(|entry| {
        matches!(
            entry,
            ChatLlmTranscriptEntry::UserText { .. } | ChatLlmTranscriptEntry::UserTurn { .. }
        )
    }) else {
        return 0;
    };
    if latest_user_idx > 0 {
        history.drain(0..latest_user_idx);
    }
    before.saturating_sub(history.len())
}

/// Build the UI task title for a chat-inline delegation. Mirrors the
/// runtime fallback format (`"{agent_id} / {summary}"`) but always uses
/// the clean `context_text`, so any caller-supplied personality directive
/// stays out of the task list — it still rides the goal description into
/// the LLM user prompt.
fn chat_delegate_task_title(target_agent_id: &str, context_text: &str) -> String {
    let summary = summarize_description(context_text);
    format!("{target_agent_id} / {summary}")
}

fn chat_running_task_status_message(
    session: &ChatSession,
    target_agent_id: &str,
    task_id: &str,
    execution_id: &str,
    chat_turn_id: Option<&str>,
) -> ChatMessage {
    ChatMessage::new(
        Uuid::new_v4().to_string(),
        session.id.clone(),
        ChatMessageDirection::System,
        ChatMessageContent::TaskStatusUpdate {
            task_id: task_id.to_string(),
            status: "running".to_string(),
            display_label: None,
            summary: Some(format!("{target_agent_id} is working…")),
            execution_id: Some(execution_id.to_string()),
            ui_thread_id: Some(session.ui_thread_id.clone()),
            output_files: Vec::new(),
            synthesis_pending: false,
            speech_tts: None,
        },
        Utc::now().timestamp_millis(),
    )
    // This card is the durable source used by the web reducer after the
    // assistant hand-off reply ends. Dropping the spawning turn here makes
    // a still-running delegation look terminal even though the live fanout
    // and progress subscription retain the same correlation.
    .with_chat_turn_id(chat_turn_id.map(str::to_string))
    .with_voice_origin(None)
    .with_speech_segments(None)
    .with_source_surface(None)
    .with_presence_session_id(None)
}

/// Identifying fields for a chat-inline delegate execution whose
/// terminal status row never made it into the per-turn projection.
/// Built by the bounded JSONL stream scanner from the latest
/// `chat.delegate.status_changed` row per `(task_id, execution_id)`
/// pair; the recovery sweep uses these to construct a synthetic
/// terminal event with the matching scope + agent metadata.
#[derive(Debug, Clone)]
struct OrphanDelegate {
    task_id: String,
    execution_id: String,
    /// Owning agent on the envelope of the last seen row — typically
    /// the chat session's agent (`personal-assistant`). Used as the
    /// `agent_id` on the synthetic envelope so it lands in the chat
    /// scope's events.jsonl correctly.
    owner_agent_id: Option<String>,
    target_agent_id: Option<String>,
    origin_agent_id: Option<String>,
    chat_session_id: Option<String>,
}

/// Invoke `visit` for every complete line that fits `max_line_bytes`, using a
/// fixed read buffer. Oversized lines are discarded through their newline
/// without ever growing a payload-sized allocation. A final line without a
/// trailing newline is still visited, which preserves the JSONL compatibility
/// of the prior `str::lines` reader.
fn visit_bounded_lines<R, F, O>(
    mut reader: R,
    max_line_bytes: usize,
    mut visit: F,
    mut oversized: O,
) -> std::io::Result<()>
where
    R: std::io::Read,
    F: FnMut(&[u8]),
    O: FnMut(&[u8]),
{
    let mut chunk = vec![0_u8; 64 * 1024];
    let mut line = Vec::with_capacity(max_line_bytes.min(64 * 1024));
    let mut discarding_oversized_line = false;
    loop {
        let read = reader.read(&mut chunk)?;
        if read == 0 {
            break;
        }
        let chunk = &chunk[..read];
        let mut start = 0usize;
        for (index, byte) in chunk.iter().enumerate() {
            if *byte != b'\n' {
                continue;
            }
            if !discarding_oversized_line {
                let part = &chunk[start..index];
                if line.len().saturating_add(part.len()) <= max_line_bytes {
                    line.extend_from_slice(part);
                    visit(&line);
                } else {
                    oversized(&line);
                }
            }
            line.clear();
            discarding_oversized_line = false;
            start = index + 1;
        }
        if start < chunk.len() && !discarding_oversized_line {
            let part = &chunk[start..];
            if line.len().saturating_add(part.len()) <= max_line_bytes {
                line.extend_from_slice(part);
            } else {
                oversized(&line);
                line.clear();
                discarding_oversized_line = true;
            }
        }
    }
    if !discarding_oversized_line && !line.is_empty() {
        visit(&line);
    }
    Ok(())
}

/// Stream a complete `chat_turn_events/<turn>.jsonl` history for delegate
/// status rows. Only the latest unresolved descriptor per
/// `(task_id, execution_id)` is retained: terminal rows remove the key, so
/// memory grows with live orphan candidates rather than journal length.
fn orphan_delegate_update_from_jsonl_line(
    line: &[u8],
) -> Option<(String, String, String, OrphanDelegate)> {
    if line.iter().all(u8::is_ascii_whitespace) {
        return None;
    }
    let mut admission = EncodedJsonStreamAdmission::new(
        MAX_RETAINED_JSON_DEPTH,
        CHAT_TURN_EVENT_RECOVERY_MAX_RECORD_NODES,
    );
    if !admission.feed(line) || !admission.finish() {
        return None;
    }
    let Ok(mut value) = serde_json::from_slice::<serde_json::Value>(line) else {
        return None;
    };
    let update = (|| {
        let inner = value.pointer("/data/event")?;
        if inner.get("event_type").and_then(serde_json::Value::as_str)
            != Some("chat.delegate.status_changed")
        {
            return None;
        }
        let payload = inner.get("payload")?;
        let task_id = payload
            .get("task_id")
            .and_then(serde_json::Value::as_str)?
            .to_string();
        let execution_id = payload
            .get("execution_id")
            .and_then(serde_json::Value::as_str)?
            .to_string();
        let status = payload
            .get("status")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("")
            .to_owned();
        let descriptor = OrphanDelegate {
            task_id: task_id.clone(),
            execution_id: execution_id.clone(),
            owner_agent_id: inner
                .get("agent_id")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
            target_agent_id: payload
                .get("target_agent_id")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
            origin_agent_id: payload
                .get("origin_agent_id")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
            chat_session_id: payload
                .get("chat_session_id")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
        };
        Some((task_id, execution_id, status, descriptor))
    })();
    discard_json_iteratively(std::mem::take(&mut value));
    update
}

fn find_orphan_delegates_in_jsonl_reader<R: std::io::Read>(
    reader: R,
) -> std::io::Result<Vec<OrphanDelegate>> {
    let mut unresolved: HashMap<(String, String), OrphanDelegate> = HashMap::new();

    visit_bounded_lines(
        reader,
        CHAT_TURN_EVENT_RECOVERY_MAX_RECORD_BYTES,
        |line| {
            let Some((task_id, execution_id, status, descriptor)) =
                orphan_delegate_update_from_jsonl_line(line)
            else {
                return;
            };
            if matches!(status.as_str(), "completed" | "failed" | "cancelled") {
                unresolved.remove(&(task_id, execution_id));
            } else {
                unresolved.insert((task_id, execution_id), descriptor);
            }
        },
        |_| {},
    )?;
    Ok(unresolved.into_values().collect())
}

async fn find_orphan_delegates_in_jsonl_path(
    workspace: &ArtifactV2Workspace,
    path: &Path,
) -> Result<Vec<OrphanDelegate>, ArtifactV2Error> {
    let canonical_path = workspace.canonicalize_path(path).await?;
    tokio::task::spawn_blocking(move || {
        let file = std::fs::File::open(canonical_path)?;
        find_orphan_delegates_in_jsonl_reader(file).map_err(ArtifactV2Error::Io)
    })
    .await
    .map_err(|error| {
        ArtifactV2Error::Runtime(format!(
            "chat-turn JSONL recovery worker failed to join: {error}"
        ))
    })?
}

/// Sanitise a chat session's `ui_thread_id` for use inside an
/// `agent-browser --session magician-chat-<id>` argument. Mirrors the
/// allow-list applied by `primitive/browser/session::sanitize_session_id`
/// — anything outside `[a-zA-Z0-9_-]` becomes `_`. Returning this from a
/// helper means every callsite that builds a chat-scoped session id
/// agrees on the same canonical form.
fn chat_browser_session_id_segment(ui_thread_id: &str) -> String {
    ui_thread_id
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect()
}

/// Build a `voice:<mode>` tag string from the raw `personality_mode`
/// argument the caller LLM passed to `delegate_to_agent` /
/// `handover_to_agent`. Returns `None` when the argument is missing or
/// is one of the explicit "no override" sentinels (`default`/`none`/
/// `off`/`inherit`) — those carry no information for the operator and
/// would just be visual noise. Returned strings are normalised
/// (lowercase, hyphenated) so `Current`, `current` and `CURRENT` all
/// collapse to the same tag.
fn chat_personality_tag(personality_mode_raw: Option<&str>) -> Option<String> {
    let raw = personality_mode_raw?.trim();
    if raw.is_empty() {
        return None;
    }
    let normalised = raw.to_ascii_lowercase().replace('_', "-");
    if matches!(normalised.as_str(), "default" | "none" | "off" | "inherit") {
        return None;
    }
    Some(format!("voice:{normalised}"))
}

#[derive(Debug, Clone)]
struct PreparedTutorActionDelegation {
    envelope: TutorActionEnvelope,
    step: TutorStep,
    context_block: String,
}

#[derive(Debug, Clone)]
struct PreparedChatDelegation {
    target_agent_id: String,
    context: String,
    personality_mode: Option<String>,
    personality_directive: Option<String>,
    work_budget_secs: Option<u64>,
    track_as_task: bool,
    reference_task_ids: Vec<String>,
    tutor_delegation: Option<PreparedTutorActionDelegation>,
    authorization_revision: crate::magician_v2::agents::runtime::GoalAuthorizationRevision,
}

fn chat_delegation_work_budget_secs(target: &Value) -> Result<Option<u64>, String> {
    let explicit_timeout_secs = match target.get("timeout_secs") {
        None => None,
        Some(value) => match value.as_u64() {
            Some(0) | None => {
                return Err("`timeout_secs` must be a positive integer".to_string());
            },
            Some(value) => Some(value),
        },
    };
    let depth = match target.get("depth") {
        None => None,
        Some(value) => Some(
            value
                .as_str()
                .ok_or_else(|| "`depth` must be a string".to_string())?,
        ),
    };

    resolve_delegation_work_budget_secs(explicit_timeout_secs, depth).map_err(str::to_string)
}

fn prepare_tutor_mac_operator_delegation(
    session: &ChatSession,
    target_agent_id: &str,
    target: &Value,
    current_user_text: Option<&str>,
) -> Result<Option<PreparedTutorActionDelegation>, Value> {
    if target_agent_id != "mac-operator" {
        return Ok(None);
    }
    let store = tutor_run_store();
    let scope = TutorRunScope::new(
        session.principal.clone(),
        session.workspace.clone(),
        session.id.clone(),
    );
    let active_run = match store.active_run(&scope) {
        Ok(run) => run.filter(|run| !run.status.is_terminal()),
        Err(reason) => {
            return Err(json!({
                "status": "error",
                "target_agent_id": target_agent_id,
                "reason": reason,
            }));
        },
    };
    let envelope_value = match tutor_action_value_from_delegate_target(target) {
        Ok(value) => value,
        Err(reason) => {
            return Err(json!({
                "status": "error",
                "target_agent_id": target_agent_id,
                "reason": reason,
            }));
        },
    };
    let explicit_tutor_lane = current_user_text
        .map(crate::magician_v2::execution::agentic::parse_leading_feature_invocation)
        .is_some_and(lane_keeps_tutor_runtime_tools);
    if envelope_value.is_none() && active_run.is_none() && !explicit_tutor_lane {
        return Ok(None);
    }
    let Some(envelope_value) = envelope_value else {
        return Err(json!({
            "status": "error",
            "target_agent_id": target_agent_id,
            "reason": "Tutor-marked mac-operator delegation requires a `tutor_action` envelope. Start a tutor run, draw/resolve the target, then delegate with tutor_action.run_id, step_kind, storyboard_step_id or storyboard_step_label, target, expected_state, safety, observation_evidence, and action_instruction.",
        }));
    };
    let envelope = match parse_tutor_action_envelope(&envelope_value) {
        Ok(envelope) => envelope,
        Err(reason) => {
            return Err(json!({
                "status": "error",
                "target_agent_id": target_agent_id,
                "reason": reason,
            }));
        },
    };
    let active_run = match active_run {
        Some(run) => run,
        None => {
            return Err(json!({
                "status": "error",
                "target_agent_id": target_agent_id,
                "reason": "Tutor mac-operator delegation requires an active tutor run for this chat session. Call start_tutor_run first.",
            }));
        },
    };
    if active_run.run_id != envelope.run_id {
        return Err(json!({
            "status": "error",
            "target_agent_id": target_agent_id,
            "reason": format!(
                "Tutor mac-operator delegation run_id `{}` does not match active tutor run `{}` for this chat session.",
                envelope.run_id, active_run.run_id
            ),
        }));
    }
    let step = match validate_tutor_action_envelope_for_run(&active_run, &envelope) {
        Ok(step) => step,
        Err(reason) => {
            return Err(json!({
                "status": "error",
                "target_agent_id": target_agent_id,
                "run_id": envelope.run_id,
                "reason": reason,
            }));
        },
    };
    let context_block = render_tutor_action_context_block(&envelope);
    Ok(Some(PreparedTutorActionDelegation {
        envelope,
        step,
        context_block,
    }))
}

fn tutor_action_value_from_delegate_target(target: &Value) -> Result<Option<Value>, String> {
    if let Some(value) = target.get("tutor_action").filter(|value| !value.is_null()) {
        return Ok(Some(value.clone()));
    }

    let Some(input_data) = target.get("input_data") else {
        return Ok(None);
    };
    let parsed = match input_data {
        Value::String(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                return Ok(None);
            }
            match serde_json::from_str::<Value>(trimmed) {
                Ok(value) => value,
                Err(_) => return Ok(None),
            }
        },
        Value::Object(_) => input_data.clone(),
        _ => return Ok(None),
    };
    if let Some(value) = parsed
        .get("tutor_action")
        .filter(|value| !value.is_null())
        .cloned()
    {
        return Ok(Some(value));
    }
    if parsed.get("run_id").is_some() && parsed.get("step_kind").is_some() {
        return Ok(Some(parsed));
    }
    Ok(None)
}

fn render_tutor_action_context_block(envelope: &TutorActionEnvelope) -> String {
    let envelope_json = serde_json::to_string_pretty(envelope).unwrap_or_else(|_| "{}".to_string());
    format!(
        r#"## Personal Tutor Action Envelope

This delegated macOS action is part of an active Personal Tutor run. The parent chat runtime already validated this envelope against the active tutor state before enqueueing you.

Execute exactly the action described by this envelope. Do not substitute a different target or a different UI action. For UI-changing actions, the envelope is bound to a prior successful screen-draw storyboard step; act on that previewed target only. If the target cannot be found or no longer matches the preview, stop and report the mismatch.

For envelope-bound `click`, `type_text`, `hotkey`, and `scroll` actions, preserve the preview binding but still choose the cheapest correct macOS engine. For scriptable apps such as Notes, Music, Reminders, Calendar, Mail, Messages, Safari, and Finder, prefer the `macos-script-automation` / JXA / AppleScript path when it can execute and verify the requested state directly. Use `macos-ui-automation` for non-scriptable UI, opaque surfaces, canvas apps, or cases where the action must physically target the previewed coordinate/control. Do not run daemon/bootstrap loops; if CUA is needed, use the `macos-ui-automation` tool wrapper and verify after the action.

After acting, observe the screen again and verify `expected_state`. Return a concise result and include a machine-readable line:

TUTOR_ACTION_RESULT: {{"run_id":"{}","status":"succeeded|failed","evidence":"<what you observed after the action>"}}

```json
{}
```"#,
        envelope.run_id, envelope_json
    )
}

fn tutor_step_kind_value(kind: TutorStepKind) -> Value {
    serde_json::to_value(kind).unwrap_or_else(|_| Value::String(format!("{kind:?}")))
}

#[allow(clippy::too_many_arguments)]
fn emit_tutor_run_progress(
    broadcaster: &RuntimeTransportBroadcaster,
    agent_id: &str,
    principal: Option<&str>,
    workspace: Option<&str>,
    chat_session_id: Option<&str>,
    chat_turn_id: Option<&str>,
    event_type: RuntimeAgentEventType,
    run: &TutorRun,
    note: Option<&str>,
) {
    let event_type_str = event_type.as_str();
    broadcaster.emit_named(
        event_type_str,
        agent_id,
        principal,
        workspace,
        json!({
            "event_id": tutor_run_event_id(event_type_str, run),
            "chat_turn_id": chat_turn_id,
            "chat_session_id": chat_session_id,
            "run_id": run.run_id.as_str(),
            "goal": run.goal.as_str(),
            "mode": run.mode.as_str(),
            "status": run.status.as_str(),
            "step_count": run.step_history.len(),
            "terminal_reason": run.terminal_reason.as_deref(),
            "note": note,
        }),
    );
}

#[allow(clippy::too_many_arguments)]
fn emit_tutor_step_progress(
    broadcaster: &RuntimeTransportBroadcaster,
    agent_id: &str,
    principal: Option<&str>,
    workspace: Option<&str>,
    chat_session_id: Option<&str>,
    chat_turn_id: Option<&str>,
    event_type: RuntimeAgentEventType,
    run: &TutorRun,
    step: &TutorStep,
    step_status: TutorStepStatus,
    note: Option<&str>,
) {
    let event_type_str = event_type.as_str();
    let step_id = tutor_step_event_id(run, step);
    broadcaster.emit_named(
        event_type_str,
        agent_id,
        principal,
        workspace,
        json!({
            "event_id": tutor_step_event_id_for_type(event_type_str, run, step),
            "step_id": step_id,
            "chat_turn_id": chat_turn_id,
            "chat_session_id": chat_session_id,
            "run_id": run.run_id.as_str(),
            "goal": run.goal.as_str(),
            "mode": run.mode.as_str(),
            "run_status": run.status.as_str(),
            "step_kind": step.kind.as_str(),
            "step_label": step.label.as_str(),
            "step_status": step_status.as_str(),
            "target": step.target.as_deref(),
            "expected_state": step.expected_state.as_deref(),
            "step_count": run.step_history.len(),
            "note": note,
        }),
    );
}

fn tutor_run_has_terminal_evidence(run: &TutorRun) -> bool {
    run.has_visible_draw_storyboard_evidence()
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum TutorAutoFinalization {
    Complete,
    Fail(String),
    NotReady,
}

fn tutor_run_auto_finalization(run: &TutorRun) -> TutorAutoFinalization {
    if run.status != TutorRunStatus::Running || run.pending_action.is_some() {
        return TutorAutoFinalization::NotReady;
    }
    if let Some(blocker) = run.terminal_blocker_reason() {
        return TutorAutoFinalization::Fail(format!(
            "Tutor could not complete the requested visual lesson: {blocker}"
        ));
    }
    if guided_tutor_finalization_continuation(run).is_some()
        || !run.lesson_contract_is_satisfied()
        || !tutor_run_has_terminal_evidence(run)
    {
        return TutorAutoFinalization::NotReady;
    }
    TutorAutoFinalization::Complete
}

fn tutor_continuation_guard_limit(run: Option<&TutorRun>) -> usize {
    run.and_then(TutorRun::lesson_progress)
        .map(|progress| {
            CHAT_INLINE_MAX_TUTOR_CONTINUATION_GUARDS.max(
                progress
                    .planned_milestones
                    .max(progress.minimum_storyboard_steps)
                    .saturating_add(1),
            )
        })
        .unwrap_or(CHAT_INLINE_MAX_TUTOR_CONTINUATION_GUARDS)
}

fn tutor_run_event_id(event_type: &str, run: &TutorRun) -> String {
    format!(
        "tutor-run:{}:{}:{}",
        run.run_id.as_str(),
        event_type,
        run.step_history.len()
    )
}

fn tutor_step_event_id(run: &TutorRun, step: &TutorStep) -> String {
    format!(
        "tutor-step:{}:{}:{}",
        run.run_id.as_str(),
        run.step_history.len(),
        step.kind.as_str()
    )
}

fn tutor_step_event_id_for_type(event_type: &str, run: &TutorRun, step: &TutorStep) -> String {
    format!("{}:{}", tutor_step_event_id(run, step), event_type)
}

fn summarize_description(description: &str) -> String {
    let mut single_line = description.replace('\n', " ");
    while single_line.contains("  ") {
        single_line = single_line.replace("  ", " ");
    }
    let trimmed = single_line.trim();
    if trimmed.is_empty() {
        "(no description)".to_string()
    } else if trimmed.chars().count() > 200 {
        let mut bound = 0;
        for (idx, _) in trimmed.char_indices().take(200) {
            bound = idx;
        }
        format!("{}…", &trimmed[..bound])
    } else {
        trimmed.to_string()
    }
}

/// Render the system-prompt index for callable capabilities without repeating
/// the full description of every implicitly injected universal pack. The
/// provider tool catalogue already carries each tool's authoritative schema
/// and description; repeating ~40 descriptions here adds substantial cached
/// prompt weight without increasing dispatch fidelity. Explicit agent grants
/// retain their individual descriptions, while implicit universals retain
/// every tool name in one compact, auditable line.
fn render_chat_capability_tools_list(
    native_tools: &[NativeExecutionTool],
    definition: Option<&crate::magician_v2::agents::types::AgentDefinition>,
) -> String {
    use crate::magician_v2::execution::agentic::native_integration::UNIVERSAL_BACKEND_PACKS;

    let explicitly_granted: HashSet<&str> = definition
        .map(|definition| {
            definition
                .tools
                .iter()
                .map(|name| name.trim())
                .filter(|name| !name.is_empty())
                .collect()
        })
        .unwrap_or_default();
    // An empty allowlist means all registered tools. Preserve the established
    // fully-expanded prompt in that uncommon mode because there is no useful
    // explicit-vs-implicit distinction to compact.
    let compact_implicit_universals = !explicitly_granted.is_empty();
    let mut detailed = Vec::new();
    let mut implicit_universals = Vec::new();
    for tool in native_tools.iter().filter(|tool| !tool.is_control_tool) {
        if compact_implicit_universals
            && UNIVERSAL_BACKEND_PACKS.contains(&tool.name.as_str())
            && !explicitly_granted.contains(tool.name.as_str())
        {
            implicit_universals.push(format!("`{}`", tool.name));
        } else {
            detailed.push(format!(
                "- `{}` — {}",
                tool.name,
                summarize_description(&tool.description)
            ));
        }
    }
    if !implicit_universals.is_empty() {
        detailed.push(format!(
            "- Shared backend tools (full descriptions and schemas are in the provider tool \
             catalogue): {}",
            implicit_universals.join(", ")
        ));
    }
    detailed.join("\n")
}

fn chat_runtime_result_is_error(value: &Value) -> bool {
    value
        .as_object()
        .map(|object| {
            object
                .get("status")
                .and_then(Value::as_str)
                .map(|status| {
                    matches!(
                        status,
                        "error" | "failed" | "ignored" | "not_supported" | "not_supported_in_chat"
                    )
                })
                .unwrap_or(false)
                || object.contains_key("error")
        })
        .unwrap_or(false)
}

fn chat_runtime_error_summary(tool_name: &str, value: &Value) -> String {
    value
        .get("reason")
        .or_else(|| value.get("error"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|reason| !reason.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| format!("chat runtime tool `{tool_name}` returned an error result"))
}

fn chat_runtime_result_shape_summary(value: &Value) -> String {
    match value {
        Value::Object(object) => format!("json object result ({} fields)", object.len()),
        Value::Array(items) => format!("json array result ({} items)", items.len()),
        Value::String(text) => format!("string result ({} chars)", text.chars().count()),
        Value::Bool(value) => format!("bool result ({value})"),
        Value::Number(_) => "number result".to_string(),
        Value::Null => "null result".to_string(),
    }
}

/// Collect every `task_id` value reachable in a tool result, descending into
/// nested JSON-as-string fields. Task-spawning tools surface the spawned task
/// id in inconsistent places: top-level `task_id` (`create_task`, deferred
/// `orchestrate_pipeline`), nested inside `full_result.preview` (a JSON STRING,
/// for the inline `orchestrate_pipeline` form), and as an array of
/// `delegations[].task_id` (`delegate_to_agent`, possibly several). Walking for
/// the `"task_id"` key — and re-parsing string values that look like embedded
/// JSON — finds all of them without hard-coding each tool's result shape. The
/// caller still gates every id on session ownership before acting on it, so
/// over-collection here is harmless. De-duplicates; preserves first-seen order.
fn collect_task_ids(value: &Value, out: &mut Vec<String>) {
    match value {
        Value::Object(map) => {
            for (key, child) in map {
                if key == "task_id" {
                    if let Some(id) = child.as_str() {
                        if id.starts_with("task_") && !out.iter().any(|seen| seen == id) {
                            out.push(id.to_string());
                        }
                    }
                }
                collect_task_ids(child, out);
            }
        },
        Value::Array(items) => {
            for item in items {
                collect_task_ids(item, out);
            }
        },
        Value::String(text) => {
            // Embedded JSON (e.g. `full_result.preview`) carries task ids for
            // the inline orchestrate/delegate result forms. Re-parse + recurse.
            let trimmed = text.trim_start();
            if (trimmed.starts_with('{') || trimmed.starts_with('[')) && text.len() < 200_000 {
                if let Ok(nested) = serde_json::from_str::<Value>(text) {
                    collect_task_ids(&nested, out);
                }
            }
        },
        _ => {},
    }
}

/// The duplicate-task guard's dedup key for `tool_name`, or `None` for tools
/// the guard doesn't cover. The string returned is matched against existing
/// tasks' `description`, so it must equal what the tool will STORE there:
/// `orchestrate_pipeline` stores `goal` verbatim; `create_task` stores
/// `create_task_description_from_args(args, title)`. Only the heavyweight,
/// expensive-to-re-run spawners are covered — they're the ones the model
/// re-issues from stale conversation history on unrelated turns.
fn duplicate_guard_goal(tool_name: &str, args: &Value) -> Option<String> {
    match tool_name {
        "orchestrate_pipeline" => {
            let goal = args.get("goal").and_then(Value::as_str)?.trim();
            if goal.is_empty() {
                return None;
            }
            Some(goal.to_string())
        },
        "create_task" => {
            let title = args.get("title").and_then(Value::as_str)?.trim();
            if title.is_empty() {
                return None;
            }
            Some(create_task_description_from_args(args, title))
        },
        _ => None,
    }
}

/// Normalize a goal/description for duplicate comparison: collapse all runs of
/// whitespace to single spaces and lowercase. Tolerates trivial formatting
/// drift between two issues of the same request while keeping genuinely
/// different requests distinct.
fn normalize_goal_for_dedup(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

/// Result returned when the duplicate-task guard blocks a re-create. Carries
/// the existing task so the agent can tell the user it's already handled, and
/// instructs the model to re-issue with `allow_duplicate: true` ONLY after the
/// user explicitly confirms a fresh re-run.
fn duplicate_confirmation_result(
    tool_name: &str,
    existing_task_id: &str,
    existing_title: &str,
    existing_status: &str,
) -> Value {
    json!({
        "status": "duplicate_blocked",
        "tool": tool_name,
        "existing_task_id": existing_task_id,
        "existing_title": existing_title,
        "existing_status": existing_status,
        "reason": format!(
            "An identical request already created a task in THIS conversation (\"{existing_title}\", currently {existing_status}), so it was NOT re-run automatically. \
    This guard usually fires when a request was carried over from earlier context rather than something the user just asked for fresh. \
    If the user did NOT explicitly ask to run it again, simply tell them it's already {existing_status} — its progress and result are on its card — and do NOT call this tool again. \
    ONLY if the user EXPLICITLY confirms they want another, separate run should you call `{tool_name}` again with the same arguments plus `allow_duplicate: true`."
        ),
    })
}

/// Summarize a chat tool dispatcher's JSON result into the shape
/// `(success, preview, error)` that `emit_tool_call_finished` expects.
///
/// The dispatcher rail supplies a successful fallback. Only the platform's
/// declared lifecycle vocabulary may refine that outcome; domain-specific
/// `status` values are preserved as data rather than guessed here.
///
/// The preview is a one-line excerpt of the serialized JSON capped at
/// 240 chars, matching the inner-loop runner's emission shape so UI
/// renderers can treat both event sources identically.
pub(crate) fn summarize_chat_tool_result_for_event(
    value: &Value,
) -> (bool, String, Option<String>) {
    const EVENT_PREVIEW_CHARS: usize = 240;
    // Compact JSON emits either ASCII escapes or literal UTF-8. Four bytes per
    // retained Unicode scalar are therefore sufficient to recover the exact
    // first 240 serialized characters without materializing the remaining
    // provider-safe tree.
    const EVENT_PREVIEW_SERIALIZED_BYTES: usize = EVENT_PREVIEW_CHARS * 4;
    const EVENT_PREVIEW_MAX_NODES: usize = 1_000_000;

    // Tool-finished events are a UI/telemetry boundary, not a private raw-result
    // store. Apply the same outbound credential guard used by model replay
    // before deriving either the preview or the error string.  In particular,
    // a dispatcher failure can echo the rejected input, so the failure path is
    // not safe to treat as metadata by default.
    let safe_value = crate::magician_v2::secrets::injection::sanitize_json_for_provider(value);
    let serialized_prefix = compact_json_prefix_bounded(
        &safe_value,
        EVENT_PREVIEW_SERIALIZED_BYTES,
        EVENT_PREVIEW_MAX_NODES,
        MAX_RETAINED_JSON_DEPTH,
    )
    .ok()
    .flatten()
    .map(|(prefix, _)| prefix)
    .unwrap_or_default();
    let preview: String = serialized_prefix
        .lines()
        .next()
        .unwrap_or("")
        .chars()
        .take(EVENT_PREVIEW_CHARS)
        .collect();

    let outcome = chat_tool_outcome(&safe_value);
    let success = !outcome.is_failure();
    let error = (!success).then(|| {
        outcome
            .message
            .clone()
            .or(outcome.code.clone())
            .unwrap_or_else(|| format!("tool outcome was {:?}", outcome.status))
    });

    (success, preview, error)
}

fn is_app_data_tool_name(tool_name: &str) -> bool {
    crate::magician_v2::execution::compiled_dispatch::is_governed_app_compiled_tool(tool_name)
}

fn is_effectful_app_data_tool_name(tool_name: &str) -> bool {
    matches!(
        tool_name,
        "app_data_compose" | "app_action_compose" | "app_action_invoke" | "app_memory_propose"
    )
}

fn tool_set_activates_app_data(tool_names: &BTreeSet<String>) -> bool {
    tool_names.iter().any(|name| is_app_data_tool_name(name))
}

/// External model surfaces cannot own the guarded app-result continuation
/// contract. Keep governed tools out of discovery and working-set mutation,
/// rather than advertising a capability that dispatch must later refuse.
fn external_tool_names_without_governed_apps(tool_names: &HashSet<String>) -> HashSet<String> {
    tool_names
        .iter()
        .filter(|name| {
            crate::magician_v2::execution::compiled_dispatch::compiled_tool_is_exposable_on_surface(
                name,
                crate::magician_v2::execution::compiled_dispatch::GovernedAppToolSurface::ExternalModel,
            )
        })
        .cloned()
        .collect()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GovernedEffectDispatchPhase {
    NotSettled,
    ProviderReturnedTypedOutcome,
}

fn governed_effect_dispatch_phase(
    tool_name: &str,
    governed_result_guard_present: bool,
) -> GovernedEffectDispatchPhase {
    if is_effectful_app_data_tool_name(tool_name) && governed_result_guard_present {
        GovernedEffectDispatchPhase::ProviderReturnedTypedOutcome
    } else {
        GovernedEffectDispatchPhase::NotSettled
    }
}

fn governed_effect_control_receipt(
    tool_name: &str,
    value: &Value,
    governed_result_guard_present: bool,
) -> Option<Value> {
    matches!(
        governed_effect_dispatch_phase(tool_name, governed_result_guard_present),
        GovernedEffectDispatchPhase::ProviderReturnedTypedOutcome
    )
    .then(|| governed_effect_control_outcome(tool_name, value))
}

/// Project a completed governed effect down to host-owned control metadata.
/// In particular, composition `result` bytes and memory claim/source content
/// are never copied into the cancellation receipt.
fn governed_effect_control_outcome(tool_name: &str, value: &Value) -> Value {
    fn copy_fields(
        source: &Value,
        destination: &mut serde_json::Map<String, Value>,
        names: &[&str],
    ) {
        let Some(source) = source.as_object() else {
            return;
        };
        for name in names {
            if let Some(value) = source.get(*name) {
                destination.insert((*name).to_owned(), value.clone());
            }
        }
    }

    let mut outcome = serde_json::Map::new();
    match tool_name {
        "app_data_compose" | "app_action_compose" => {
            copy_fields(
                value,
                &mut outcome,
                &[
                    "status",
                    "error_code",
                    "retry_class",
                    "retryable",
                    "effect_uncertain",
                    "result_withheld_by_policy",
                    "source_status",
                ],
            );
            if let Some(source_run) = value.get("source_run") {
                outcome.insert("source_run".to_owned(), source_run.clone());
            }
            if let Some(launch) = value.get("launch") {
                let mut safe_launch = serde_json::Map::new();
                copy_fields(
                    launch,
                    &mut safe_launch,
                    &["run_handle", "task_id", "execution_id"],
                );
                if !safe_launch.is_empty() {
                    outcome.insert("launch".to_owned(), Value::Object(safe_launch));
                }
            }
        },
        "app_action_invoke" => {
            copy_fields(
                value,
                &mut outcome,
                &[
                    "status",
                    "error_code",
                    "retryable",
                    "effect_uncertain",
                    "result_withheld_by_policy",
                ],
            );
            if let Some(run_handle) = value.get("run_handle") {
                outcome.insert("run_handle".to_owned(), run_handle.clone());
            }
        },
        "app_memory_propose" => {
            copy_fields(
                value,
                &mut outcome,
                &[
                    "candidate_id",
                    "candidate_revision",
                    "status",
                    "publication_outcome",
                    "error_code",
                    "retryable",
                    "effect_committed",
                ],
            );
        },
        _ => {},
    }
    if outcome.is_empty() {
        outcome.insert("status".to_owned(), json!("outcome_unavailable"));
    }
    json!({
        "status": "settled_after_stop",
        "tool": tool_name,
        "outcome": outcome,
        "result_bytes_withheld": true,
    })
}

fn governed_effect_settled_after_stop_message(receipt: &Value) -> String {
    format!(
        "Stop arrived after the governed action had settled. Its safe control outcome is: \
         {receipt}"
    )
}

fn governed_app_consumer_refusal() -> Value {
    json!({
        "status": "error",
        "error_code": "AppDataConsumerDenied",
        "reason": "Governed app data is unavailable to the current model consumer.",
    })
}

fn governed_app_lineage_refusal() -> Value {
    json!({
        "status": "error",
        "error_code": "AppDerivedLineageUnsupported",
        "reason": "This governed app write requires one complete, unambiguous source lineage.",
    })
}

fn governed_direct_action_lineage_refusal() -> Value {
    json!({
        "status": "error",
        "error_code": "AppDirectActionLineageUnsupported",
        "reason": "Direct app invocation cannot consume prior tool or governed data. Use app_data_compose or app_action_compose for data-derived input.",
    })
}

fn governed_app_external_surface_refusal() -> Value {
    json!({
        "status": "error",
        "error_code": "AppResultExternalContinuationUnavailable",
        "reason": "Governed app tools are currently available only in a direct local chat continuation.",
    })
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum GovernedAppSourceLineage {
    Projection(String),
    ActionRun(String),
}

/// V1 can continue to use the original source fence only while every
/// model-visible result is either another typed source read or a proven
/// no-effect control outcome. Destination launches, effect-uncertain failures,
/// and published memory candidates introduce a result lineage that V1 cannot
/// encode for a later write.
fn governed_app_result_invalidates_v1_lineage(tool_name: &str, result: &Value) -> bool {
    match tool_name {
        "app_action_invoke" => {
            let status = result.get("status").and_then(Value::as_str);
            let effect_uncertain = result.get("effect_uncertain").and_then(Value::as_bool);
            let has_run_ref = governed_action_run_from_direct_result(result).is_some();
            match status {
                Some("launched") => !has_run_ref,
                Some("unavailable") if effect_uncertain == Some(true) => !has_run_ref,
                Some("unavailable") if effect_uncertain == Some(false) && !has_run_ref => false,
                Some("cancelled") if effect_uncertain == Some(false) && !has_run_ref => false,
                _ => true,
            }
        },
        "app_data_compose" | "app_action_compose" => {
            let status = result.get("status").and_then(Value::as_str);
            if status == Some("launched")
                || result.get("effect_uncertain").and_then(Value::as_bool) == Some(true)
            {
                return true;
            }
            // These are the complete typed outcomes that prove no destination
            // effect was committed. Anything malformed or untyped after an
            // effect dispatch fails closed because V1 cannot prove otherwise.
            match status {
                Some("waiting") | Some("source_terminal") => false,
                Some("unavailable")
                    if result.get("effect_uncertain").and_then(Value::as_bool) == Some(false) =>
                {
                    false
                },
                _ => true,
            }
        },
        "app_memory_propose" => {
            match result.get("effect_committed").and_then(Value::as_bool) {
                Some(true) => true,
                Some(false)
                    if result.get("status").and_then(Value::as_str) == Some("cancelled") =>
                {
                    false
                },
                // Missing or contradictory effect evidence after an effectful
                // dispatch is not a reusable V1 lineage proof.
                _ => true,
            }
        },
        _ => false,
    }
}

/// A direct action run can remain composable only when its exact run handle
/// crosses the guarded consumer boundary. If the guarded payload is withheld,
/// the effect still happened but the model has no representable source to name;
/// fail the continuation closed instead of allowing another source-less launch.
fn governed_app_result_invalidates_lineage_when_withheld(tool_name: &str, result: &Value) -> bool {
    governed_app_result_invalidates_v1_lineage(tool_name, result)
        || (tool_name == "app_action_invoke"
            && governed_action_run_from_direct_result(result).is_some())
}

#[derive(Debug)]
struct GovernedAppChatState {
    policy: Option<crate::magician_v2::apps::records::AppDataHandlingPolicy>,
    source_lineage: BTreeSet<GovernedAppSourceLineage>,
    lineage_complete: bool,
}

impl Default for GovernedAppChatState {
    fn default() -> Self {
        Self {
            policy: None,
            source_lineage: BTreeSet::new(),
            lineage_complete: true,
        }
    }
}

impl GovernedAppChatState {
    fn policy(&self) -> Option<&crate::magician_v2::apps::records::AppDataHandlingPolicy> {
        self.policy.as_ref()
    }

    fn has_policy(&self) -> bool {
        self.policy.is_some()
    }

    fn effectful_call_denial(&self, call: &LLMToolCall) -> Option<Value> {
        if !is_effectful_app_data_tool_name(&call.name) {
            return None;
        }
        if call.name == "app_action_invoke" {
            return (!self.lineage_complete || !self.source_lineage.is_empty())
                .then(governed_direct_action_lineage_refusal);
        }
        if call.name == "app_memory_propose"
            && self.policy.as_ref().is_some_and(|policy| {
                policy.memory_promotion
                    != crate::magician_v2::apps::records::AppMemoryPromotion::CandidateAllowed
            })
        {
            return Some(governed_app_lineage_refusal());
        }
        let Some(source) = governed_app_source_from_call(call) else {
            return Some(governed_app_lineage_refusal());
        };
        if !self.lineage_complete
            || self.source_lineage.len() != 1
            || !self.source_lineage.contains(&source)
        {
            return Some(governed_app_lineage_refusal());
        }
        None
    }

    fn observe_untyped_model_result(&mut self, tool_name: &str) {
        if !is_app_data_tool_name(tool_name) {
            // Generic tool contracts do not prove that an error payload is
            // content-free. Once any such result is shown in this turn, V1
            // cannot represent its contribution to a later app write.
            // Fail closed regardless of the generic tool's success bit.
            self.lineage_complete = false;
        }
    }

    fn join_guard(
        &mut self,
        call: &LLMToolCall,
        policy: crate::magician_v2::apps::records::AppDataHandlingPolicy,
        projection_handle: Option<&crate::magician_v2::apps::models::AppProjectionHandle>,
        result: &Value,
    ) {
        self.policy = Some(match self.policy.take() {
            Some(current) => {
                crate::magician_v2::apps::policy::intersect_app_data_handling_policies(
                    &current, &policy,
                )
            },
            None => policy,
        });

        match call.name.as_str() {
            // Discovery is guarded policy metadata, not a transferable data
            // source. It neither creates a projection lineage nor restores a
            // lineage already made incomplete by another tool result.
            "app_discover" => {},
            "app_data_query" | "app_data_search" => match projection_handle {
                Some(handle) => {
                    self.source_lineage
                        .insert(GovernedAppSourceLineage::Projection(
                            handle.handle_ref.as_str().to_owned(),
                        ));
                },
                None => self.lineage_complete = false,
            },
            "app_data_compose" | "app_action_compose" | "app_memory_propose" => {
                match governed_app_source_from_call(call) {
                    Some(source) => {
                        self.source_lineage.insert(source);
                    },
                    None => self.lineage_complete = false,
                }
                if governed_app_result_invalidates_v1_lineage(&call.name, result) {
                    self.lineage_complete = false;
                }
            },
            "app_action_invoke" => {
                if let Some(source) = governed_action_run_from_direct_result(result) {
                    self.source_lineage.insert(source);
                }
                if governed_app_result_invalidates_v1_lineage(&call.name, result) {
                    self.lineage_complete = false;
                }
            },
            _ => self.lineage_complete = false,
        }
    }
}

fn governed_action_run_from_direct_result(result: &Value) -> Option<GovernedAppSourceLineage> {
    result
        .get("run_handle")
        .and_then(|run_handle| run_handle.get("run_ref"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .map(GovernedAppSourceLineage::ActionRun)
}

fn governed_app_source_from_call(call: &LLMToolCall) -> Option<GovernedAppSourceLineage> {
    let (field, constructor): (&str, fn(String) -> GovernedAppSourceLineage) =
        match call.name.as_str() {
            "app_data_compose" | "app_memory_propose" => (
                "source_projection_handle",
                GovernedAppSourceLineage::Projection,
            ),
            "app_action_compose" => ("source_run_ref", GovernedAppSourceLineage::ActionRun),
            _ => return None,
        };
    call.arguments
        .get(field)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .map(constructor)
}

fn app_result_policy_permits_consumer(
    direct_personal_agent: bool,
    provider_class: crate::magician_v2::apps::records::AppDisclosureProviderClass,
    remote_processing_enabled: bool,
    execution_ref: Option<crate::magician_v2::apps::models::AppReference>,
    policy: &crate::magician_v2::apps::records::AppDataHandlingPolicy,
) -> bool {
    if !direct_personal_agent
        || policy.personal_agent_access
            != crate::magician_v2::apps::records::AppPersonalAgentAccess::ApprovedProjection
    {
        return false;
    }
    let processing_class = match provider_class {
        crate::magician_v2::apps::records::AppDisclosureProviderClass::LocalModel => {
            crate::magician_v2::apps::boundary::AppAgentProcessingClass::LocalModel
        },
        crate::magician_v2::apps::records::AppDisclosureProviderClass::RemoteModel
            if remote_processing_enabled =>
        {
            crate::magician_v2::apps::boundary::AppAgentProcessingClass::RemoteModel
        },
        crate::magician_v2::apps::records::AppDisclosureProviderClass::Deterministic
        | crate::magician_v2::apps::records::AppDisclosureProviderClass::RemoteModel
        | crate::magician_v2::apps::records::AppDisclosureProviderClass::ExternalTool => {
            return false;
        },
    };
    let Some(execution_ref) = execution_ref else {
        return false;
    };
    crate::magician_v2::apps::boundary::AppStoreReadAudience::PersonalAgent {
        execution_ref,
        processing_class,
        maximum_classification: crate::magician_v2::apps::models::AppDataClassification::Secret,
    }
    .permits_policy(policy.classification_floor, policy.model_processing)
}

fn app_policy_allows_chat_tool(
    policy: &crate::magician_v2::apps::records::AppDataHandlingPolicy,
    tool_name: &str,
) -> bool {
    if is_app_data_tool_name(tool_name) {
        return true;
    }
    match policy.external_egress {
        crate::magician_v2::apps::records::AppExternalEgress::Denied => false,
        crate::magician_v2::apps::records::AppExternalEgress::ApprovedDestinations
        | crate::magician_v2::apps::records::AppExternalEgress::AnyPublicHost => {
            let required = format!("capability:{tool_name}");
            policy
                .approved_destinations
                .iter()
                .any(|destination| destination.as_str() == required)
        },
    }
}

fn json_root_kind(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

/// Build the only representation of governed tool arguments allowed to cross
/// a durable transcript or transport-event boundary. The exact JSON remains in
/// the current turn's in-memory `LLMToolCall` for dispatch and provider protocol
/// continuity; this record retains only a canonical digest and bounded shape.
fn omitted_governed_tool_arguments(arguments: &Value) -> Value {
    let arguments_digest =
        crate::magician_v2::apps::models::AppDigest::blake3_canonical_json(arguments)
            .map(|digest| digest.to_string())
            .expect("canonical JSON hashing into an infallible BLAKE3 writer must succeed");
    let shape = match inspect_json_bounded(arguments, GOVERNED_TOOL_ARGUMENT_SHAPE_MAX_NODES) {
        Some(metrics) => json!({
            "inspection_complete": true,
            "root_kind": json_root_kind(arguments),
            "nodes": metrics.nodes,
            "max_depth": metrics.max_depth,
            "array_entries": metrics.array_entries,
            "maximum_scalar_bytes": metrics.maximum_scalar_bytes,
        }),
        None => json!({
            "inspection_complete": false,
            "root_kind": json_root_kind(arguments),
            "inspection_node_limit": GOVERNED_TOOL_ARGUMENT_SHAPE_MAX_NODES,
        }),
    };
    json!({
        "schema_version": "magician.governed_tool_arguments_omission.v1",
        "governed_content_omitted": true,
        "arguments_digest": arguments_digest,
        "shape": shape,
    })
}

pub(crate) fn tool_arguments_for_durable_surface(
    tool_name: &str,
    arguments: &Value,
    governed_persistence_closed: bool,
) -> Value {
    if governed_persistence_closed || is_app_data_tool_name(tool_name) {
        omitted_governed_tool_arguments(arguments)
    } else {
        crate::magician_v2::json_traversal::clone_json_iteratively(arguments)
    }
}

fn buffer_reasoning_delta_for_durable_event(
    buffers: &mut HashMap<usize, String>,
    index: usize,
    delta: &str,
    governed_persistence_closed: bool,
) {
    if !governed_persistence_closed {
        buffers.entry(index).or_default().push_str(delta);
    }
}

/// Provider/routing errors are not a content-safe type: an adapter may attach
/// response or request detail. Once governed app content can be present, keep
/// the exact error only on the current control path and use one stable marker
/// for every durable event/transcript producer.
fn llm_failure_for_durable_surface(
    error: &anyhow::Error,
    governed_persistence_closed: bool,
) -> String {
    if governed_persistence_closed {
        GOVERNED_LLM_FAILURE_DURABLE_ERROR.to_owned()
    } else {
        format!("{error:#}")
    }
}

fn sanitize_assistant_tool_call_entry_for_persistence(
    entry: &ChatLlmTranscriptEntry,
    governed_persistence_closed: bool,
) -> ChatLlmTranscriptEntry {
    match entry {
        ChatLlmTranscriptEntry::AssistantTurn {
            text,
            tool_calls,
            provider_state,
        } => {
            // Provider-native continuation objects may retain the provider's
            // original tool-call arguments. A governed name therefore closes
            // this persistence path before the result policy is even known.
            let contains_governed_tool = tool_calls
                .iter()
                .any(|call| is_app_data_tool_name(&call.name));
            ChatLlmTranscriptEntry::AssistantTurn {
                text: if governed_persistence_closed {
                    Some(
                        "[governed app-derived assistant content omitted from reusable transcript]"
                            .to_owned(),
                    )
                } else {
                    text.clone()
                },
                tool_calls: tool_calls
                    .iter()
                    .map(|call| StoredToolCall {
                        id: call.id.clone(),
                        name: call.name.clone(),
                        arguments: tool_arguments_for_durable_surface(
                            &call.name,
                            &call.arguments,
                            governed_persistence_closed,
                        ),
                    })
                    .collect(),
                // Provider continuations may retain the omitted bytes on a
                // remote service. Governed turns always restart from the
                // content-free local transcript on the next user turn.
                provider_state: if governed_persistence_closed || contains_governed_tool {
                    None
                } else {
                    provider_state.clone()
                },
            }
        },
        other => other.clone(),
    }
}

fn governed_tool_result_transcript_entries(
    tool_call_id: &str,
    tool_name: &str,
    tool_result: &Value,
    content_digest: &crate::magician_v2::apps::models::AppDigest,
    projection_handle: Option<&crate::magician_v2::apps::models::AppProjectionHandle>,
    exact_result_admitted_to_continuation: bool,
) -> (ChatLlmTranscriptEntry, ChatLlmTranscriptEntry) {
    let persisted = ChatLlmTranscriptEntry::ToolResult {
        tool_call_id: tool_call_id.to_owned(),
        tool_name: Some(tool_name.to_owned()),
        content: json!({
            "status": "governed_app_result",
            "content_digest": content_digest,
            "projection_handle": projection_handle,
            "content_omitted": true,
        })
        .to_string(),
    };
    let in_memory = if exact_result_admitted_to_continuation {
        ChatLlmTranscriptEntry::ToolResult {
            tool_call_id: tool_call_id.to_owned(),
            tool_name: Some(tool_name.to_owned()),
            content: tool_result.to_string(),
        }
    } else {
        persisted.clone()
    };
    (in_memory, persisted)
}

#[cfg(any(test, feature = "test-fixtures"))]
mod governed_tool_argument_persistence_tests {
    use super::*;

    #[test]
    fn provider_bound_local_memory_closes_reusable_history_and_provider_state() {
        let entry = ChatLlmTranscriptEntry::AssistantTurn {
            text: Some("derived from LOCAL-ONLY-MEMORY".to_owned()),
            tool_calls: vec![StoredToolCall {
                id: "ordinary-1".to_owned(),
                name: "list_tasks".to_owned(),
                arguments: json!({"derived": "LOCAL-ONLY-MEMORY"}),
            }],
            provider_state: Some(AssistantProviderState::Gemini {
                parts: vec![json!({"cached": "LOCAL-ONLY-MEMORY"})],
            }),
        };

        let sanitized = sanitize_assistant_tool_call_entry_for_persistence(&entry, true);
        let ChatLlmTranscriptEntry::AssistantTurn {
            text,
            tool_calls,
            provider_state,
        } = sanitized
        else {
            panic!("assistant turn expected");
        };
        assert_eq!(
            text.as_deref(),
            Some("[governed app-derived assistant content omitted from reusable transcript]")
        );
        assert!(provider_state.is_none());
        let encoded = serde_json::to_string(&tool_calls).expect("sanitized tool calls");
        assert!(!encoded.contains("LOCAL-ONLY-MEMORY"));
        assert!(encoded.contains("governed_content_omitted"));
    }

    #[test]
    fn first_governed_call_omits_arguments_and_provider_state_by_name() {
        let exact_arguments = json!({
            "app": "private_notes",
            "action": "publish",
            "input": {"secret": "TOP-SECRET-FIRST-CALL"}
        });
        let entry = ChatLlmTranscriptEntry::AssistantTurn {
            text: Some("Calling the app now.".to_owned()),
            tool_calls: vec![
                StoredToolCall {
                    id: "governed-1".to_owned(),
                    name: "app_action_invoke".to_owned(),
                    arguments: exact_arguments.clone(),
                },
                StoredToolCall {
                    id: "ordinary-1".to_owned(),
                    name: "list_tasks".to_owned(),
                    arguments: json!({"page": 2}),
                },
            ],
            provider_state: Some(AssistantProviderState::Gemini {
                parts: vec![json!({"embedded_args": exact_arguments})],
            }),
        };

        // No result has joined a policy yet. The governed tool name alone must
        // close every durable path carrying that call's exact arguments.
        let sanitized = sanitize_assistant_tool_call_entry_for_persistence(&entry, false);
        let ChatLlmTranscriptEntry::AssistantTurn {
            text,
            tool_calls,
            provider_state,
        } = sanitized
        else {
            panic!("assistant turn expected");
        };
        assert_eq!(text.as_deref(), Some("Calling the app now."));
        assert!(provider_state.is_none());
        assert_eq!(tool_calls[0].id, "governed-1");
        assert_eq!(tool_calls[0].name, "app_action_invoke");
        assert_eq!(
            tool_calls[0]
                .arguments
                .get("governed_content_omitted")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert!(tool_calls[0]
            .arguments
            .get("arguments_digest")
            .and_then(Value::as_str)
            .is_some_and(|digest| digest.starts_with("blake3:")));
        assert_eq!(tool_calls[1].arguments, json!({"page": 2}));
        assert!(!serde_json::to_string(&tool_calls[0].arguments)
            .expect("serialize omission record")
            .contains("TOP-SECRET-FIRST-CALL"));
    }

    #[test]
    fn governed_argument_digest_is_canonical_and_shape_is_bounded() {
        let first = json!({"b": [true, "sensitive"], "a": 1});
        let mut reordered = serde_json::Map::new();
        reordered.insert("a".to_owned(), json!(1));
        reordered.insert("b".to_owned(), json!([true, "sensitive"]));
        let second = Value::Object(reordered);

        let first_record = omitted_governed_tool_arguments(&first);
        let second_record = omitted_governed_tool_arguments(&second);
        assert_eq!(
            first_record.get("arguments_digest"),
            second_record.get("arguments_digest")
        );
        assert_eq!(
            first_record.pointer("/shape/root_kind"),
            Some(&json!("object"))
        );
        assert_eq!(
            first_record.pointer("/shape/inspection_complete"),
            Some(&json!(true))
        );
        assert!(!first_record.to_string().contains("sensitive"));

        let over_limit = Value::Array(
            (0..=GOVERNED_TOOL_ARGUMENT_SHAPE_MAX_NODES)
                .map(|_| Value::Null)
                .collect(),
        );
        let over_limit_record = omitted_governed_tool_arguments(&over_limit);
        assert_eq!(
            over_limit_record.pointer("/shape/inspection_complete"),
            Some(&json!(false))
        );
        assert!(over_limit_record.pointer("/shape/nodes").is_none());
    }

    #[test]
    fn every_governed_app_tool_name_uses_the_omission_record_pre_policy() {
        for tool_name in [
            "app_discover",
            "app_action_compose",
            "app_action_invoke",
            "app_data_query",
            "app_data_search",
            "app_data_compose",
            "app_memory_propose",
        ] {
            let durable = tool_arguments_for_durable_surface(
                tool_name,
                &json!({"private": "must-not-cross"}),
                false,
            );
            assert_eq!(
                durable
                    .get("governed_content_omitted")
                    .and_then(Value::as_bool),
                Some(true),
                "{tool_name} must be sanitized by name before policy join"
            );
            assert!(!durable.to_string().contains("must-not-cross"));
        }

        assert_eq!(
            tool_arguments_for_durable_surface(
                "ordinary_read_only_tool",
                &json!({"public": "kept"}),
                false,
            ),
            json!({"public": "kept"})
        );
    }

    #[test]
    fn active_governed_content_omits_every_follow_on_call_argument() {
        let entry = ChatLlmTranscriptEntry::AssistantTurn {
            text: Some("derived private answer".to_owned()),
            tool_calls: vec![StoredToolCall {
                id: "ordinary-after-governed".to_owned(),
                name: "list_tasks".to_owned(),
                arguments: json!({"query": "derived private selector"}),
            }],
            provider_state: Some(AssistantProviderState::OpenaiResponses {
                response_id: "provider-state".to_owned(),
                tool_protocol_repair_checkpoint: false,
            }),
        };

        let sanitized = sanitize_assistant_tool_call_entry_for_persistence(&entry, true);
        let encoded = serde_json::to_string(&sanitized).expect("serialize sanitized entry");
        assert!(!encoded.contains("derived private"));
        assert!(!encoded.contains("provider-state"));
        assert!(encoded.contains("governed_content_omitted"));
        assert!(encoded.contains("blake3:"));
    }

    #[test]
    fn closed_governed_fence_buffers_no_reasoning_bytes() {
        let mut buffers = HashMap::new();
        buffer_reasoning_delta_for_durable_event(
            &mut buffers,
            0,
            "private governed reasoning",
            true,
        );
        assert!(buffers.is_empty());

        buffer_reasoning_delta_for_durable_event(&mut buffers, 1, "public ", false);
        buffer_reasoning_delta_for_durable_event(&mut buffers, 1, "reasoning", false);
        assert_eq!(
            buffers.get(&1).map(String::as_str),
            Some("public reasoning")
        );
    }

    #[test]
    fn closed_governed_fence_redacts_llm_failure_detail_for_durable_surfaces() {
        let error =
            anyhow::anyhow!("provider echoed governed sentinel GOVERNED-FAILURE-PRIVATE-BYTES");

        let durable = llm_failure_for_durable_surface(&error, true);
        assert_eq!(durable, GOVERNED_LLM_FAILURE_DURABLE_ERROR);
        assert!(!durable.contains("GOVERNED-FAILURE-PRIVATE-BYTES"));

        let ordinary = llm_failure_for_durable_surface(&error, false);
        assert!(ordinary.contains("GOVERNED-FAILURE-PRIVATE-BYTES"));
    }

    #[test]
    fn pre_guard_failure_continuation_keeps_correlation_without_private_bytes() {
        let exact_arguments = json!({"input": {"secret": "PRE-GUARD-PRIVATE"}});
        let exact_assistant = ChatLlmTranscriptEntry::AssistantTurn {
            text: None,
            tool_calls: vec![StoredToolCall {
                id: "call-pre-guard".to_owned(),
                name: "app_action_invoke".to_owned(),
                arguments: exact_arguments,
            }],
            provider_state: None,
        };
        let sanitized_assistant =
            sanitize_assistant_tool_call_entry_for_persistence(&exact_assistant, true);
        let failure = json!({
            "status": "error",
            "reason": "rejected input PRE-GUARD-PRIVATE",
        });
        let digest =
            crate::magician_v2::apps::models::AppDigest::blake3(failure.to_string().as_bytes());
        let (in_memory_result, persisted_result) = governed_tool_result_transcript_entries(
            "call-pre-guard",
            "app_action_invoke",
            &failure,
            &digest,
            None,
            false,
        );
        let continuation = vec![sanitized_assistant, in_memory_result];
        let encoded = serde_json::to_string(&continuation).expect("serialize continuation");

        assert!(!encoded.contains("PRE-GUARD-PRIVATE"));
        assert!(encoded.contains("call-pre-guard"));
        assert!(encoded.contains("app_action_invoke"));
        assert!(encoded.contains("content_omitted"));
        assert_eq!(continuation[1], persisted_result);
    }
}

fn chat_tool_outcome(value: &Value) -> crate::magician_v2::tool_result_projection::ToolOutcome {
    crate::magician_v2::tool_result_runtime::legacy_tool_outcome_from_platform_envelope(
        value,
        crate::magician_v2::tool_result_projection::ToolOutcomeStatus::Succeeded,
    )
}

#[allow(clippy::too_many_arguments)]
#[allow(clippy::too_many_arguments)]
fn build_chat_turn_episode(
    session: &ChatSession,
    agent_id: &str,
    user_text: Option<&str>,
    assistant_text: &str,
    started_at: DateTime<Utc>,
    completed_at: DateTime<Utc>,
    iterations: usize,
    loop_exhausted: bool,
    tool_outcomes: &[ChatToolMemoryOutcome],
    invocation_surface: crate::magician_v2::agents::InvocationSurface,
) -> V3EpisodeRecord {
    let user_excerpt = user_text
        .map(|text| bounded_chat_memory_excerpt(&redact_chat_memory_text(text), 4_000))
        .unwrap_or_default();
    let assistant_excerpt =
        bounded_chat_memory_excerpt(&redact_chat_memory_text(assistant_text), 4_000);
    let summary = if assistant_excerpt.trim().is_empty() {
        "Chat turn completed without assistant text.".to_string()
    } else {
        bounded_chat_memory_excerpt(&assistant_excerpt, 1_000)
    };
    let outcome = if loop_exhausted {
        EpisodeOutcome::PartialProgress {
            summary: summary.clone(),
            remaining: "Chat tool-call loop reached its per-turn limit.".to_string(),
        }
    } else {
        EpisodeOutcome::GoalAchieved {
            summary: summary.clone(),
        }
    };
    let episode_id = format!("chat_{}", Uuid::new_v4().simple());
    let trigger_payload = json!({
        "session_id": session.id,
        "ui_thread_id": session.ui_thread_id,
        "origin_channel": session.origin_channel,
        "iterations": iterations,
        "loop_exhausted": loop_exhausted,
        "tool_count": tool_outcomes.len(),
    });
    let actions_taken = tool_outcomes
        .iter()
        .map(|tool| {
            let mut metadata = HashMap::new();
            metadata.insert("call_id".to_string(), Value::String(tool.call_id.clone()));
            metadata.insert(
                "arguments".to_string(),
                redact_chat_memory_value(&tool.arguments),
            );
            metadata.insert(
                "preview".to_string(),
                Value::String(redact_chat_memory_text(&tool.preview)),
            );
            if let Some(error) = &tool.error {
                metadata.insert(
                    "error".to_string(),
                    Value::String(redact_chat_memory_text(error)),
                );
            }
            ActionSummary {
                action_type: "chat_tool_call".to_string(),
                description: format!("Called chat tool `{}`", tool.tool_name),
                tool: tool.tool_name.clone(),
                succeeded: tool.success,
                duration_ms: Some(tool.duration_ms),
                metadata,
            }
        })
        .collect::<Vec<_>>();
    let tool_values = tool_outcomes
        .iter()
        .map(|tool| {
            json!({
                "call_id": tool.call_id,
                "tool_name": tool.tool_name,
                "success": tool.success,
                "duration_ms": tool.duration_ms,
                "preview": redact_chat_memory_text(&tool.preview),
                "error": tool.error.as_ref().map(|error| redact_chat_memory_text(error)),
            })
        })
        .collect::<Vec<_>>();
    let mut observations = vec![
        format!("chat_session_id: {}", session.id),
        format!("ui_thread_id: {}", session.ui_thread_id),
        format!("origin_channel: {}", session.origin_channel.channel_type),
        format!("iterations: {iterations}"),
    ];
    if !user_excerpt.trim().is_empty() {
        observations.push(format!("user_message_excerpt: {user_excerpt}"));
    }
    if !assistant_excerpt.trim().is_empty() {
        observations.push(format!("assistant_message_excerpt: {assistant_excerpt}"));
    }

    let mut candidates = Vec::new();
    candidates.push(MemoryCandidate {
        candidate_type: "chat_turn_outcome".to_string(),
        target_hint: "agent.memory_quality_source".to_string(),
        key: Some(episode_id.clone()),
        value: json!({
            "session_id": session.id,
            "ui_thread_id": session.ui_thread_id,
            "summary": summary,
            "iterations": iterations,
            "loop_exhausted": loop_exhausted,
        }),
        confidence: if loop_exhausted { 0.55 } else { 0.8 },
        source: "chat_inline_turn".to_string(),
        evidence: vec![format!("chat_session:{}", session.id)],
        rationale: "Chat turn outcome is source material for later memory extraction; it is not \
                    durable by itself."
            .to_string(),
    });
    if !user_excerpt.trim().is_empty() {
        candidates.push(MemoryCandidate {
            candidate_type: "chat_user_message_excerpt".to_string(),
            target_hint: "user_or_agent_memory_candidate_source".to_string(),
            key: Some(format!("{episode_id}:user")),
            value: json!({
                "session_id": session.id,
                "ui_thread_id": session.ui_thread_id,
                "text_excerpt": user_excerpt,
            }),
            confidence: 0.86,
            source: "chat_user_turn".to_string(),
            evidence: vec![format!("chat_session:{}", session.id)],
            rationale: "User chat text may contain explicit preferences, corrections, or reusable \
                        project facts."
                .to_string(),
        });
    }
    if !assistant_excerpt.trim().is_empty() {
        candidates.push(MemoryCandidate {
            candidate_type: "chat_assistant_reply_excerpt".to_string(),
            target_hint: "agent_memory_candidate_source".to_string(),
            key: Some(format!("{episode_id}:assistant")),
            value: json!({
                "session_id": session.id,
                "ui_thread_id": session.ui_thread_id,
                "text_excerpt": assistant_excerpt,
            }),
            confidence: 0.72,
            source: "chat_assistant_turn".to_string(),
            evidence: vec![format!("chat_session:{}", session.id)],
            rationale: "Assistant reply captures conclusions and commitments that may inform \
                        future strategy."
                .to_string(),
        });
    }
    if !tool_values.is_empty() {
        candidates.push(MemoryCandidate {
            candidate_type: "chat_tool_outcomes".to_string(),
            target_hint: "agent.tool_usage_or_environment_knowledge".to_string(),
            key: Some(format!("{episode_id}:tools")),
            value: Value::Array(tool_values),
            confidence: 0.76,
            source: "chat_tool_calls".to_string(),
            evidence: tool_outcomes
                .iter()
                .map(|tool| format!("tool_call:{}:{}", tool.tool_name, tool.call_id))
                .collect(),
            rationale: "Tool outcomes may contain reusable workflow knowledge, failures, or \
                        produced artifact references."
                .to_string(),
        });
    }

    let mut episode = V3EpisodeRecord::new_memory_episode(
        Some((&session.principal, &session.workspace)),
        agent_id.to_string(),
        episode_id.clone(),
        format!("chat:{}", session.id),
        "chat_inline_turn",
        completed_at
            .timestamp_millis()
            .try_into()
            .unwrap_or_default(),
        completed_at,
        Some(trigger_payload),
        started_at,
        completed_at,
        &outcome,
        actions_taken,
        observations,
        Vec::new(),
        Some(format!(
            "Chat turn completed with {} tool call(s); loop_exhausted={loop_exhausted}",
            tool_outcomes.len()
        )),
        Some(format!(
            "principal={}; workspace={}; ui_thread_id={}; chat_session_id={}",
            session.principal, session.workspace, session.ui_thread_id, session.id
        )),
        Some(json!({
            "session_id": session.id,
            "ui_thread_id": session.ui_thread_id,
            "origin_channel": session.origin_channel,
            "tool_outcomes": tool_outcomes
                .iter()
                .map(|tool| {
                    json!({
                        "call_id": tool.call_id,
                        "tool_name": tool.tool_name,
                        "success": tool.success,
                        "duration_ms": tool.duration_ms,
                        "preview": tool.preview,
                        "error": tool.error,
                    })
                })
                .collect::<Vec<_>>(),
        })),
    );
    episode.record_type = "chat_turn".to_string();
    episode.ui_thread_id = Some(session.ui_thread_id.clone());
    episode.execution_status = Some(if loop_exhausted {
        "partial_progress".to_string()
    } else {
        "completed".to_string()
    });
    episode.outcome_type = Some("chat_inline".to_string());
    // Server-minted, never model-supplied. Everything downstream that needs to
    // know how far this content may travel derives it from here.
    episode.origin_surface = Some(invocation_surface.as_str().to_string());
    // The second half of the same fact: WHICH occasion, not just what kind of
    // surface. Server-minted from the session's binding, and only for a room —
    // an owner turn happens in no meeting, and labelling one as if it did
    // would make it reachable from a room that claimed that occasion.
    episode.origin_meeting = matches!(
        invocation_surface,
        crate::magician_v2::agents::InvocationSurface::Meeting
    )
    .then(|| crate::magician_v2::media_seam::meeting_binding_id(&session.ui_thread_id))
    .flatten();
    episode.memory_candidates = candidates;
    episode
}

fn build_memory_utility_review_trace_from_chat_tools(
    tool_outcomes: &[ChatToolMemoryOutcome],
) -> Vec<crate::magician_v2::agents::MemoryTemperatureUtilityReviewTraceItem> {
    tool_outcomes
        .iter()
        .take(18)
        .map(
            |tool| crate::magician_v2::agents::MemoryTemperatureUtilityReviewTraceItem {
                source: "chat_tool_call".to_string(),
                action_type: Some("chat_tool_call".to_string()),
                tool_name: Some(tool.tool_name.clone()),
                succeeded: Some(tool.success),
                duration_ms: Some(tool.duration_ms),
                summary: format!(
                    "Called chat tool `{}` and {}.",
                    tool.tool_name,
                    if tool.success { "succeeded" } else { "failed" }
                ),
                output_preview: (!tool.preview.trim().is_empty()).then(|| {
                    bounded_chat_memory_excerpt(&redact_chat_memory_text(&tool.preview), 1_000)
                }),
                error: tool
                    .error
                    .as_deref()
                    .map(redact_chat_memory_text)
                    .map(|error| bounded_chat_memory_excerpt(&error, 700)),
            },
        )
        .collect()
}

fn bounded_chat_memory_excerpt(text: &str, max_chars: usize) -> String {
    let trimmed = text.trim();
    if trimmed.chars().count() <= max_chars {
        return trimmed.to_string();
    }
    let mut out = trimmed.chars().take(max_chars).collect::<String>();
    out.push_str("...");
    out
}

fn non_empty_trimmed(value: &str) -> Option<&str> {
    let trimmed = value.trim();
    (!trimmed.is_empty()).then_some(trimmed)
}

fn identity_research_review_candidate_exists(
    store: &LearningStore,
    scope: &LearningScope,
    research_task_id: &str,
) -> Result<bool> {
    let candidates = store.list_candidates(
        scope,
        LearningCandidateFilters {
            candidate_type: Some(LearningCandidateType::MemoryFact.as_str().to_string()),
            limit: Some(500),
            ..LearningCandidateFilters::default()
        },
    )?;
    Ok(candidates.iter().any(|candidate| {
        candidate.source_task_id.as_deref() == Some(research_task_id)
            && candidate
                .proposed_change
                .get("public_contact_identity_research")
                .is_some()
    }))
}

fn public_contact_review_subject(
    profile: &PublicContactProfile,
    possible_identity: Option<&str>,
) -> String {
    let subject = possible_identity
        .and_then(non_empty_trimmed)
        .or_else(|| profile.display_name.as_deref().and_then(non_empty_trimmed))
        .or_else(|| profile.claimed_name.as_deref().and_then(non_empty_trimmed))
        .or_else(|| profile.claimed_org.as_deref().and_then(non_empty_trimmed))
        .unwrap_or_else(|| profile.sender_key.channel_address.as_str());
    bounded_chat_memory_excerpt(subject, 80)
}

/// Write what research concluded into the counterparty register, as a guess.
///
/// Engagements Phase 3B. Until this call the two subsystems never met: research
/// settled into a chat-scoped profile and the register stayed empty of
/// everything research had learned.
///
/// # It cannot grant anything, which is why it is safe here
///
/// `contact_research::record_research` mints `MintSource::ResearchInferred` —
/// *"a guess. It is never verified, and it may never be promoted on the strength
/// of the research that produced it."* An unverified identity answers `None` to
/// `authority()`, so inbound routing still treats the sender as a guest and no
/// engagement lane opens on the strength of a pattern. Promotion stays an owner
/// act with a trusted signal and different evidence.
///
/// # A failure here does not fail the research
///
/// The profile is already saved and the owner-review candidate still follows.
/// Losing the register row costs a row an owner would have reviewed; failing the
/// completion would lose the research itself, which is the more expensive half
/// and the one the user waited for. So it is logged and stepped over.
fn record_research_in_register(session: &ChatSession, profile: &PublicContactProfile) {
    use crate::magician_v2::contact_research::{record_research, Recorded};
    use crate::magician_v2::counterparties::{global_counterparty_store, CounterpartyScope};

    let Some(result) = profile.research_result.as_ref() else {
        return;
    };
    let Some(store) = global_counterparty_store() else {
        // Absent is unreadable, never empty — but this is the one caller where
        // that costs only a row, so it says so once and moves on.
        warn!(
            session_id = %session.id,
            "[IDENTITY-RESEARCH] no counterparty register is installed, so what research \
             concluded was not written down"
        );
        return;
    };
    let scope = CounterpartyScope::new(session.principal.clone(), session.workspace.clone());
    match record_research(
        store.as_ref(),
        &scope,
        &profile.sender_key,
        result,
        Utc::now(),
    ) {
        Ok(Recorded::Minted { counterparty, .. }) => info!(
            session_id = %session.id,
            counterparty = %counterparty.as_str(),
            "[IDENTITY-RESEARCH] recorded an UNVERIFIED research guess in the register"
        ),
        // A re-run over a sender already on file. The ordinary case once
        // research has run twice, and NOT a skip: the address is recorded and
        // owned by us, which is the outcome the caller wanted. Logged apart
        // from a mint so a register that has stopped growing can be told from
        // one that was already complete.
        Ok(Recorded::AlreadyOnFile { counterparty, .. }) => debug!(
            session_id = %session.id,
            counterparty = %counterparty.as_str(),
            "[IDENTITY-RESEARCH] this address was already on file for this counterparty"
        ),
        // Every skip is an ordinary outcome — research that concluded nothing,
        // a channel that fixes no address kind. Named rather than folded, so a
        // register that is not filling can be told from research that is not
        // concluding.
        Ok(Recorded::Skipped(why)) => debug!(
            session_id = %session.id,
            reason = why.as_str(),
            "[IDENTITY-RESEARCH] nothing recorded in the register"
        ),
        Err(error) => warn!(
            session_id = %session.id,
            error = %error,
            "[IDENTITY-RESEARCH] the counterparty register refused what research concluded"
        ),
    }
}

fn public_contact_review_candidate_summary(
    profile: &PublicContactProfile,
    result: &PublicContactResearchResult,
) -> String {
    let mut parts = Vec::new();
    if let Some(identity) = result
        .possible_identity
        .as_deref()
        .and_then(non_empty_trimmed)
    {
        parts.push(format!("Possible identity: {identity}"));
    }
    if let Some(org) = result.org.as_deref().and_then(non_empty_trimmed) {
        parts.push(format!("Org: {org}"));
    }
    if let Some(role) = result.role.as_deref().and_then(non_empty_trimmed) {
        parts.push(format!("Role: {role}"));
    }
    parts.push(format!(
        "Confidence: {}",
        public_contact_research_confidence_label(&result.confidence)
    ));
    if !result.sources.is_empty() {
        parts.push(format!("Sources: {}", result.sources.len()));
    }
    if !result.warnings.is_empty() {
        parts.push(format!(
            "Warnings: {}",
            bounded_chat_memory_excerpt(&result.warnings.join("; "), 260)
        ));
    }
    if parts.is_empty() {
        parts.push(format!(
            "Public-contact research completed for {}.",
            profile.sender_key.as_storage_key()
        ));
    }
    parts.join(". ")
}

fn public_contact_research_evidence_refs(
    result: &PublicContactResearchResult,
    summary: &str,
    job_id: &str,
) -> Vec<LearningEvidenceRef> {
    let mut refs = vec![LearningEvidenceRef {
        kind: "identity_research_job".to_string(),
        id: Some(job_id.to_string()),
        path: None,
        uri: None,
        summary: Some("Queued public-chat identity research job.".to_string()),
    }];
    refs.push(LearningEvidenceRef {
        kind: "task".to_string(),
        id: Some(result.task_id.clone()),
        path: None,
        uri: None,
        summary: Some(bounded_chat_memory_excerpt(summary, 500)),
    });
    if let Some(output_id) = result.primary_user_output_id.as_deref() {
        refs.push(LearningEvidenceRef {
            kind: "task_output".to_string(),
            id: Some(output_id.to_string()),
            path: None,
            uri: None,
            summary: result.excerpt.clone(),
        });
    }
    refs
}

fn public_contact_research_confidence_score(
    confidence: &super::public_contact_profile::PublicContactProfileConfidence,
) -> Option<f64> {
    match confidence {
        super::public_contact_profile::PublicContactProfileConfidence::ResearchedHigh => Some(0.8),
        super::public_contact_profile::PublicContactProfileConfidence::ResearchedMedium => {
            Some(0.6)
        },
        super::public_contact_profile::PublicContactProfileConfidence::ResearchedLow => Some(0.35),
        super::public_contact_profile::PublicContactProfileConfidence::UserClaimed => Some(0.5),
        super::public_contact_profile::PublicContactProfileConfidence::OwnerReviewed => Some(1.0),
        super::public_contact_profile::PublicContactProfileConfidence::Unknown => None,
    }
}

fn public_contact_research_confidence_label(
    confidence: &super::public_contact_profile::PublicContactProfileConfidence,
) -> &'static str {
    match confidence {
        super::public_contact_profile::PublicContactProfileConfidence::Unknown => "unknown",
        super::public_contact_profile::PublicContactProfileConfidence::UserClaimed => {
            "user_claimed"
        },
        super::public_contact_profile::PublicContactProfileConfidence::OwnerReviewed => {
            "owner_reviewed"
        },
        super::public_contact_profile::PublicContactProfileConfidence::ResearchedLow => {
            "researched_low"
        },
        super::public_contact_profile::PublicContactProfileConfidence::ResearchedMedium => {
            "researched_medium"
        },
        super::public_contact_profile::PublicContactProfileConfidence::ResearchedHigh => {
            "researched_high"
        },
    }
}

fn redact_chat_memory_value(value: &Value) -> Value {
    redact_chat_memory_value_with_key(None, value)
}

fn redact_chat_memory_value_with_key(key: Option<&str>, value: &Value) -> Value {
    if key.is_some_and(is_sensitive_memory_key) {
        return Value::String("[REDACTED]".to_string());
    }
    match value {
        Value::String(text) => Value::String(redact_chat_memory_text(text)),
        Value::Array(items) => Value::Array(
            items
                .iter()
                .map(|item| redact_chat_memory_value_with_key(None, item))
                .collect(),
        ),
        Value::Object(map) => {
            let mut redacted = serde_json::Map::new();
            for (key, value) in map {
                redacted.insert(
                    key.clone(),
                    redact_chat_memory_value_with_key(Some(key.as_str()), value),
                );
            }
            Value::Object(redacted)
        },
        other => other.clone(),
    }
}

fn redact_chat_memory_text(text: &str) -> String {
    static PRIVATE_KEY_RE: OnceLock<regex::Regex> = OnceLock::new();
    static BEARER_RE: OnceLock<regex::Regex> = OnceLock::new();
    static KEY_VALUE_SECRET_RE: OnceLock<regex::Regex> = OnceLock::new();
    static COMMON_TOKEN_RE: OnceLock<regex::Regex> = OnceLock::new();

    let mut redacted = text.to_string();
    redacted = PRIVATE_KEY_RE
        .get_or_init(|| {
            regex::Regex::new(
                r"(?s)-----BEGIN [A-Z ]*PRIVATE KEY-----.*?-----END [A-Z ]*PRIVATE KEY-----",
            )
            .expect("valid private key redaction regex")
        })
        .replace_all(&redacted, "[REDACTED_PRIVATE_KEY]")
        .into_owned();
    redacted = BEARER_RE
        .get_or_init(|| {
            regex::Regex::new(r"(?i)\bbearer\s+[A-Za-z0-9._~+/=-]{8,}")
                .expect("valid bearer redaction regex")
        })
        .replace_all(&redacted, "Bearer [REDACTED]")
        .into_owned();
    redacted = KEY_VALUE_SECRET_RE
        .get_or_init(|| {
            regex::Regex::new(
                r#"(?i)\b(password|passwd|pwd|api[_-]?key|secret|token|access[_-]?token|refresh[_-]?token|authorization|cookie|session[_-]?id|client[_-]?secret|private[_ -]?key)\b\s*[:=]\s*["']?[^\s"',;}\]]+"#,
            )
            .expect("valid key-value secret redaction regex")
        })
        .replace_all(&redacted, "$1=[REDACTED]")
        .into_owned();
    COMMON_TOKEN_RE
        .get_or_init(|| {
            regex::Regex::new(
                r"\b(sk-[A-Za-z0-9_-]{10,}|gh[pousr]_[A-Za-z0-9_]{20,}|xox[baprs]-[A-Za-z0-9-]{10,})\b",
            )
            .expect("valid common token redaction regex")
        })
        .replace_all(&redacted, "[REDACTED_TOKEN]")
        .into_owned()
}

fn is_sensitive_memory_key(key: &str) -> bool {
    let normalized = key
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .collect::<String>()
        .to_ascii_lowercase();
    matches!(
        normalized.as_str(),
        "password"
            | "passwd"
            | "pwd"
            | "apikey"
            | "secret"
            | "token"
            | "accesstoken"
            | "refreshtoken"
            | "authorization"
            | "cookie"
            | "sessionid"
            | "clientsecret"
            | "privatekey"
    ) || normalized.ends_with("token")
        || normalized.ends_with("secret")
        || normalized.ends_with("password")
}

pub fn extract_chat_bad_request_message(error: &anyhow::Error) -> Option<String> {
    error
        .to_string()
        .strip_prefix(CHAT_BAD_REQUEST_PREFIX)
        .map(ToOwned::to_owned)
}

fn select_preferred_agent_id_for_thread(
    sessions: &[ChatSession],
    ui_thread_id: &str,
) -> Option<String> {
    let normalize = |agent_id: &str| {
        let trimmed = agent_id.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    };

    sessions
        .iter()
        .filter(|session| {
            session.ui_thread_id == ui_thread_id && session.status == ChatSessionStatus::Active
        })
        .max_by_key(|session| (session.updated_at, session.created_at))
        .and_then(|session| normalize(&session.agent_id))
        .or_else(|| {
            sessions
                .iter()
                .filter(|session| session.ui_thread_id == ui_thread_id)
                .max_by_key(|session| (session.created_at, session.updated_at))
                .and_then(|session| normalize(&session.agent_id))
        })
}

