    /// Repair a durable chat history whose last task-status row is still
    /// non-terminal even though the canonical V3 task is terminal.
    ///
    /// This is deliberately a read-time safety net in addition to the live
    /// watcher. Watchers are process-local; a restart can strand the display
    /// transcript at `running` while `task_state.json` and the execution record
    /// correctly say `failed`, `completed`, or `cancelled`. Returning the
    /// repaired row immediately removes zombie spinners for every client, and
    /// emitting it through the canonical chat bus makes the repair durable for
    /// later reads and for a subsequent Reset-to-Ready transition.
    pub async fn reconcile_terminal_task_status_messages(
        &self,
        session: &ChatSession,
        mut messages: Vec<ChatMessage>,
    ) -> Vec<ChatMessage> {
        let Some(v3) = self.artifact_v2_service.as_ref() else {
            return messages;
        };

        let mut latest_by_task: HashMap<String, (usize, i64)> = HashMap::new();
        for (index, message) in messages.iter().enumerate() {
            let ChatMessageContent::TaskStatusUpdate {
                task_id, status, ..
            } = &message.content
            else {
                continue;
            };
            if task_id.trim().is_empty() {
                continue;
            }
            let replace = latest_by_task
                .get(task_id)
                .map_or(true, |(_, timestamp)| message.created_at >= *timestamp);
            if replace {
                latest_by_task.insert(task_id.clone(), (index, message.created_at));
            }
            // A terminal row already in this response is canonical enough for
            // rendering; the task may since have been reset or re-run, but
            // historical terminal runs must not be rewritten as active.
            if matches!(status.as_str(), "completed" | "failed" | "cancelled") {
                continue;
            }
        }

        let candidates = latest_by_task.into_iter().collect::<Vec<_>>();
        for (task_id, (index, _)) in candidates {
            let Some(latest_message) = messages.get(index).cloned() else {
                continue;
            };
            let ChatMessageContent::TaskStatusUpdate {
                status: latest_status,
                display_label: latest_display_label,
                execution_id: latest_execution_id,
                ui_thread_id: latest_ui_thread_id,
                ..
            } = latest_message.content.clone()
            else {
                continue;
            };
            if matches!(latest_status.as_str(), "completed" | "failed" | "cancelled") {
                continue;
            }

            let (
                terminal_status,
                summary,
                execution_id,
                ui_thread_id,
                display_label,
                output_files,
                speech_tts,
            ) = match v3
                .get_task(
                    &ScopeRef::system_internal_unauthenticated(
                        &session.principal.clone(),
                        &session.workspace.clone(),
                    ),
                    &task_id,
                )
                .await
            {
                Ok(task) => {
                    // A task id mentioned in a card is not sufficient
                    // authority to surface another session's result.
                    if task.manifest.chat_session_id.as_deref() != Some(session.id.as_str()) {
                        continue;
                    }
                    let status = task.state.status.clone();
                    if !matches!(status.as_str(), "completed" | "failed" | "cancelled") {
                        continue;
                    }
                    if !task.state.synthesis_pending_executions.is_empty() {
                        continue;
                    }
                    let scope = ScopeRef::system_internal_unauthenticated(
                        &session.principal.clone(),
                        &session.workspace.clone(),
                    );
                    let summary =
                        V3ReadApi::get_task_progress_projection(v3.as_ref(), &scope, &task_id)
                            .await
                            .ok()
                            .and_then(|projection| projection.task.summary)
                            .filter(|value| !value.trim().is_empty())
                            .or_else(|| Some(Self::default_terminal_task_summary(&status)));
                    let execution_id = task
                        .state
                        .last_completed_root_execution_id
                        .clone()
                        .or_else(|| task.state.latest_root_execution_id.clone())
                        .or_else(|| task.state.active_root_execution_id.clone())
                        .or(latest_execution_id.clone());
                    let output_files =
                        project_task_outputs_for_chat_session(v3.as_ref(), session, &task_id).await;
                    let speech_tts = if status == "completed" {
                        v3.read_voice_speech_summary(&scope, &task_id)
                            .await
                            .and_then(|speech| speech.tts)
                            .map(|value| value.trim().to_string())
                            .filter(|value| !value.is_empty())
                    } else {
                        None
                    };
                    (
                        status,
                        summary,
                        execution_id,
                        Some(task.manifest.ui_thread_id.clone()),
                        latest_display_label
                            .clone()
                            .or_else(|| Some(task.manifest.agent_id.clone())),
                        output_files,
                        speech_tts,
                    )
                },
                Err(ArtifactV2Error::TaskNotFound(_)) => (
                    "cancelled".to_string(),
                    Some("Task is no longer available; its execution is not running.".to_string()),
                    latest_execution_id.clone(),
                    latest_ui_thread_id.clone(),
                    latest_display_label.clone(),
                    Vec::new(),
                    None,
                ),
                Err(error) => {
                    warn!(
                        session_id = %session.id,
                        task_id,
                        error = %error,
                        "[CHAT] terminal task reconciliation could not read canonical task"
                    );
                    continue;
                },
            };

            // Pagination can ask for an older page whose last local row is
            // running even though a newer terminal row already exists in the
            // store. Match the concrete execution when one exists: a terminal
            // first run must not suppress repair of a later failed rerun under
            // the same task id.
            if Self::chat_already_has_terminal_task_status(
                self.chat_store.as_ref(),
                &session.id,
                &task_id,
                execution_id.as_deref(),
            )
            .await
            {
                continue;
            }

            let reconciliation_key = format!(
                "{}::{}::{}",
                session.id,
                task_id,
                execution_id.as_deref().unwrap_or("none")
            );
            // This is only a short-lived race guard while the asynchronous
            // ChatStoreSink catches up. Bound it so a long-running service
            // cannot retain one key for every historical task forever. Once
            // cleared, the durable terminal-row check above remains the
            // authoritative deduplication layer.
            if self.terminal_status_reconciliations.len() >= 1_024 {
                self.terminal_status_reconciliations.clear();
            }
            let message = ChatMessage::new(
                format!(
                    "task-status-reconcile-{}-{}-{}",
                    task_id,
                    execution_id.as_deref().unwrap_or("none"),
                    terminal_status
                ),
                session.id.clone(),
                ChatMessageDirection::System,
                ChatMessageContent::TaskStatusUpdate {
                    task_id: task_id.clone(),
                    status: terminal_status,
                    display_label,
                    summary,
                    execution_id,
                    ui_thread_id,
                    output_files,
                    synthesis_pending: false,
                    speech_tts,
                },
                Utc::now()
                    .timestamp_millis()
                    .max(latest_message.created_at + 1),
            )
            .with_chat_turn_id(latest_message.chat_turn_id.clone())
            .with_source_surface(latest_message.source_surface.clone())
            .with_presence_session_id(latest_message.presence_session_id.clone())
            .with_voice_origin(None)
            .with_speech_segments(None);

            if self
                .terminal_status_reconciliations
                .insert(reconciliation_key.clone(), ())
                .is_none()
            {
                if let Err(error) = self.persist_display_message(session, message.clone()).await {
                    self.terminal_status_reconciliations
                        .remove(&reconciliation_key);
                    warn!(
                        session_id = %session.id,
                        task_id,
                        error = %error,
                        "[CHAT] failed to persist reconciled terminal task status"
                    );
                }
            }
            messages.push(message);
        }

        messages.sort_by(|left, right| {
            left.created_at
                .cmp(&right.created_at)
                .then_with(|| left.id.cmp(&right.id))
        });
        messages
    }

    fn public_chat_durable_state_path(workspace: &ArtifactV2Workspace) -> PathBuf {
        workspace
            .system_root()
            .join("public_chat")
            .join("runtime_state.json")
    }

    fn restore_public_chat_durable_state_from_disk_sync(&self) {
        if self.public_chat_admission.is_none() {
            return;
        }
        let Some(service) = self.artifact_v2_service.as_ref() else {
            return;
        };
        let workspace = service.workspace();
        let path = Self::public_chat_durable_state_path(workspace);
        let state = match workspace.read_json_path_sync::<PublicChatDurableState, _>(&path) {
            Ok(state) => state,
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                return;
            },
            Err(error) => {
                self.record_public_chat_durable_restore_failure(&path, error.to_string());
                warn!(
                    path = %path.display(),
                    error = %error,
                    "[PUBLIC-CHAT] failed to restore durable state"
                );
                return;
            },
        };
        if state.schema_version > PUBLIC_CHAT_DURABLE_STATE_SCHEMA_VERSION {
            warn!(
                path = %path.display(),
                schema_version = state.schema_version,
                supported_schema_version = PUBLIC_CHAT_DURABLE_STATE_SCHEMA_VERSION,
                "[PUBLIC-CHAT] skipping newer durable state schema"
            );
            self.record_public_chat_durable_restore_failure(
                &path,
                format!(
                    "newer schema {} > supported {}",
                    state.schema_version, PUBLIC_CHAT_DURABLE_STATE_SCHEMA_VERSION
                ),
            );
            return;
        }
        let saved_at_ms = state.saved_at_ms;
        let schema_version = state.schema_version;
        let restored_public_chat_queue_depth = state.public_chat_queue.len();
        let restored_identity_research_queue_depth = state.identity_research_queue.len();

        if let Some(admission) = self.public_chat_admission.as_ref() {
            admission.restore_ledger(state.public_chat_daily_ledger);
        }
        {
            let mut queue = self
                .public_chat_queue
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            *queue = state.public_chat_queue.into_iter().collect();
            self.rebuild_public_chat_queue_sender_depths(&queue);
        }
        {
            let mut ledger = self
                .identity_research_daily_ledger
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            *ledger = state.identity_research_daily_ledger;
            if let Some(policy) = self.identity_research_policy() {
                Self::refresh_identity_research_daily_ledger(&mut ledger, &policy);
            }
        }
        {
            let mut queue = self
                .identity_research_queue
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            *queue = state.identity_research_queue.into_iter().collect();
            self.rebuild_identity_research_sender_depths(&queue);
        }
        self.record_public_chat_durable_restore_success(
            &path,
            saved_at_ms,
            schema_version,
            restored_public_chat_queue_depth,
            restored_identity_research_queue_depth,
        );
    }

    fn rebuild_public_chat_queue_sender_depths(&self, queue: &VecDeque<PublicChatQueuedTurn>) {
        self.public_chat_queue_sender_depths.clear();
        for turn in queue {
            self.public_chat_queue_sender_depths
                .entry(turn.contact_key.clone())
                .and_modify(|depth| *depth = depth.saturating_add(1))
                .or_insert(1);
        }
    }

    fn rebuild_identity_research_sender_depths(&self, queue: &VecDeque<IdentityResearchJob>) {
        self.identity_research_sender_depths.clear();
        for job in queue {
            self.identity_research_sender_depths
                .entry(job.contact_key.clone())
                .and_modify(|depth| *depth = depth.saturating_add(1))
                .or_insert(1);
        }
    }

    fn public_chat_durable_state_snapshot(&self) -> PublicChatDurableState {
        let public_chat_daily_ledger = self
            .public_chat_admission
            .as_ref()
            .map(|admission| admission.ledger_snapshot())
            .unwrap_or_default();
        let public_chat_queue = self
            .public_chat_queue
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .iter()
            .cloned()
            .collect();
        let identity_research_daily_ledger = {
            let mut ledger = self
                .identity_research_daily_ledger
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            if let Some(policy) = self.identity_research_policy() {
                Self::refresh_identity_research_daily_ledger(&mut ledger, &policy);
            }
            ledger.clone()
        };
        let identity_research_queue = self
            .identity_research_queue
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .iter()
            .cloned()
            .collect();

        PublicChatDurableState {
            schema_version: PUBLIC_CHAT_DURABLE_STATE_SCHEMA_VERSION,
            saved_at_ms: Utc::now().timestamp_millis(),
            public_chat_daily_ledger,
            public_chat_queue,
            identity_research_daily_ledger,
            identity_research_queue,
        }
    }

    async fn persist_public_chat_durable_state(&self) -> Result<()> {
        let _guard = self.public_chat_state_save_lock.lock().await;
        let Some(service) = self.artifact_v2_service.as_ref() else {
            return Ok(());
        };
        let workspace = service.workspace();
        let path = Self::public_chat_durable_state_path(workspace);
        let state = self.public_chat_durable_state_snapshot();
        if let Some(parent) = path.parent() {
            workspace
                .create_dir_all_path(parent)
                .await
                .context("failed to create public-chat durable state directory")?;
        }
        workspace
            .write_json_atomic_path(&path, &state)
            .await
            .context("failed to write public-chat durable state")?;
        self.record_public_chat_durable_save_success(&path, state.saved_at_ms);
        Ok(())
    }

    fn spawn_public_chat_durable_state_save(&self) {
        let Some(service) = self.self_arc() else {
            return;
        };
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            return;
        };
        handle.spawn(async move {
            if let Err(error) = service.persist_public_chat_durable_state().await {
                service.record_public_chat_durable_save_failure(error.to_string());
                warn!(
                    error = %error,
                    "[PUBLIC-CHAT] failed to persist durable state"
                );
            }
        });
    }

    fn record_public_chat_durable_restore_success(
        &self,
        path: &Path,
        restored_state_saved_at_ms: i64,
        restored_schema_version: u32,
        restored_public_chat_queue_depth: usize,
        restored_identity_research_queue_depth: usize,
    ) {
        let mut metrics = self
            .public_chat_durable_metrics
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        metrics.path = Some(path.display().to_string());
        metrics.last_restored_at_ms = Some(Utc::now().timestamp_millis());
        metrics.restored_state_saved_at_ms = Some(restored_state_saved_at_ms);
        metrics.restored_schema_version = Some(restored_schema_version);
        metrics.restored_public_chat_queue_depth = restored_public_chat_queue_depth;
        metrics.restored_identity_research_queue_depth = restored_identity_research_queue_depth;
        metrics.last_error = None;
    }

    fn record_public_chat_durable_restore_failure(&self, path: &Path, error: String) {
        let mut metrics = self
            .public_chat_durable_metrics
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        metrics.path = Some(path.display().to_string());
        metrics.restore_failures = metrics.restore_failures.saturating_add(1);
        metrics.last_error = Some(format!("restore: {error}"));
    }

    fn record_public_chat_durable_save_success(&self, path: &Path, saved_at_ms: i64) {
        let mut metrics = self
            .public_chat_durable_metrics
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        metrics.path = Some(path.display().to_string());
        metrics.last_saved_at_ms = Some(saved_at_ms);
        metrics.last_error = None;
    }

    fn record_public_chat_durable_save_failure(&self, error: String) {
        let mut metrics = self
            .public_chat_durable_metrics
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        metrics.save_failures = metrics.save_failures.saturating_add(1);
        metrics.last_error = Some(format!("save: {error}"));
    }

    fn public_chat_durable_state_snapshot_for_api(&self) -> PublicChatDurableStateSnapshot {
        let mut metrics = self
            .public_chat_durable_metrics
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .clone();
        if metrics.path.is_none() {
            if let Some(service) = self.artifact_v2_service.as_ref() {
                metrics.path = Some(
                    Self::public_chat_durable_state_path(service.workspace())
                        .display()
                        .to_string(),
                );
            }
        }
        PublicChatDurableStateSnapshot {
            path: metrics.path,
            last_saved_at_ms: metrics.last_saved_at_ms,
            last_restored_at_ms: metrics.last_restored_at_ms,
            restored_state_saved_at_ms: metrics.restored_state_saved_at_ms,
            restored_schema_version: metrics.restored_schema_version,
            restored_public_chat_queue_depth: metrics.restored_public_chat_queue_depth,
            restored_identity_research_queue_depth: metrics.restored_identity_research_queue_depth,
            save_failures: metrics.save_failures,
            restore_failures: metrics.restore_failures,
            last_error: metrics.last_error,
        }
    }

    pub async fn cancel_execution_for_scope(
        &self,
        principal: &str,
        workspace: &str,
        execution_id: &str,
    ) -> Result<bool, String> {
        let Some(service) = self.artifact_v2_service.as_ref() else {
            return Ok(false);
        };
        let scope = ScopeRef::system_internal_unauthenticated(
            &principal.to_string(),
            &workspace.to_string(),
        );
        service
            .cancel_execution_by_id(&scope, execution_id)
            .await
            .map(|_| true)
            .map_err(|error| error.to_string())
    }

