    /// Runtime-only public-chat admission, queue, and research snapshot.
    pub fn public_chat_observability_snapshot(&self) -> PublicChatObservabilitySnapshot {
        let now_ms = Utc::now().timestamp_millis();
        let Some(admission) = self.public_chat_admission.as_ref() else {
            return PublicChatObservabilitySnapshot {
                enabled: false,
                source_surface: None,
                source_surfaces: Vec::new(),
                paid_operation: None,
                fallback_operation: None,
                durable_state: self.public_chat_durable_state_snapshot_for_api(),
                admission: PublicChatAdmissionSnapshot::default(),
                queue: PublicChatQueueSnapshot::default(),
                identity_research: None,
            };
        };

        let queue = {
            let queue = self
                .public_chat_queue
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            PublicChatQueueSnapshot {
                queued: queue.len(),
                max_global_queue_depth: admission.policy.max_global_queue_depth,
                sender_depths: self.public_chat_queue_sender_depths.len(),
                max_per_sender_queue_depth: admission.policy.max_per_sender_queue_depth,
                worker_active: self.public_chat_queue_worker_active.load(Ordering::SeqCst),
                oldest_age_ms: queue
                    .front()
                    .map(|turn| now_ms.saturating_sub(turn.queued_at_ms)),
                coalesce_window_ms: admission.policy.coalesce_window_ms,
                max_queue_wait_ms: admission.policy.max_queue_wait_ms,
            }
        };

        let identity_research = admission.policy.identity_research.as_ref().map(|policy| {
            let research_queue = self
                .identity_research_queue
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            let mut ledger = self
                .identity_research_daily_ledger
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            Self::refresh_identity_research_daily_ledger(&mut ledger, policy);
            PublicChatIdentityResearchSnapshot {
                enabled: policy.enabled,
                worker_agent_id: policy.worker_agent_id.clone(),
                queued: research_queue.len(),
                max_global_queue_depth: policy.max_global_queue_depth,
                sender_depths: self.identity_research_sender_depths.len(),
                max_per_sender_queue_depth: policy.max_per_sender_queue_depth,
                active: self.identity_research_active_count.load(Ordering::SeqCst),
                max_concurrent: policy.max_concurrent,
                worker_active: self.identity_research_worker_active.load(Ordering::SeqCst),
                day_key: ledger.day_key.clone(),
                queued_jobs_today: ledger.queued_jobs,
                completed_jobs_today: ledger.completed_jobs,
                cost_attributed_jobs_today: ledger.cost_attributed_jobs,
                llm_calls_today: ledger.llm_calls,
                input_tokens_today: ledger.input_tokens,
                output_tokens_today: ledger.output_tokens,
                reasoning_tokens_today: ledger.reasoning_tokens,
                max_jobs_today: policy.daily_limit.max_jobs,
                cost_usd_today: ledger.cost_usd,
                max_cost_usd_today: policy.daily_limit.max_cost_usd,
            }
        });

        PublicChatObservabilitySnapshot {
            enabled: true,
            source_surface: Some(admission.policy.source_surface.clone()),
            source_surfaces: admission
                .policy
                .effective_source_surfaces()
                .into_iter()
                .map(ToOwned::to_owned)
                .collect(),
            paid_operation: Some(admission.policy.paid_operation.clone()),
            fallback_operation: Some(admission.policy.fallback_operation.clone()),
            durable_state: self.public_chat_durable_state_snapshot_for_api(),
            admission: admission.snapshot(),
            queue,
            identity_research,
        }
    }

