/// Operator-safe projection of one canonical policy snapshot. Schemas and
/// parameter-deny values stay server-side; the Crew page receives only names,
/// descriptions, category/dispatch state, target ceilings, and provenance.
#[derive(Debug, Clone, Serialize)]
pub struct EffectiveToolPolicyPreview {
    pub schema_version: &'static str,
    pub generated_at: DateTime<Utc>,
    pub snapshot_id: String,
    pub agent_id: String,
    pub definition_version: u32,
    pub definition_digest: String,
    pub trust_level: String,
    pub selected_surface: crate::magician_v2::agents::InvocationSurface,
    pub feature_mode: crate::magician_v2::agents::FeatureMode,
    pub source_kind: crate::magician_v2::agents::InvocationSourceKind,
    pub available_surfaces: Vec<EffectiveToolPolicyPreviewSurface>,
    pub direct: Vec<EffectiveToolPolicyPreviewGrant>,
    pub runtime: Vec<EffectiveToolPolicyPreviewGrant>,
    pub structural: Vec<EffectiveToolPolicyPreviewStructuralGrant>,
    pub deferred: Vec<EffectiveToolPolicyPreviewGrant>,
    pub internal: Vec<EffectiveToolPolicyPreviewInternalGrant>,
    pub delegation_targets: Vec<String>,
    pub handover_targets: Vec<String>,
    pub denied_tool_names: Vec<String>,
    pub approval_rule_count: usize,
    pub provider_tool_count: usize,
    pub dispatch_tool_count: usize,
}

impl EffectiveToolPolicyPreview {
    fn from_snapshot(
        snapshot: &crate::magician_v2::execution::agentic::EffectiveToolPolicySnapshot,
        available_surfaces: Vec<EffectiveToolPolicyPreviewSurface>,
    ) -> Self {
        let descriptions = snapshot
            .provider_specs
            .iter()
            .map(|tool| (tool.name.as_str(), tool.description.as_str()))
            .collect::<HashMap<_, _>>();
        let project_grant = |grant: &crate::magician_v2::execution::agentic::policy_snapshot::EffectiveToolGrant| {
            EffectiveToolPolicyPreviewGrant {
                name: grant.name.clone(),
                description: descriptions
                    .get(grant.name.as_str())
                    .map(|value| (*value).to_string()),
                provider_visible: grant.provider_visible,
                dispatchable: snapshot.permits_tool(&grant.name),
                requires_approval: false,
            }
        };
        let direct = snapshot.direct_tools.values().map(project_grant).collect();
        let runtime = snapshot.runtime_tools.values().map(project_grant).collect();
        let deferred = snapshot
            .deferred_tools
            .values()
            .map(project_grant)
            .collect();
        let structural = snapshot
            .structural_tools
            .values()
            .map(|grant| EffectiveToolPolicyPreviewStructuralGrant {
                name: grant.name.clone(),
                description: descriptions
                    .get(grant.name.as_str())
                    .map(|value| (*value).to_string()),
                provider_visible: true,
                dispatchable: snapshot.permits_tool(&grant.name),
                requires_approval: grant.requires_approval,
                allowed_targets: grant.allowed_targets.iter().cloned().collect(),
            })
            .collect();
        let internal = snapshot
            .implicit_tools
            .iter()
            .map(|name| EffectiveToolPolicyPreviewInternalGrant {
                name: name.clone(),
                dispatchable: snapshot.permits_implicit_tool(name),
            })
            .collect();

        Self {
            schema_version: "effective_tool_policy_preview.v1",
            generated_at: Utc::now(),
            snapshot_id: snapshot.snapshot_id.clone(),
            agent_id: snapshot.agent_id.clone(),
            definition_version: snapshot.definition_version,
            definition_digest: snapshot.definition_digest.clone(),
            trust_level: snapshot.trust_level.clone(),
            selected_surface: snapshot.invocation.surface,
            feature_mode: snapshot.invocation.feature_mode,
            source_kind: snapshot.invocation.source_kind,
            available_surfaces,
            direct,
            runtime,
            structural,
            deferred,
            internal,
            delegation_targets: snapshot.delegation_targets.keys().cloned().collect(),
            handover_targets: snapshot.handover_targets.keys().cloned().collect(),
            denied_tool_names: snapshot.denied_tool_names.iter().cloned().collect(),
            approval_rule_count: snapshot.approval_rules.len(),
            provider_tool_count: snapshot.provider_specs.len(),
            dispatch_tool_count: snapshot.dispatch_tool_names.len(),
        }
    }
}

