    struct TinyChunkReader<R> {
        inner: R,
        chunk_bytes: usize,
    }

    impl<R: std::io::Read> std::io::Read for TinyChunkReader<R> {
        fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {
            let take = buffer.len().min(self.chunk_bytes);
            self.inner.read(&mut buffer[..take])
        }
    }

    fn delegate_status_event(task_id: &str, execution_id: &str, status: &str) -> String {
        serde_json::json!({
            "data": {
                "event": {
                    "event_type": "chat.delegate.status_changed",
                    "agent_id": "personal-assistant",
                    "payload": {
                        "task_id": task_id,
                        "execution_id": execution_id,
                        "status": status,
                        "target_agent_id": "web-researcher",
                        "origin_agent_id": "personal-assistant",
                        "chat_session_id": "session-1"
                    }
                }
            }
        })
        .to_string()
    }

    #[test]
    fn orphan_delegate_scan_streams_large_split_histories_and_keeps_old_unresolved_rows() {
        let old_unresolved = delegate_status_event("task-old", "exec-old", "running");
        let later_resolved = delegate_status_event("task-done", "exec-done", "running");
        let terminal = delegate_status_event("task-done", "exec-done", "completed");
        let mut journal = String::new();
        journal.push_str(&old_unresolved);
        journal.push('\n');
        journal.push_str("{malformed json}\n");
        for index in 0..20_000 {
            journal.push_str(&format!(
                "{{\"data\":{{\"event\":{{\"event_type\":\"unrelated.{index}\"}}}}}}\n"
            ));
        }
        journal.push_str(&later_resolved);
        journal.push('\n');
        journal.push_str(&terminal);

        let reader = TinyChunkReader {
            inner: std::io::Cursor::new(journal.as_bytes()),
            chunk_bytes: 7,
        };
        let orphans = find_orphan_delegates_in_jsonl_reader(reader).expect("stream scan");

        assert_eq!(orphans.len(), 1);
        assert_eq!(orphans[0].task_id, "task-old");
        assert_eq!(orphans[0].execution_id, "exec-old");
    }

    #[test]
    fn orphan_delegate_scan_skips_one_oversized_record_without_losing_following_history() {
        let mut journal = vec![b'x'; CHAT_TURN_EVENT_RECOVERY_MAX_RECORD_BYTES + 1];
        journal.push(b'\n');
        journal.extend_from_slice(
            delegate_status_event("task-after", "exec-after", "running").as_bytes(),
        );

        let orphans = find_orphan_delegates_in_jsonl_reader(std::io::Cursor::new(journal))
            .expect("stream scan");

        assert_eq!(orphans.len(), 1);
        assert_eq!(orphans[0].task_id, "task-after");
    }

