    #[test]
    fn file_index_publish_readback_requires_the_exact_intended_index() {
        let expected = ChatSessionFileRecord {
            id: "tout-expected".to_string(),
            stored_name: "expected.bin".to_string(),
            original_name: "source.bin".to_string(),
            mime_type: "application/octet-stream".to_string(),
            size: 42,
            label: None,
            screen_capture: None,
            prompt_image: false,
            origin: ChatSessionFileOrigin::ToolOutput {
                tool_name: "task_output".to_string(),
                tool_call_id: None,
            },
            source_task_output_id: Some("output-1".to_string()),
            source_task_id: Some("task-1".to_string()),
            created_at: 123,
        };
        let expected_index = ChatSessionFileIndex {
            files: vec![expected.clone()],
        };
        let mut published = expected_index.clone();

        assert_eq!(published, expected_index);

        // Sharing the id or source key is insufficient: readback must prove
        // that the complete index written by this transaction became visible.
        published.files[0].size += 1;
        assert_ne!(published, expected_index);

        published = expected_index.clone();
        published.files.push(expected);
        assert_ne!(published, expected_index);
    }

