    fn chat_tool_test_agent(
        trust_level: &str,
        tools: &[&str],
        excluded_tools: &[&str],
        denied_tools: &[&str],
    ) -> crate::magician_v2::agents::types::AgentDefinition {
        let mut definition: crate::magician_v2::agents::types::AgentDefinition =
            serde_yaml::from_str("name: Test agent\npersona: Test persona\nkind: worker\n")
                .expect("minimal test agent definition should deserialize");
        definition.trust_level =
            crate::magician_v2::agents::types::TrustLevel(trust_level.to_string());
        definition.tools = tools.iter().map(|value| (*value).to_string()).collect();
        definition.excluded_tools = excluded_tools
            .iter()
            .map(|value| (*value).to_string())
            .collect();
        definition.denied_tools = denied_tools
            .iter()
            .map(|value| (*value).to_string())
            .collect();
        definition
    }

