    #[test]
    fn chat_authorization_definition_digest_ignores_hash_map_iteration_order() {
        fn denied_params(
            indices: impl Iterator<Item = usize>,
        ) -> HashMap<String, HashMap<String, Vec<String>>> {
            let mut outer = HashMap::new();
            for index in indices {
                let mut inner = HashMap::new();
                inner.insert(
                    format!("argument_{:02}", 23 - index),
                    vec![format!("blocked/{index}")],
                );
                inner.insert(
                    format!("argument_{index:02}"),
                    vec![format!("private/{index}")],
                );
                outer.insert(format!("tool_{index:02}"), inner);
            }
            outer
        }

        let mut forward = chat_tool_test_agent("local", &["screen-draw"], &[], &[]);
        forward.denied_tool_params = denied_params(0..24);
        let mut reverse = chat_tool_test_agent("local", &["screen-draw"], &[], &[]);
        reverse.denied_tool_params = denied_params((0..24).rev());

        assert_eq!(forward, reverse, "fixtures must be semantically identical");
        assert_eq!(
            chat_definition_digest(&forward).expect("forward chat authorization digest"),
            chat_definition_digest(&reverse).expect("reverse chat authorization digest")
        );
        assert_eq!(
            chat_definition_digest(&forward).expect("chat authorization digest"),
            crate::magician_v2::execution::agentic::policy_snapshot::canonical_definition_digest(
                &forward
            )
            .expect("canonical policy definition digest")
        );
    }

    #[test]
    fn crew_effective_tool_preview_projects_the_canonical_snapshot_without_schemas() {
        use crate::magician_v2::{
            agents::{
                AgentInvocationContext, FeatureMode, InvocationSourceKind, InvocationSurface,
            },
            execution::agentic::{resolve_effective_tool_policy_snapshot, SnapshotResolutionInput},
        };

        let mut definition =
            chat_tool_test_agent("local", &["direct_tool", "runtime_tool"], &[], &["blocked"]);
        definition.agent_id = "preview-agent".to_string();
        let provider_tool = |name: &str| NativeExecutionTool {
            name: name.to_string(),
            description: format!("{name} description"),
            parameters: serde_json::json!({
                "type": "object",
                "properties": { "secret_shape": { "type": "string" } }
            }),
            is_control_tool: false,
        };
        let snapshot = resolve_effective_tool_policy_snapshot(
            &definition,
            AgentInvocationContext {
                principal: "principal".to_string(),
                workspace: "workspace".to_string(),
                source_agent_id: None,
                target_agent_id: definition.agent_id.clone(),
                surface: InvocationSurface::Chat,
                feature_mode: FeatureMode::None,
                source_kind: InvocationSourceKind::Direct,
                chat_session_id: None,
                chat_turn_id: None,
            },
            SnapshotResolutionInput {
                provider_tools: vec![provider_tool("direct_tool"), provider_tool("runtime_tool")],
                runtime_tool_names: BTreeSet::from(["runtime_tool".to_string()]),
                deferred_tool_names: BTreeSet::from(["later_tool".to_string()]),
                direct_reachable_tool_names: BTreeSet::from([
                    "direct_tool".to_string(),
                    "runtime_tool".to_string(),
                    "later_tool".to_string(),
                    "task_state_action".to_string(),
                ]),
                implicit_tool_names: BTreeSet::from(["task_state_action".to_string()]),
                ..Default::default()
            },
        )
        .expect("canonical policy snapshot");

        let preview = EffectiveToolPolicyPreview::from_snapshot(
            snapshot.as_ref(),
            vec![EffectiveToolPolicyPreviewSurface::from(
                InvocationSurface::Chat,
            )],
        );
        assert_eq!(preview.snapshot_id, snapshot.snapshot_id);
        assert_eq!(preview.direct[0].name, "direct_tool");
        assert_eq!(preview.runtime[0].name, "runtime_tool");
        assert_eq!(preview.deferred[0].name, "later_tool");
        assert_eq!(preview.internal[0].name, "task_state_action");
        assert_eq!(preview.denied_tool_names, ["blocked"]);
        let serialized = serde_json::to_string(&preview).expect("serialize preview");
        assert!(!serialized.contains("secret_shape"));
        assert!(!serialized.contains("parameters"));
        assert!(!serialized.contains("denied_tool_params"));
    }

