    #[test]
    fn realtime_setup_deadline_reports_each_unstarted_stage_as_timed_out() {
        let outcome = realtime_context_setup_timeout(300);

        assert_eq!(outcome.status, RealtimeTurnContextStatus::TimedOut);
        assert!(outcome.context.is_none());
        assert_eq!(outcome.memory_candidate_count, 0);
        assert_eq!(outcome.procedure_count, 0);
        assert_eq!(
            outcome.fast_memory_stage_status,
            crate::magician_v2::context_retrieval::ContextStageState::TimedOut
        );
        assert_eq!(
            outcome.memory_stage_status,
            crate::magician_v2::context_retrieval::ContextStageState::TimedOut
        );
        assert_eq!(
            outcome.procedure_stage_status,
            crate::magician_v2::context_retrieval::ContextStageState::TimedOut
        );
    }

    /// A room's meeting notes ride alongside retrieval, not inside it. They must
    /// therefore survive an empty or timed-out retrieval: the turn a room most
    /// needs its own meeting state is the turn memory lookup found nothing.
    /// `status` stays a statement about retrieval and does NOT move because a
    /// meeting block is present.
    #[test]
    fn a_room_block_reaches_the_provider_even_when_retrieval_found_nothing() {
        let mut outcome = realtime_context_setup_timeout(300);
        outcome.meeting_context = Some("So far in this meeting: we picked Friday.".to_string());

        assert_eq!(
            outcome.injectable_context().as_deref(),
            Some("So far in this meeting: we picked Friday.")
        );
        assert_eq!(
            outcome.status,
            RealtimeTurnContextStatus::TimedOut,
            "a meeting block is not a retrieval stage and must not relabel the turn"
        );
    }

    /// When both halves exist the meeting block leads, so the room's own state
    /// frames whatever retrieval found rather than trailing it.
    #[test]
    fn the_meeting_block_leads_the_retrieved_context() {
        let mut outcome = realtime_context_setup_timeout(300);
        outcome.context = Some("retrieved".to_string());
        outcome.meeting_context = Some("meeting".to_string());

        assert_eq!(
            outcome.injectable_context().as_deref(),
            Some("meeting\n\nretrieved")
        );
    }

    /// An owner call carries no meeting block, so this plan cannot alter what an
    /// owner turn injects.
    #[test]
    fn an_owner_turn_injects_exactly_what_retrieval_returned() {
        let mut outcome = realtime_context_setup_timeout(300);
        outcome.context = Some("retrieved".to_string());

        assert_eq!(outcome.injectable_context().as_deref(), Some("retrieved"));

        outcome.context = None;
        assert!(outcome.injectable_context().is_none());
    }

    /// The room-context gate reads the SURFACE's audience, not "a meeting exists
    /// on this thread". Pin both directions: the room surface is untrusted, and
    /// every other voice source (including an absent one) stays an owner call.
    /// A room reads no agent memory. The tiers accumulate across every room and
    /// contact the agent has spoken to and carry no record of which one produced
    /// an entry, so there is no way to hand a room "only its own" — the honest
    /// answer is none.
    /// Delegation from an untrusted surface is refused at depth 0 — the FIRST
    /// hop is the one that must not happen, because a delegate holds its own
    /// grant and the room would be reaching it through a proxy.
    ///
    /// Pinned over every surface rather than for the meeting alone: the shipped
    /// ambassador's `delegation_targets` is empty, so a test that only checked
    /// today's configuration would pass even if the surface gate were removed.
    #[test]
    fn no_untrusted_surface_may_delegate() {
        use crate::magician_v2::agents::{InvocationSurface, SurfaceAudience};

        for surface in InvocationSurface::ALL {
            let permitted = surface_may_delegate(surface);
            match surface.audience() {
                SurfaceAudience::Untrusted => assert!(
                    !permitted,
                    "{} is untrusted and must not reach a delegate",
                    surface.as_str()
                ),
                SurfaceAudience::Owner => assert!(
                    permitted,
                    "{} lost delegation; this must not alter owner behaviour",
                    surface.as_str()
                ),
            }
        }
    }

    /// A fabricated call to a sealed tool must fail without revealing that the
    /// tool exists. Otherwise the refusal is an enumeration oracle: a room calls
    /// candidate names and learns the owner's capability surface from which ones
    /// come back "denied" rather than "no such tool".
    ///
    /// Asserted by INDISTINGUISHABILITY rather than by matching wording — the
    /// refusal for a real-but-ungranted tool and for an invented one must differ
    /// only in the name the caller itself supplied.
    #[test]
    fn a_sealed_tool_refusal_does_not_reveal_that_the_tool_exists() {
        let real_but_ungranted = tool_absent_from_snapshot_refusal("search_memory", "snapshot-1");
        let never_existed =
            tool_absent_from_snapshot_refusal("totally_invented_tool_xyz", "snapshot-1");

        assert_eq!(
            real_but_ungranted.replace("search_memory", "<name>"),
            never_existed.replace("totally_invented_tool_xyz", "<name>"),
            "the refusal distinguishes a sealed tool from a nonexistent one, so it \
             can be used to enumerate sealed capabilities"
        );

        for leak in ["exists", "denied", "not authorized", "permission", "sealed"] {
            assert!(
                !real_but_ungranted.to_ascii_lowercase().contains(leak),
                "refusal leaks `{leak}`, which implies the tool is real: \
                 {real_but_ungranted}"
            );
        }
    }

    #[test]
    fn a_room_reads_no_agent_memory_while_every_other_surface_does() {
        use crate::magician_v2::agents::InvocationSurface;

        assert!(
            !surface_may_read_agent_memory(InvocationSurface::Meeting),
            "a room must not read tiers that accumulate across other rooms"
        );
        for surface in InvocationSurface::ALL {
            if surface == InvocationSurface::Meeting {
                continue;
            }
            assert!(
                surface_may_read_agent_memory(surface),
                "{} lost its memory read; this plan must not alter any surface \
                 except the room",
                surface.as_str()
            );
        }
    }

    /// The public ambassador surface KEEPS its memory, deliberately. Remembering
    /// a contact between messages is intended capability, made safe by
    /// `fully_isolated` rather than by withholding. Pinned separately from the
    /// loop above so narrowing it later is a visible decision rather than a
    /// side effect of "tighten every untrusted surface".
    #[test]
    fn the_public_ambassador_surface_keeps_its_memory() {
        use crate::magician_v2::agents::{InvocationSurface, SurfaceAudience};

        assert_eq!(
            InvocationSurface::PublicEnvoy.audience(),
            SurfaceAudience::Untrusted
        );
        assert!(
            surface_may_read_agent_memory(InvocationSurface::PublicEnvoy),
            "the gate is deliberately NOT keyed on audience(); public chat keeps \
             contact memory"
        );
    }

    /// The meeting axis: a later meeting cannot read an earlier one's memory,
    /// while a rejoin of the SAME meeting can.
    ///
    /// The failure this closes is the reason the surface gate above had to be
    /// all-or-nothing: an entry recorded WHICH SURFACE produced it, never which
    /// MEETING, so "this room's own material" was not expressible and a room
    /// had to be blinded entirely to stop it reading somebody else's.
    ///
    /// Asserted in both directions on purpose. A gate that denied everything
    /// would satisfy the containment half while leaving a rejoining room
    /// permanently blank — which is the regression this axis exists to avoid,
    /// and it would look identical from the containment side alone.
    #[test]
    fn a_room_reads_this_meetings_memory_and_no_other_meetings() {
        use crate::magician_v2::agents::retrieval_scope::{ContextLabel, RetrievalScope};
        use crate::magician_v2::agents::InvocationSurface;

        let mine = "meeting-weekly-sync-2026-08-18";
        let theirs = "meeting-board-review-2026-08-19";

        let read = agent_memory_read_for_call(InvocationSurface::Meeting, Some(mine));
        assert_eq!(
            read,
            AgentMemoryRead::ThisMeetingOnly(
                RetrievalScope::for_meeting(mine).expect("named meeting")
            )
        );
        assert!(
            read.permits_any(),
            "a room with a known binding reads nothing at all"
        );

        let scope = read.retrieval_scope();
        assert!(
            scope.admits(&ContextLabel::Meeting(mine.to_string())),
            "a rejoining room lost the material it produced itself"
        );
        assert!(
            !scope.admits(&ContextLabel::Meeting(theirs.to_string())),
            "a later meeting could read an earlier meeting's memory"
        );
        assert!(
            !scope.admits(&ContextLabel::Unlabelled),
            "unlabelled memory — which is everything consolidated before this \
             axis existed — was readable from a room"
        );
        assert!(
            !scope.admits(&ContextLabel::Neutral),
            "a room honoured a neutrality claim that was only ever made about \
             engagements"
        );
    }

    /// An episode carries the occasion it was produced in, so a room can read
    /// back its own episodic record and no other room's.
    ///
    /// Before this, `build_episode_candidate` hardcoded a null label for every
    /// episode, so the containment pass refused the whole corpus under a bound
    /// retrieval — including the episodes the asking room had just written.
    #[test]
    fn an_episode_candidate_carries_the_meeting_it_was_produced_in() {
        use crate::magician_v2::agents::retrieval_scope::{
            label_from_metadata, ContextLabel, RetrievalScope,
        };

        let mine = "meeting-weekly-sync-2026-09-02";
        let theirs = "meeting-other-2026-09-02";

        let mut room_episode = episode_candidate_fixture();
        room_episode.origin_meeting = Some(mine.to_string());
        let room_metadata = episode_candidate_metadata(&room_episode);
        assert_eq!(
            label_from_metadata(&room_metadata),
            ContextLabel::Meeting(mine.to_string())
        );

        let scope = RetrievalScope::for_meeting(mine).expect("named meeting");
        assert!(
            scope.admits_metadata(&room_metadata),
            "a rejoining room lost the episode it produced itself"
        );
        let other = RetrievalScope::for_meeting(theirs).expect("named meeting");
        assert!(
            !other.admits_metadata(&room_metadata),
            "a later meeting could read an earlier meeting's episode"
        );
    }

    /// An owner-surface episode names no occasion, and that must stay an
    /// explicit null rather than becoming a label: the distinction between
    /// "looked and found none" and "never looked" is what keeps the refusal
    /// under a bound retrieval honest.
    #[test]
    fn an_owner_episode_stays_unlabelled_and_unreadable_from_a_room() {
        use crate::magician_v2::agents::retrieval_scope::{
            label_from_metadata, ContextLabel, RetrievalScope,
        };

        let mut owner_episode = episode_candidate_fixture();
        owner_episode.origin_meeting = None;
        let metadata = episode_candidate_metadata(&owner_episode);

        assert!(
            metadata
                .get("engagement_scope")
                .is_some_and(serde_json::Value::is_null),
            "the label must be written as an explicit null, not omitted"
        );
        assert_eq!(label_from_metadata(&metadata), ContextLabel::Unlabelled);
        assert!(
            !RetrievalScope::for_meeting("meeting-any")
                .expect("named meeting")
                .admits_metadata(&metadata),
            "a room read an owner-surface episode"
        );
        assert!(
            RetrievalScope::Unbound.admits_metadata(&metadata),
            "an owner turn is unbound and was never narrowed"
        );
    }

    /// The metadata the ranker and the debug tooling read must survive the
    /// label change: this is the no-regression half of the same edit.
    #[test]
    fn episode_candidate_metadata_keeps_its_descriptive_fields() {
        let mut record = episode_candidate_fixture();
        record.origin_meeting = Some("meeting-1".to_string());
        let metadata = episode_candidate_metadata(&record);

        assert_eq!(
            metadata.get("candidate_kind").and_then(|v| v.as_str()),
            Some("episode")
        );
        assert_eq!(
            metadata.get("episode_id").and_then(|v| v.as_str()),
            Some(record.episode_id.as_str())
        );
        assert_eq!(
            metadata.get("goal_key").and_then(|v| v.as_str()),
            Some(record.goal_key.as_str())
        );
        assert_eq!(
            metadata.get("outcome_kind").and_then(|v| v.as_str()),
            Some(record.outcome_kind.as_str())
        );
        assert_eq!(
            metadata.get("completed_at").and_then(|v| v.as_str()),
            Some(record.completed_at.as_str())
        );
    }

    /// The index build reads episodes off disk into
    /// `EpisodeCandidateProjectionV1`; the query path converts the in-memory
    /// record into the same projection. If those two disagree about any field
    /// that feeds the composed search text, the content hash differs, the score
    /// key differs, and every episode silently scores zero. This pins them.
    #[test]
    fn the_disk_and_runtime_projections_of_an_episode_agree() {
        let mut record = episode_candidate_fixture();
        record.task_description = Some("a longer description".to_string());
        record.strategy_summary = Some("adaptive".to_string());
        record.context_at_start = Some("started from a clean tree".to_string());
        record.observations = vec!["first".to_string(), "second".to_string()];
        record.origin_meeting = Some("meeting-1".to_string());
        record.principal = Some("anonymous".to_string());
        record.workspace = Some("default".to_string());

        let from_record = episode_candidate_projection(&record);
        let from_disk: magician_vector_index::episode_candidates::EpisodeCandidateProjectionV1 =
            serde_json::from_value(serde_json::to_value(&record).expect("record serializes"))
                .expect("a written episode deserializes into the index projection");

        assert_eq!(
            from_record, from_disk,
            "the query path and the index build disagree about an episode's indexable fields"
        );
    }

    /// Same identity from both paths, expressed the way the index actually
    /// keys rows — this is the assertion that would fail if the search text
    /// composition ever forked.
    #[test]
    fn both_paths_produce_the_same_index_score_key() {
        use magician_vector_index::episode_candidates::episode_candidate_document;
        use magician_vector_index::memory_index::memory_candidate_index_score_key;

        let mut record = episode_candidate_fixture();
        record.observations = vec!["an observation".to_string()];

        let runtime = episode_candidate_document(
            "envoy",
            std::path::PathBuf::from("/tmp/ep-1.json"),
            episode_candidate_projection(&record),
        );
        let indexed = episode_candidate_document(
            "envoy",
            std::path::PathBuf::from("/tmp/ep-1.json"),
            serde_json::from_value(serde_json::to_value(&record).expect("record serializes"))
                .expect("projection"),
        );

        assert_eq!(
            memory_candidate_index_score_key(&runtime),
            memory_candidate_index_score_key(&indexed),
            "an indexed episode row would not bind to its runtime candidate"
        );
    }

    /// `new_memory_episode` leaves `task_title`, `task_id`, `task_description`,
    /// `strategy_summary`, `context_at_start` and `observations` empty, and the
    /// first four of those feed the composed search text. A fixture that left
    /// them unset would let a `serde(rename)` on any of them pass both pinning
    /// tests while forking the content hash in production, so the fixture sets
    /// every field the text composition reads.
    fn episode_candidate_fixture() -> crate::magician_v2::artifact_v2::memory::V3EpisodeRecord {
        use crate::magician_v2::agents::EpisodeOutcome;
        use crate::magician_v2::artifact_v2::memory::V3EpisodeRecord;

        let now = chrono::Utc::now();
        let mut record = V3EpisodeRecord::new_memory_episode(
            None,
            "envoy".to_string(),
            "ep-1".to_string(),
            "goal-1".to_string(),
            "manual".to_string(),
            1,
            now,
            None,
            now,
            now,
            &EpisodeOutcome::PartialProgress {
                summary: "did some of it".to_string(),
                remaining: "the rest".to_string(),
            },
            Vec::new(),
            Vec::new(),
            Vec::new(),
            None,
            None,
            None,
        );
        record.task_title = Some("ship the fix".to_string());
        record.task_id = Some("task_abc".to_string());
        record.task_description = Some("a longer description of the task".to_string());
        record.strategy_summary = Some("adaptive".to_string());
        record.context_at_start = Some("started from a clean tree".to_string());
        record.observations = vec!["an observation".to_string()];
        record
    }

    /// Unknown is never permission. A room that cannot name its occasion —
    /// a thread pinned by `MEET_BOT_THREAD`, an owner-shaped thread that
    /// resolved to a room surface — reads nothing, which is exactly what it
    /// read before this axis existed.
    #[test]
    fn a_room_with_no_resolvable_binding_reads_nothing() {
        use crate::magician_v2::agents::InvocationSurface;

        for binding in [
            None,
            Some(""),
            Some("   "),
            Some("general"),
            Some("meeting-bot"),
        ] {
            let binding = binding.and_then(crate::magician_v2::media_seam::meeting_binding_id);
            let read = agent_memory_read_for_call(InvocationSurface::Meeting, binding.as_deref());
            assert_eq!(
                read,
                AgentMemoryRead::Denied,
                "a room with binding {binding:?} was granted a memory read"
            );
            assert!(!read.permits_any());
            // Even if a refusal ever did reach a render, its scope must admit
            // nothing rather than widening to Unbound.
            let scope = read.retrieval_scope();
            assert!(
                scope.is_bound(),
                "a refusal produced an UNBOUND scope, which reads everything"
            );
        }
    }

    /// Owner parity for the memory axis, asserted over `InvocationSurface::ALL`
    /// rather than over a chosen few: every surface that reads agent memory
    /// today must still read it UNRESTRICTED, whatever binding is supplied.
    /// The meeting dimension must not narrow anything it was not built to
    /// narrow — including the public ambassador, which keeps its memory
    /// deliberately.
    #[test]
    fn no_owner_surface_is_narrowed_by_the_meeting_axis() {
        use crate::magician_v2::agents::InvocationSurface;

        for surface in InvocationSurface::ALL {
            if !surface_may_read_agent_memory(surface) {
                continue;
            }
            for binding in [None, Some("meeting-weekly-sync-2026-08-18")] {
                assert_eq!(
                    agent_memory_read_for_call(surface, binding),
                    AgentMemoryRead::Unrestricted,
                    "{} was narrowed by the meeting axis; this must not alter \
                     any surface except a room",
                    surface.as_str()
                );
            }
            assert_eq!(
                agent_memory_read_for_call(surface, None).retrieval_scope(),
                crate::magician_v2::agents::retrieval_scope::RetrievalScope::Unbound,
                "{} started rendering under a containment it never had",
                surface.as_str()
            );
        }
    }

    /// Why this is containment and not a provenance filter: a trust filter would
    /// be inert here. Consolidated tier entries carry no guaranteed
    /// `source_type`, and the unrecognised case resolves to `Inferred` — so
    /// room-derived content would read as ordinary inference and pass straight
    /// through a trust gate.
    #[test]
    fn a_trust_filter_would_not_have_caught_room_derived_memory() {
        use crate::magician_v2::agents::memory_provenance::MemoryTrust;

        assert_eq!(
            MemoryTrust::from_source_type("insight"),
            MemoryTrust::Inferred
        );
        assert_eq!(MemoryTrust::from_source_type(""), MemoryTrust::Inferred);
        assert_ne!(
            MemoryTrust::from_source_type("inferred_pattern"),
            MemoryTrust::Untrusted,
            "consolidated entries do not carry untrusted provenance, so filtering \
             on trust alone cannot contain a room"
        );
    }

    #[test]
    fn only_the_room_surface_is_untrusted_for_per_turn_meeting_context() {
        use crate::magician_v2::agents::SurfaceAudience;

        assert_eq!(
            voice_invocation_surface(Some(MEETING_ROOM_SOURCE_SURFACE)).audience(),
            SurfaceAudience::Untrusted
        );
        for owner_source in [None, Some(""), Some("web"), Some("ios"), Some("unknown")] {
            assert_eq!(
                voice_invocation_surface(owner_source).audience(),
                SurfaceAudience::Owner,
                "voice source {owner_source:?} must not be treated as a room"
            );
        }
    }

    #[test]
    fn realtime_context_reports_useful_deadline_result_as_partial_not_ready() {
        use crate::magician_v2::context_retrieval::ContextStageState;

        assert_eq!(
            classify_realtime_turn_context_status(
                true,
                false,
                true,
                [
                    ContextStageState::Completed,
                    ContextStageState::TimedOut,
                    ContextStageState::Empty,
                ],
            ),
            RealtimeTurnContextStatus::Partial
        );
        assert_eq!(
            classify_realtime_turn_context_status(
                true,
                false,
                false,
                [
                    ContextStageState::Completed,
                    ContextStageState::Empty,
                    ContextStageState::Completed,
                ],
            ),
            RealtimeTurnContextStatus::Ready
        );
    }

    #[test]
    fn deferred_tool_search_cannot_widen_a_paired_provider_response() {
        let search = LLMToolCall {
            id: "search".to_string(),
            name: "tool_search".to_string(),
            arguments: json!({"query": "select:browser__open"}),
        };
        let browser = LLMToolCall {
            id: "browser".to_string(),
            name: "browser__open".to_string(),
            arguments: json!({"url": "https://example.test"}),
        };

        assert!(tool_search_is_solo_provider_call(std::slice::from_ref(
            &search
        )));
        assert!(!tool_search_is_solo_provider_call(&[
            search.clone(),
            browser
        ]));
        assert!(!tool_search_is_solo_provider_call(&[
            search.clone(),
            search
        ]));
    }

    fn governed_chat_test_policy(
        processing: crate::magician_v2::apps::models::AppModelProcessing,
    ) -> crate::magician_v2::apps::records::AppDataHandlingPolicy {
        crate::magician_v2::apps::records::AppDataHandlingPolicy {
            classification_floor: crate::magician_v2::apps::models::AppDataClassification::Personal,
            model_processing: processing,
            personal_agent_access:
                crate::magician_v2::apps::records::AppPersonalAgentAccess::ApprovedProjection,
            memory_promotion:
                crate::magician_v2::apps::records::AppMemoryPromotion::CandidateAllowed,
            external_egress: crate::magician_v2::apps::records::AppExternalEgress::Denied,
            approved_destinations: Vec::new(),
        }
    }

    #[test]
    fn guarded_app_consumer_admission_requires_direct_exact_provider_class() {
        use crate::magician_v2::apps::{
            models::{AppModelProcessing, AppReference},
            records::AppDisclosureProviderClass,
        };

        let execution_ref =
            || Some(AppReference::parse("execution:session-1").expect("valid execution ref"));
        let local_only = governed_chat_test_policy(AppModelProcessing::LocalOnly);
        assert!(app_result_policy_permits_consumer(
            true,
            AppDisclosureProviderClass::LocalModel,
            false,
            execution_ref(),
            &local_only,
        ));
        assert!(!app_result_policy_permits_consumer(
            true,
            AppDisclosureProviderClass::LocalModel,
            false,
            None,
            &local_only,
        ));
        assert!(!app_result_policy_permits_consumer(
            true,
            AppDisclosureProviderClass::RemoteModel,
            true,
            execution_ref(),
            &local_only,
        ));

        let remote = governed_chat_test_policy(AppModelProcessing::RemoteAllowed);
        assert!(!app_result_policy_permits_consumer(
            true,
            AppDisclosureProviderClass::RemoteModel,
            false,
            execution_ref(),
            &remote,
        ));
        assert!(app_result_policy_permits_consumer(
            true,
            AppDisclosureProviderClass::RemoteModel,
            true,
            execution_ref(),
            &remote,
        ));
        assert!(!app_result_policy_permits_consumer(
            false,
            AppDisclosureProviderClass::LocalModel,
            false,
            execution_ref(),
            &remote,
        ));

        let mut denied = remote;
        denied.personal_agent_access =
            crate::magician_v2::apps::records::AppPersonalAgentAccess::Denied;
        assert!(!app_result_policy_permits_consumer(
            true,
            AppDisclosureProviderClass::LocalModel,
            false,
            execution_ref(),
            &denied,
        ));
    }

    #[test]
    fn governed_app_effects_fail_closed_after_multiple_source_results() {
        use crate::magician_v2::apps::models::{
            AppModelProcessing, AppProjectionHandle, AppReference,
        };

        let query = |id: &str| LLMToolCall {
            id: id.to_owned(),
            name: "app_data_query".to_owned(),
            arguments: json!({}),
        };
        let handle = |value: &str| AppProjectionHandle {
            handle_ref: AppReference::parse(value).expect("valid projection ref"),
            expires_at: Utc::now() + chrono::Duration::minutes(1),
        };
        let compose = |source: &str| LLMToolCall {
            id: format!("compose-{source}"),
            name: "app_data_compose".to_owned(),
            arguments: json!({"source_projection_handle": source}),
        };

        let mut state = GovernedAppChatState::default();
        let first = handle("projection:first");
        state.join_guard(
            &query("query-1"),
            governed_chat_test_policy(AppModelProcessing::LocalOnly),
            Some(&first),
            &json!({"status": "completed"}),
        );
        assert!(state
            .effectful_call_denial(&compose("projection:first"))
            .is_none());

        let second = handle("projection:second");
        state.join_guard(
            &query("query-2"),
            governed_chat_test_policy(AppModelProcessing::LocalOnly),
            Some(&second),
            &json!({"status": "completed"}),
        );
        let denial = state
            .effectful_call_denial(&compose("projection:first"))
            .expect("multi-source write must fail closed");
        assert_eq!(
            denial.get("error_code").and_then(Value::as_str),
            Some("AppDerivedLineageUnsupported")
        );
    }

    #[test]
    fn governed_app_effects_require_representable_source_and_memory_policy() {
        use crate::magician_v2::apps::models::AppModelProcessing;

        let missing_source = LLMToolCall {
            id: "compose".to_owned(),
            name: "app_data_compose".to_owned(),
            arguments: json!({}),
        };
        assert!(GovernedAppChatState::default()
            .effectful_call_denial(&missing_source)
            .is_some());

        let mut state = GovernedAppChatState::default();
        let mut policy = governed_chat_test_policy(AppModelProcessing::LocalOnly);
        policy.memory_promotion = crate::magician_v2::apps::records::AppMemoryPromotion::Denied;
        state.policy = Some(policy);
        let memory = LLMToolCall {
            id: "memory".to_owned(),
            name: "app_memory_propose".to_owned(),
            arguments: json!({"source_projection_handle": "projection:first"}),
        };
        assert!(state.effectful_call_denial(&memory).is_some());
    }

    #[test]
