    #[test]
    fn governed_effect_control_receipt_omits_result_and_claim_bytes() {
        let composition = governed_effect_control_outcome(
            "app_data_compose",
            &json!({
                "status": "launched",
                "launch": {
                    "run_handle": {
                        "protocol_version": "1",
                        "run_ref": "run:app-action:receipt",
                        "installation_id": "destination",
                        "action_id": "create"
                    },
                    "task_id": "task_app_receipt",
                    "execution_id": "execution-1",
                    "result": {"output": {"secret": "never-retain"}}
                },
                "result_withheld_by_policy": false
            }),
        );
        let encoded = composition.to_string();
        assert!(encoded.contains("run:app-action:receipt"));
        assert!(!encoded.contains("never-retain"));
        assert!(!encoded.contains("\"result\""));

        let memory = governed_effect_control_outcome(
            "app_memory_propose",
            &json!({
                "candidate_id": "memory-candidate:1",
                "candidate_revision": 1,
                "status": "proposed",
                "publication_outcome": "recovered",
                "effect_committed": true,
                "derived_claim_or_summary": "private derived claim",
                "source_refs": [{"secret": "source bytes"}]
            }),
        );
        let encoded = memory.to_string();
        assert!(encoded.contains("memory-candidate:1"));
        assert!(encoded.contains("recovered"));
        assert!(encoded.contains("effect_committed"));
        assert!(!encoded.contains("private derived claim"));
        assert!(!encoded.contains("source bytes"));

        let direct = governed_effect_control_outcome(
            "app_action_invoke",
            &json!({
                "status": "launched",
                "run_handle": {
                    "protocol_version": "1",
                    "run_ref": "run:app-action:direct",
                    "installation_id": "destination",
                    "action_id": "create"
                },
                "result": {"output": {"secret": "never-retain-direct"}},
                "result_withheld_by_policy": false,
                "retryable": false,
                "effect_uncertain": false
            }),
        );
        let encoded = direct.to_string();
        assert!(encoded.contains("run:app-action:direct"));
        assert!(!encoded.contains("never-retain-direct"));
        assert!(!encoded.contains("\"result\""));
    }

    #[test]
    fn pre_provider_governed_cancellation_has_no_settlement_receipt() {
        let cancelled = json!({
            "status": "cancelled",
            "error_code": "CompiledDispatchCancelled",
            "reason": "compiled chat dispatch was cancelled before provider execution",
        });
        assert_eq!(
            governed_effect_dispatch_phase("app_data_compose", false),
            GovernedEffectDispatchPhase::NotSettled
        );
        assert!(governed_effect_control_receipt("app_data_compose", &cancelled, false).is_none());

        let launched = json!({"status": "launched"});
        assert_eq!(
            governed_effect_dispatch_phase("app_data_compose", true),
            GovernedEffectDispatchPhase::ProviderReturnedTypedOutcome
        );
        assert!(governed_effect_control_receipt("app_data_compose", &launched, true).is_some());
        assert_eq!(
            governed_effect_dispatch_phase("app_action_invoke", true),
            GovernedEffectDispatchPhase::ProviderReturnedTypedOutcome
        );
        assert_eq!(
            governed_effect_dispatch_phase("app_discover", true),
            GovernedEffectDispatchPhase::NotSettled
        );
    }

