    #[test]
    fn governed_no_effect_outcomes_preserve_same_source_retry() {
        use crate::magician_v2::apps::models::{
            AppModelProcessing, AppProjectionHandle, AppReference,
        };

        let source = "projection:first";
        let query = LLMToolCall {
            id: "query".to_owned(),
            name: "app_data_query".to_owned(),
            arguments: json!({}),
        };
        let compose = LLMToolCall {
            id: "compose".to_owned(),
            name: "app_data_compose".to_owned(),
            arguments: json!({"source_projection_handle": source}),
        };
        for result in [
            json!({"status": "waiting"}),
            json!({"status": "source_terminal", "source_status": "failed"}),
            json!({
                "status": "unavailable",
                "retry_class": "permanent",
                "effect_uncertain": false
            }),
            json!({
                "status": "unavailable",
                "retry_class": "cancelled",
                "effect_uncertain": false
            }),
        ] {
            let mut state = GovernedAppChatState::default();
            state.join_guard(
                &query,
                governed_chat_test_policy(AppModelProcessing::LocalOnly),
                Some(&AppProjectionHandle {
                    handle_ref: AppReference::parse(source).expect("valid projection ref"),
                    expires_at: Utc::now() + chrono::Duration::minutes(1),
                }),
                &json!({"status": "completed"}),
            );
            state.join_guard(
                &compose,
                governed_chat_test_policy(AppModelProcessing::LocalOnly),
                None,
                &result,
            );
            assert!(!governed_app_result_invalidates_v1_lineage(
                "app_data_compose",
                &result,
            ));
            assert!(state.effectful_call_denial(&compose).is_none());
        }
        assert!(governed_app_result_invalidates_v1_lineage(
            "app_action_compose",
            &json!({"status": "launched"}),
        ));
        assert!(governed_app_result_invalidates_v1_lineage(
            "app_action_compose",
            &json!({"status": "unavailable", "effect_uncertain": true}),
        ));
        assert!(!governed_app_result_invalidates_v1_lineage(
            "app_memory_propose",
            &json!({"status": "cancelled", "effect_committed": false}),
        ));
        assert!(governed_app_result_invalidates_v1_lineage(
            "app_memory_propose",
            &json!({
                "status": "proposed",
                "publication_outcome": "published",
                "effect_committed": true
            }),
        ));
        assert!(governed_app_result_invalidates_v1_lineage(
            "app_memory_propose",
            &json!({
                "status": "proposed",
                "publication_outcome": "recovered",
                "effect_committed": true
            }),
        ));
        assert!(governed_app_result_invalidates_v1_lineage(
            "app_data_compose",
            &json!({"status": "error"}),
        ));
    }

