    /// A harness turn's grant is revoked the moment the turn settles, which
    /// cancels every per-call token under it. The tools that spawn a run
    /// outliving the turn must not read that as an abort: a delegated desktop
    /// run was cancelled seconds after its loop started because it did. They
    /// take the turn's own abort token; everything else still stops with the
    /// door.
    #[test]
    fn a_spawning_tool_cascades_on_the_turns_abort_not_on_the_grants_revoke() {
        use tokio_util::sync::CancellationToken;

        let turn_abort = CancellationToken::new();
        // The plane's per-call token as `dispatch` builds it: a grandchild of
        // the turn's, so a revoke reaches it and never reaches the turn.
        let grant_dispatch = turn_abort.child_token();
        let call_cancel = grant_dispatch.child_token();

        let delegate =
            super::bridged_call_cancel_token("delegate_to_agent", &turn_abort, call_cancel.clone());
        let handover =
            super::bridged_call_cancel_token("handover_to_agent", &turn_abort, call_cancel.clone());
        let pipeline = super::bridged_call_cancel_token(
            "orchestrate_pipeline",
            &turn_abort,
            call_cancel.clone(),
        );
        let inline = super::bridged_call_cancel_token("http", &turn_abort, call_cancel.clone());

        // The turn settles: the grant is revoked.
        grant_dispatch.cancel();
        assert!(call_cancel.is_cancelled(), "a revoke reaches the call");
        assert!(
            inline.is_cancelled(),
            "in-flight work still stops with the door"
        );
        for (tool, token) in [
            ("delegate_to_agent", &delegate),
            ("handover_to_agent", &handover),
            ("orchestrate_pipeline", &pipeline),
        ] {
            assert!(
                !token.is_cancelled(),
                "{tool} must survive its turn settling"
            );
        }

        // The user stops the conversation: now they cascade.
        turn_abort.cancel();
        for (tool, token) in [
            ("delegate_to_agent", &delegate),
            ("handover_to_agent", &handover),
            ("orchestrate_pipeline", &pipeline),
        ] {
            assert!(token.is_cancelled(), "{tool} must cascade on a real abort");
        }
    }

