    #[tokio::test]
    async fn compiled_chat_dispatch_exposes_cancellation_task_local() {
        let token = CancellationToken::new();
        token.cancel();
        let visible = compiled_dispatch::EXECUTION_CANCEL_TOKEN
            .scope(Some(token), async {
                compiled_dispatch::EXECUTION_CANCEL_TOKEN
                    .try_with(|current| {
                        current
                            .as_ref()
                            .is_some_and(CancellationToken::is_cancelled)
                    })
                    .unwrap_or(false)
            })
            .await;
        assert!(visible);
    }

