    #[test]
    fn chat_dispatch_trust_policy_uses_pack_action_discriminator() {
        let enforcer = crate::magician_v2::agents::TrustPolicyEnforcer::from_yaml_str(
            r#"
trust_policies:
  - level: local
    allow:
      - tool: "*"
        action: "*"
    deny:
      - tool: report
        action: email
"#,
        )
        .expect("trust policy");
        let policy = ChatTrustDispatchPolicy {
            level: crate::magician_v2::agents::types::TrustLevel("local".to_string()),
            enforcer: Arc::new(enforcer),
            policy_digest: "test-policy-digest".to_string(),
        };
        let denied = LLMToolCall {
            id: "call-report".to_string(),
            name: "report".to_string(),
            arguments: json!({"action": "email"}),
        };
        let allowed = LLMToolCall {
            id: "call-report-preview".to_string(),
            name: "report".to_string(),
            arguments: json!({"action": "preview"}),
        };

        assert_eq!(
            chat_tool_trust_denial(Some(&policy), &denied)
                .and_then(|value| value.get("error_code").cloned()),
            Some(Value::String("ChatToolTrustPolicyDenied".to_string()))
        );
        assert!(chat_tool_trust_denial(Some(&policy), &allowed).is_none());
    }

    #[test]
    fn chat_tool_resolution_runtime_projection_is_shared_and_turn_gated() {
        let trusted = chat_tool_test_agent("local", &[], &[], &[]);
        let untrusted = chat_tool_test_agent("untrusted", &[], &[], &[]);
        let runtime_tools = build_chat_runtime_tools();

        let (ordinary, ordinary_tutor_dropped) = chat_runtime_tool_specs_for_turn(
            &runtime_tools,
            Some(&trusted),
            crate::magician_v2::agents::FeatureMode::None,
        );
        assert!(ordinary_tutor_dropped > 0);
        assert!(ordinary
            .iter()
            .any(|spec| spec.name == "list_tools_for_chat"));
        assert!(!ordinary.iter().any(|spec| spec.name == "start_tutor_run"));

        let (tutor, tutor_dropped) = chat_runtime_tool_specs_for_turn(
            &runtime_tools,
            Some(&trusted),
            crate::magician_v2::agents::FeatureMode::Tutor,
        );
        assert_eq!(tutor_dropped, 0);
        assert!(tutor.iter().any(|spec| spec.name == "start_tutor_run"));

        let (stranger, stranger_dropped) = chat_runtime_tool_specs_for_turn(
            &runtime_tools,
            Some(&untrusted),
            crate::magician_v2::agents::FeatureMode::None,
        );
        assert_eq!(stranger_dropped, 0);
        assert!(stranger.is_empty());
    }

    #[test]
    fn chat_tool_resolution_lower_trust_uses_policy_executor_and_no_untrusted_orchestration() {
        let local = chat_tool_test_agent("local", &["browser"], &[], &[]);
        let reviewed = chat_tool_test_agent("reviewed", &["browser"], &[], &[]);
        let mut untrusted = chat_tool_test_agent("untrusted", &["browser"], &[], &[]);
        untrusted.delegation_targets = vec!["worker".to_string()];

        assert!(!chat_trust_requires_executor_policy_path(&local));
        assert!(chat_trust_requires_executor_policy_path(&reviewed));
        assert!(chat_trust_requires_executor_policy_path(&untrusted));

        let inline_registry = tutor_draw_adapter_test_registry("visual-overlay-v2", "render");
        let mut reviewed_overlay = build_execution_native_catalog(&build_chat_catalog_context(
            &["visual-overlay-v2__render".to_string()],
            &["worker".to_string()],
            Some(inline_registry.as_ref()),
        ));
        assert!(
            retain_chat_native_tools_for_trust(
                &mut reviewed_overlay,
                &reviewed,
                Some(inline_registry.as_ref()),
            ) >= 3
        );
        assert!(!reviewed_overlay
            .iter()
            .any(|tool| tool.name == "visual-overlay-v2__render"));
        assert!(!reviewed_overlay.iter().any(|tool| matches!(
            tool.name.as_str(),
            "spawn_sub_goal" | "delegate_to_agent" | "handover_to_agent"
        )));

        let mut parameter_restricted = local.clone();
        parameter_restricted.denied_tool_params.insert(
            " shell ".to_string(),
            HashMap::from([("command".to_string(), vec!["rm ".to_string()])]),
        );
        assert!(!chat_trust_requires_executor_policy_path(
            &parameter_restricted
        ));
        let params = HashMap::from([(
            "command".to_string(),
            Value::String("  RM -rf /tmp/example".to_string()),
        )]);
        assert!(
            crate::magician_v2::agents::types::denied_tool_parameter_match(
                &parameter_restricted.denied_tool_params,
                "shell",
                &params,
            )
            .is_some()
        );
        let denied_call = LLMToolCall {
            id: "call-1".to_string(),
            name: "shell".to_string(),
            arguments: json!({ "command": "  RM -rf /tmp/example" }),
        };
        assert_eq!(
            chat_tool_parameter_denial(
                Some(&parameter_restricted.denied_tool_params),
                &denied_call,
            )
            .and_then(|value| value.get("error_code").cloned()),
            Some(Value::String("ChatToolParameterDenied".to_string()))
        );

        let tools = effective_tools_from_definition(&untrusted);
        let context = build_chat_catalog_context(&tools, &untrusted.delegation_targets, None);
        let mut catalog = build_execution_native_catalog(&context);
        let removed = retain_chat_native_tools_for_trust(&mut catalog, &untrusted, None);
        let names: HashSet<&str> = catalog.iter().map(|tool| tool.name.as_str()).collect();

        assert!(removed >= 3);
        assert!(!names.contains("spawn_sub_goal"));
        assert!(!names.contains("delegate_to_agent"));
        assert!(!names.contains("handover_to_agent"));
        assert!(!names.contains("orchestrate_pipeline"));
        assert!(names.contains("time_math"));
    }

