    #[test]
    fn chat_tool_resolution_search_memory_uses_registered_schema() {
        let definition = chat_tool_test_agent("local", &["browser"], &[], &[]);
        let search_pack =
            crate::magician_v2::execution::compiled_providers::embedded_compiled_pack_defs()
                .into_iter()
                .find(|pack| pack.name == "search_memory")
                .expect("search_memory must remain an embedded compiled pack");
        let registry = CapabilityRegistry::new();
        registry.set_pack_definition("search_memory", search_pack);
        let tools = effective_tools_from_definition(&definition);
        let context = build_chat_catalog_context(&tools, &[], Some(&registry));
        let catalog = build_execution_native_catalog(&context);
        let search = catalog
            .iter()
            .find(|tool| tool.name == "search_memory")
            .expect("search_memory should reach the provider catalogue");

        assert!(search.parameters["properties"].get("query").is_some());
        assert!(search.parameters["required"]
            .as_array()
            .is_some_and(|required| required.iter().any(|value| value == "query")));
    }

