    #[test]
    fn terminal_usage_public_budget_keeps_unknown_cost_explicit_across_restore() {
        let manager = PublicChatAdmissionManager::new(test_public_chat_policy(100));
        manager.commit_paid_usage(None);
        assert_eq!(manager.snapshot().paid_cost_usd, Some(0.0));
        manager.commit_paid_usage(Some(&ChatTurnUsage {
            calls: 1,
            total_tokens: 123,
            cost_usd: None,
            ..Default::default()
        }));
        assert_eq!(manager.snapshot().paid_cost_usd, None);
        assert_eq!(manager.try_reserve_paid_call(), Some("unreported_cost"));
        let persisted = serde_json::to_string(&manager.ledger_snapshot()).unwrap();
        let restored = PublicChatAdmissionManager::new(test_public_chat_policy(100));
        restored.restore_ledger(serde_json::from_str(&persisted).unwrap());
        assert_eq!(restored.try_reserve_paid_call(), Some("unreported_cost"));
        assert_eq!(restored.snapshot().paid_cost_usd, None);
        assert_eq!(restored.snapshot().paid_tokens, 123);
    }

    #[test]
    fn public_chat_paid_admission_rolls_back_uncommitted_reserved_call() {
        let manager = Arc::new(PublicChatAdmissionManager::new(test_public_chat_policy(1)));
        match manager.admit(None, false) {
            PublicChatAdmissionDecision::Run { permit, .. } => drop(permit),
            PublicChatAdmissionDecision::Reject { reason, .. } => {
                panic!("expected paid admission, rejected with {reason}");
            },
        }

        let snapshot = manager.snapshot();

        assert_eq!(snapshot.paid_calls, 0);
        assert_eq!(snapshot.fallback_reason, None);
    }

    #[test]
    fn public_chat_paid_admission_switches_to_fallback_after_daily_call_limit() {
        let manager = Arc::new(PublicChatAdmissionManager::new(test_public_chat_policy(1)));
        let mut first_permit = match manager.admit(None, false) {
            PublicChatAdmissionDecision::Run { permit, route, .. } => {
                assert_eq!(route, PublicChatAdmissionRoute::Paid);
                permit
            },
            PublicChatAdmissionDecision::Reject { reason, .. } => {
                panic!("expected paid admission, rejected with {reason}");
            },
        };
        first_permit.commit_usage(None);

        match manager.admit(None, false) {
            PublicChatAdmissionDecision::Run { route, permit, .. } => {
                assert_eq!(route, PublicChatAdmissionRoute::Fallback);
                drop(permit);
            },
            PublicChatAdmissionDecision::Reject { reason, .. } => {
                panic!("expected fallback admission, rejected with {reason}");
            },
        }

        let snapshot = manager.snapshot();

        assert_eq!(snapshot.paid_calls, 1);
        assert_eq!(snapshot.fallback_reason.as_deref(), Some("daily_calls"));
    }

