    fn duckdb_style_pack() -> crate::magician_v2::execution::capability::CapabilityPackDefinition {
        serde_yaml::from_str(
            r#"
name: browser
description: Drive a browser.
parameters:
  - name: command
    required: true
    param_type: string
native_action_schemas:
  open:
    description: Open a URL.
    parameters: [url]
    required: [url]
    parameter_overrides:
      url: { type: string }
  snapshot:
    description: Snapshot the page.
    parameters: []
    required: []
implementation:
  type: primitive
"#,
        )
        .expect("pack parses")
    }

    /// The chat surface advertises whole packs, but a leaf can still reach the
    /// pack dispatcher (a stale loaded set, a model inventing a name). The
    /// sub-run must then be scoped to the pack the leaf belongs to — a pack
    /// named `browser__open` exists nowhere, and a run scoped to it gets only
    /// `task_state` and reports "no browser tools".
    #[test]
    fn a_leaf_call_dispatches_as_its_pack() {
        let registry = CapabilityRegistry::new();
        registry.set_pack_definition("browser", duckdb_style_pack());

        let (pack, action) = chat_pack_dispatch_target(Some(&registry), "browser__open");
        assert_eq!(pack, "browser");
        assert_eq!(action.as_deref(), Some("open"));

        let (pack, action) = chat_pack_dispatch_target(Some(&registry), "browser");
        assert_eq!((pack.as_str(), action), ("browser", None));

        // An action the pack never declared is not a leaf of it.
        let (pack, action) = chat_pack_dispatch_target(Some(&registry), "browser__teleport");
        assert_eq!((pack.as_str(), action), ("browser__teleport", None));
    }

    /// A leaf call's arguments are one step, not a goal: the sub-run is told
    /// the user's request and which action the model chose to start with, so
    /// it can finish the job instead of stopping after one `open`.
    #[test]
    fn a_leaf_call_goal_carries_the_request_and_the_chosen_step() {
        let goal = chat_pack_leaf_goal_text(
            "browser",
            "open",
            &serde_json::json!({"url": "https://www.makemytrip.com/flights/"}),
            Some("Find the cheapest BLR to DEL flight next Friday on makemytrip.com"),
            None,
        );
        assert!(
            goal.starts_with("Find the cheapest BLR to DEL flight"),
            "{goal}"
        );
        assert!(
            goal.contains("`open`") && goal.contains("`browser`"),
            "{goal}"
        );
        assert!(
            goal.contains("https://www.makemytrip.com/flights/"),
            "{goal}"
        );

        let bare =
            chat_pack_leaf_goal_text("browser", "snapshot", &serde_json::json!({}), None, None);
        assert!(
            bare.contains("`snapshot`") && !bare.contains("{}"),
            "{bare}"
        );
    }

    fn artifact(
        name: &str,
        content_type: &str,
        text: &str,
    ) -> crate::magician_v2::execution::agentic::Artifact {
        crate::magician_v2::execution::agentic::Artifact {
            name: name.to_string(),
            content_type: content_type.to_string(),
            data: text.as_bytes().to_vec(),
            artifact_type: None,
            render_hints: None,
            materialized_path: None,
        }
    }

    /// The mouth reads the sub-run's answer from the tool result. It used to
    /// get file names only, and reported "MakeMyTrip blocked the results"
    /// while the deliverable said "IndiGo 6E-6406, 22:00, ₹10,378".
    #[test]
    fn a_chat_pack_result_carries_the_deliverable_text() {
        let artifacts = vec![
            artifact(
                "makemytrip_blr_del.md",
                "text/markdown",
                "# Results\nlots of rows",
            ),
            artifact(
                "task_deliverable.md",
                "text/markdown",
                "Cheapest: IndiGo 6E-6406, 22:00, ₹10,378\nURL: https://example.invalid",
            ),
        ];
        let text = chat_pack_deliverable_text(&artifacts).expect("deliverable");
        assert!(text.starts_with("Cheapest: IndiGo 6E-6406"), "{text}");

        // No typed deliverable: the first text artifact stands in.
        let text = chat_pack_deliverable_text(&artifacts[..1]).expect("text artifact");
        assert!(text.starts_with("# Results"), "{text}");

        // Binary-only outputs carry no text.
        assert!(
            chat_pack_deliverable_text(&[artifact("shot.png", "image/png", "\u{89}PNG")]).is_none()
        );

        // Bounded at a char boundary.
        let big = "é".repeat(CHAT_PACK_DELIVERABLE_MAX_BYTES);
        let text =
            chat_pack_deliverable_text(&[artifact("task_deliverable.md", "text/markdown", &big)])
                .expect("bounded");
        assert!(
            text.ends_with('…') && text.len() <= CHAT_PACK_DELIVERABLE_MAX_BYTES + 4,
            "{}",
            text.len()
        );
    }

