    #[test]
    fn personal_tutor_instructions_require_typed_feature_mode() {
        // The service folds this decision onto the chat lane seam: the lane
        // owning the mode declares whether its turns carry the personal-tutor
        // prompt block, and unregistered modes inject nothing.
        let injects = |feature_mode: crate::magician_v2::agents::FeatureMode| {
            registered_lanes()
                .iter()
                .find(|lane| lane.feature_mode() == feature_mode)
                .is_some_and(|lane| lane.injects_personal_tutor_instructions())
        };
        assert!(injects(crate::magician_v2::agents::FeatureMode::Tutor));
        assert!(injects(crate::magician_v2::agents::FeatureMode::AppCopilot));
        assert!(!injects(crate::magician_v2::agents::FeatureMode::None));
        assert!(!injects(
            crate::magician_v2::agents::FeatureMode::Brainstorm
        ));
        assert!(!injects(crate::magician_v2::agents::FeatureMode::Vibedev));
    }

