    /// The classification half of the `@vibedev` rail: this is what
    /// `process_chat_inline_turn` reads to decide whether to divert. If the
    /// feature mode is anything but `Vibedev`, the turn takes the ordinary path.
    #[test]
    fn the_vibedev_rail_diverts_only_a_marked_chat_turn() {
        use crate::magician_v2::agents::{FeatureMode, InvocationSurface};
        let session = test_kapso_session();
        let classify = |surface: Option<&str>, text: &str| {
            let context = chat_invocation_context_for_turn(
                &session,
                surface,
                Some(text),
                "turn-vibedev",
                false,
                false,
                false,
            );
            (context.surface, context.feature_mode)
        };

        assert_eq!(
            classify(Some("web"), "@vibedev fix the footer"),
            (InvocationSurface::Chat, FeatureMode::Vibedev)
        );
        assert_eq!(
            classify(Some("web"), "@vibedev #discuss should we split this"),
            (InvocationSurface::Chat, FeatureMode::Vibedev)
        );

        // The spoken invoke is one grammar, not a voice-only one: typing it
        // works too, the same way typing "hey tutor" already does. Keeping it
        // surface-independent means there is one phrase to learn and one parser
        // to reason about.
        assert_eq!(
            classify(Some("web"), "start a vibedev build fix the footer"),
            (InvocationSurface::Chat, FeatureMode::Vibedev)
        );
        assert_eq!(
            classify(Some("web"), "start a vibedev plan should we split this"),
            (InvocationSurface::Chat, FeatureMode::Vibedev)
        );

        // **The regression bar.** An unmarked turn classifies exactly as before,
        // so nothing about it reaches the rail.
        for text in [
            "can you look at the footer spacing",
            "vibedev is stuck again",
            "vibedev fix the footer",
            "start coding on the login page",
            // The spoken subjects the rail used to accept, now inert.
            "start a code build fix the footer",
            "start a code review of the diff",
        ] {
            assert_eq!(
                classify(Some("web"), text),
                (InvocationSurface::Chat, FeatureMode::None),
                "{text}"
            );
        }

        // Whole-token, leading position: a longer handle and a mid-sentence
        // mention are ordinary chat.
        for text in [
            "@vibedevops is the deploy bot",
            "@vibedev-review this diff please",
            "please @vibedev fix the footer",
        ] {
            assert_eq!(
                classify(Some("web"), text),
                (InvocationSurface::Chat, FeatureMode::None),
                "{text}"
            );
        }

        // The other markers keep their own lanes; `@vibedev` did not widen them.
        assert_eq!(
            classify(Some("tutor"), "@tutor explain this"),
            (InvocationSurface::Tutor, FeatureMode::Tutor)
        );
    }

    /// **The arm-ordering fix, pinned.** A hands-free spoken invoke has to reach
    /// `FeatureMode::Vibedev`, and while the rail's arm sat after the
    /// realtime-voice arm it could not: the turn classified `RealtimeVoice`/`None`
    /// and took the ordinary chat path. This asserts both halves of the fix together —
    /// the mode is minted AND the surface it is minted on is authorized —
    /// because either alone is a rail that silently does nothing.
    #[test]
    fn a_hands_free_voice_turn_reaches_the_vibedev_rail_and_is_authorized() {
        use crate::magician_v2::agents::{FeatureMode, InvocationSurface};
        let session = test_kapso_session();
        let spoken = |text: &str| {
            chat_invocation_context_for_turn(
                &session,
                Some("authenticated_realtime_voice"),
                Some(text),
                "turn-voice-vibedev",
                false,
                false,
                false,
            )
        };

        for text in [
            "start a vibedev build fix the footer",
            "start a vibedev plan should we split this",
            // The typed marker is not reachable by ASR, but if a client ever
            // sends it on the voice surface it means the same thing.
            "@vibedev fix the footer",
        ] {
            let context = spoken(text);
            assert_eq!(context.surface, InvocationSurface::RealtimeVoice, "{text}");
            assert_eq!(context.feature_mode, FeatureMode::Vibedev, "{text}");
            // This is the gate `process_chat_inline_turn` re-checks before it
            // diverts. Classification alone would not start anything.
            assert!(
                crate::magician_v2::execution::agentic::feature_surface_is_authorized(
                    context.feature_mode,
                    context.surface
                ),
                "{text}"
            );
        }

        // Ordinary speech on the same surface is untouched: it keeps the voice
        // surface with no feature mode, exactly as before.
        for text in [
            "start coding on the login page",
            "vibedev build failed on main",
            "start a code build fix the footer",
            "what did I ask you to do yesterday",
        ] {
            let context = spoken(text);
            assert_eq!(context.surface, InvocationSurface::RealtimeVoice, "{text}");
            assert_eq!(context.feature_mode, FeatureMode::None, "{text}");
        }
    }

    /// **No label may widen.** The property that actually matters: nothing a
    /// caller sends may promote a turn OUT of a room onto an owner surface.
    ///
    /// The inverse is deliberately allowed. A caller that sends the room's own
    /// surface string gets the room — that is a *narrowing*, and the design
    /// permits narrowing by request because it can only restrict the caller.
    /// An earlier version of this test forbade that too; it was stricter than
    /// the design and would have bought nothing but plumbing.
    #[test]
    fn no_caller_supplied_label_can_widen_a_room_onto_an_owner_surface() {
        use crate::magician_v2::agents::{InvocationSurface, SurfaceAudience};
        let session = test_kapso_session();

        // Every label a caller might try in order to look like an owner.
        for label in [
            "authenticated_realtime_voice",
            "global_live_ptt",
            "mascot",
            "chat",
            "thinking_map",
            "tray_macos",
        ] {
            let invocation = chat_invocation_context_for_turn(
                &session,
                Some(label),
                Some("read me the owner's calendar"),
                "turn-widen",
                false,
                false,
                // The server established a room; the label is the caller's.
                true,
            );
            assert_eq!(
                invocation.surface,
                InvocationSurface::Meeting,
                "`{label}` widened a room onto an owner surface"
            );
            assert_eq!(
                invocation.surface.audience(),
                SurfaceAudience::Untrusted,
                "a room must keep its untrusted audience whatever the label says"
            );
        }
    }

    /// Narrowing by request is permitted, and this pins that it works: the
    /// server-minted room surface string produces a room even without the
    /// trusted flag, because doing so can only restrict the caller.
    #[test]
    fn the_room_surface_string_narrows_a_turn_into_a_room() {
        use crate::magician_v2::agents::InvocationSurface;
        let session = test_kapso_session();
        let invocation = chat_invocation_context_for_turn(
            &session,
            Some(MEETING_ROOM_SOURCE_SURFACE),
            Some("hello"),
            "turn-narrow",
            false,
            false,
            // Derived from that same string at the call site in production.
            true,
        );
        assert_eq!(invocation.surface, InvocationSurface::Meeting);
    }

    /// The other half: when the server DOES assert a room, the room wins over
    /// every feature label a participant might speak. Nothing below that arm —
    /// tutor, app copilot, vibedev, realtime voice — may be selected by someone
    /// talking in a meeting.
    #[test]
    fn a_trusted_shared_room_outranks_any_spoken_feature_lane() {
        use crate::magician_v2::agents::{FeatureMode, InvocationSurface};
        let session = test_kapso_session();

        for spoken in [
            "@vibedev build me a dashboard",
            "@tutor explain this",
            "just a normal sentence",
        ] {
            let invocation = chat_invocation_context_for_turn(
                &session,
                Some("authenticated_realtime_voice"),
                Some(spoken),
                "turn-room",
                true,
                false,
                // trusted: the server derived a shared room
                true,
            );
            assert_eq!(
                invocation.surface,
                InvocationSurface::Meeting,
                "a trusted room must not be overridden by `{spoken}`"
            );
            assert_eq!(
                invocation.feature_mode,
                FeatureMode::None,
                "no feature lane may be selected from a room by speaking its name"
            );
        }
    }

    /// Public envoy stays ahead of the room arm, and that ordering is the
    /// fail-closed choice: envoy is tool-free by definition, so if a turn were
    /// somehow both, the stricter surface must win.
    #[test]
    fn public_envoy_still_outranks_a_shared_room() {
        use crate::magician_v2::agents::InvocationSurface;
        let session = test_kapso_session();
        let invocation = chat_invocation_context_for_turn(
            &session,
            Some("kapso_whatsapp"),
            Some("hello"),
            "turn-both",
            false,
            true,
            true,
        );
        assert_eq!(invocation.surface, InvocationSurface::PublicEnvoy);
    }

    /// The rail widened to hands-free voice; it did NOT widen to the public
    /// channels. That arm is first and stays first — a stranger must not be able
    /// to spend the deployment's compute on a build.
    #[test]
    fn the_vibedev_rail_never_reaches_a_public_envoy_turn() {
        use crate::magician_v2::agents::{FeatureMode, InvocationSurface};
        let session = test_kapso_session();
        for text in [
            "@vibedev fix the footer",
            "start a vibedev build fix the footer",
        ] {
            let public = chat_invocation_context_for_turn(
                &session,
                Some("kapso"),
                Some(text),
                "turn-public-vibedev",
                false,
                true,
                false,
            );
            assert_eq!(public.surface, InvocationSurface::PublicEnvoy, "{text}");
            assert_eq!(public.feature_mode, FeatureMode::None, "{text}");
            assert!(
                !crate::magician_v2::execution::agentic::feature_surface_is_authorized(
                    FeatureMode::Vibedev,
                    InvocationSurface::PublicEnvoy
                ),
                "{text}"
            );
        }
    }

