    #[test]
    fn app_copilot_capture_attestation_is_short_lived() {
        let now = 1_000_000_i64;
        assert!(app_copilot_capture_timestamp_is_fresh(now, now));
        assert!(app_copilot_capture_timestamp_is_fresh(
            now - APP_COPILOT_CAPTURE_MAX_AGE_MS,
            now
        ));
        assert!(!app_copilot_capture_timestamp_is_fresh(
            now - APP_COPILOT_CAPTURE_MAX_AGE_MS - 1,
            now
        ));
        assert!(!app_copilot_capture_timestamp_is_fresh(now + 1, now));
    }

