    #[test]
    fn chat_structural_controls_match_canonical_approval_rules_before_dispatch() {
        for action in [
            "spawn_sub_goal",
            "delegate_to_agent",
            "handover_to_agent",
            "orchestrate_pipeline",
        ] {
            let rules = vec![crate::magician_v2::agents::types::ApprovalRule {
                tool: "orchestrator".to_string(),
                action: crate::magician_v2::agents::types::ActionPattern::Single(
                    action.to_string(),
                ),
                when: None,
                ttl_secs: None,
            }];
            assert!(chat_structural_approval_required(
                action,
                &serde_json::json!({}),
                &rules
            ));
        }
        let unrelated = vec![crate::magician_v2::agents::types::ApprovalRule {
            tool: "orchestrator".to_string(),
            action: crate::magician_v2::agents::types::ActionPattern::Single(
                "delegate_to_agent".to_string(),
            ),
            when: None,
            ttl_secs: None,
        }];
        assert!(!chat_structural_approval_required(
            "spawn_sub_goal",
            &serde_json::json!({}),
            &unrelated
        ));
    }

