    #[test]
    fn chat_sub_goals_inherit_the_authenticated_active_surface_and_feature_provenance() {
        use crate::magician_v2::agents::{
            AgentInvocationContext, FeatureMode, InvocationSourceKind, InvocationSurface,
        };

        let session = test_kapso_session();
        let definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(
            "agent_id: envoy\nname: Envoy\npersona: Test\ntrust_level: local\n",
        )
        .expect("definition");
        let cases = [
            (
                InvocationSurface::Chat,
                FeatureMode::None,
                InvocationSourceKind::Direct,
            ),
            (
                InvocationSurface::RealtimeVoice,
                FeatureMode::None,
                InvocationSourceKind::Direct,
            ),
            (
                InvocationSurface::Tutor,
                FeatureMode::Tutor,
                InvocationSourceKind::ProductFeature,
            ),
            (
                InvocationSurface::AppCopilot,
                FeatureMode::AppCopilot,
                InvocationSourceKind::ProductFeature,
            ),
        ];

        for (surface, feature_mode, source_kind) in cases {
            let snapshot =
                crate::magician_v2::execution::agentic::resolve_effective_tool_policy_snapshot(
                    &definition,
                    AgentInvocationContext {
                        principal: session.principal.clone(),
                        workspace: session.workspace.clone(),
                        source_agent_id: None,
                        target_agent_id: session.agent_id.clone(),
                        surface,
                        feature_mode,
                        source_kind,
                        chat_session_id: Some("prior-session".to_string()),
                        chat_turn_id: Some("prior-turn".to_string()),
                    },
                    Default::default(),
                )
                .expect("snapshot");
            let child = chat_sub_goal_invocation_context(
                &session,
                &session.agent_id,
                Some("current-turn"),
                Some(snapshot.as_ref()),
            )
            .expect("authorized sub-goal context");
            assert_eq!(child.surface, surface);
            assert_eq!(child.feature_mode, feature_mode);
            assert_eq!(child.source_kind, source_kind);
            assert_eq!(child.chat_session_id.as_deref(), Some(session.id.as_str()));
            assert_eq!(child.chat_turn_id.as_deref(), Some("current-turn"));
        }

        assert!(
            chat_sub_goal_invocation_context(&session, &session.agent_id, Some("turn"), None,)
                .is_err()
        );
    }

    #[test]
    fn delegated_introspection_mints_the_same_typed_delegation_boundary_as_execution() {
        use crate::magician_v2::agents::{
            AgentInvocationContext, FeatureMode, InvocationSourceKind, InvocationSurface,
        };

        let session = test_kapso_session();
        let definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(
            "agent_id: envoy\nname: Envoy\npersona: Test\ntrust_level: \
             local\ndelegation_targets:\n  - worker\n",
        )
        .expect("definition");
        let snapshot =
            crate::magician_v2::execution::agentic::resolve_effective_tool_policy_snapshot(
                &definition,
                AgentInvocationContext {
                    principal: session.principal.clone(),
                    workspace: session.workspace.clone(),
                    source_agent_id: None,
                    target_agent_id: session.agent_id.clone(),
                    surface: InvocationSurface::Tutor,
                    feature_mode: FeatureMode::Tutor,
                    source_kind: InvocationSourceKind::ProductFeature,
                    chat_session_id: Some(session.id.clone()),
                    chat_turn_id: Some("turn-source".to_string()),
                },
                crate::magician_v2::execution::agentic::SnapshotResolutionInput {
                    provider_tools: vec![
                        crate::magician_v2::execution::agentic::native_catalog::build_delegate_to_agent_tool(),
                    ],
                    delegation_target_ids: vec!["worker".to_string()],
                    ..Default::default()
                },
            )
            .expect("source snapshot");

        let target = delegated_introspection_invocation_context(
            &session,
            &session.agent_id,
            "worker",
            Some(snapshot.as_ref()),
        )
        .expect("delegated introspection invocation");
        assert_eq!(
            target.source_agent_id.as_deref(),
            Some(session.agent_id.as_str())
        );
        assert_eq!(target.target_agent_id, "worker");
        assert_eq!(target.surface, InvocationSurface::Delegation);
        assert_eq!(target.feature_mode, FeatureMode::None);
        assert_eq!(target.source_kind, InvocationSourceKind::Delegated);
        assert_eq!(target.chat_turn_id.as_deref(), Some("turn-source"));

        assert!(delegated_introspection_invocation_context(
            &session,
            &session.agent_id,
            "not-authorized",
            Some(snapshot.as_ref()),
        )
        .is_err());
    }

