    #[tokio::test]
    async fn dispatch_screen_draw_pack_realtime_client_broadcasts_without_gateway() {
        let llm = Arc::new(MockChatLlmClient::default());
        let (service, _store, session, _tmp) = create_test_service(llm).await;
        let mut receiver = service.event_broadcaster.subscribe();
        let context = ScreenCaptureAttachmentContext {
            server_registered: true,
            mode: "screenshot".to_string(),
            coordinate_space: SCREEN_CAPTURE_COORDINATE_SPACE_CAPTURE.to_string(),
            image_size: Some(crate::magician_v2::chat::models::ScreenCaptureImageSize {
                width: 1179,
                height: 2556,
            }),
            screen_rect: None,
        };
        let args = serde_json::json!({
            "shape_json": {
                "type": "group",
                "coordinate_space": "capture",
                "tutor_step_label": "Tap Compose",
                "narration": "Tap the compose button.",
                "shapes": [{
                    "type": "rect",
                    "x": 900,
                    "y": 2200,
                    "w": 120,
                    "h": 120,
                    "color": "#ffcc00"
                }]
            }
        });

        let result = dispatch_screen_draw_pack(
            service.event_broadcaster.as_ref(),
            &session,
            &session.agent_id,
            Some("@tutor show me where to tap"),
            &args,
            OverlayTarget::RealtimeClient,
            &[context],
            Some("ios-turn-1"),
        )
        .await;

        assert_eq!(result["success"], true);
        assert_eq!(result["overlay_target"], "realtime_client");
        let event = tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                if let RuntimeTransportEvent::AgentEvent { event } =
                    receiver.recv().await.expect("realtime event")
                {
                    if event.event_type == RuntimeAgentEventType::TutorDrawShape.as_str() {
                        break event;
                    }
                }
            }
        })
        .await
        .expect("tutor.draw.shape event");
        assert_eq!(event.payload["chat_turn_id"], "ios-turn-1");
        assert_eq!(
            event.payload["shape_json"]["capture_image_size"]["width"],
            1179
        );
    }

