    #[tokio::test]
    async fn stale_capture_cleanup_removes_only_unreferenced_server_captures() {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let (artifact_service, _orchestrator) =
            build_test_artifact_v2_harness(&temp_dir.path().join("artifact-v2"));
        let store = Arc::new(FileChatStore::with_workspace_layout(
            artifact_service.workspace().clone(),
        ));
        let session = store
            .get_or_create_active_session(
                "user",
                "workspace",
                "thread",
                &ChatChannel::web(),
                DEFAULT_AGENT_ID,
            )
            .await
            .expect("session");
        let prompt_manager = Arc::new(PromptManager::new(Arc::new(DummyPromptStore)));
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
        let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
            HashMap::new(),
            HashMap::new(),
        )));
        let chat_store: Arc<dyn ChatStore> = store.clone();
        let service = ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster)
            .with_artifact_v2_service(artifact_service);
        let capture_context = ScreenCaptureAttachmentContext {
            server_registered: true,
            mode: "screenshot".to_string(),
            coordinate_space: SCREEN_CAPTURE_COORDINATE_SPACE_CAPTURE.to_string(),
            image_size: None,
            screen_rect: None,
        };

        let orphan = service
            .store_attachment_with_context(
                &session.id,
                "orphan.png",
                "image/png",
                b"orphan",
                Some("voice screen capture".to_string()),
                Some(capture_context.clone()),
            )
            .await
            .expect("stage orphan capture");
        assert!(service
            .discard_unreferenced_screen_capture_attachment(&session.id, &orphan.id)
            .await
            .expect("discard orphan capture"));
        assert!(service
            .resolve_session_output(&session.id, &orphan.stored_name)
            .await
            .is_err());

        let active_owned = service
            .store_attachment_with_context(
                &session.id,
                "active-owned.png",
                "image/png",
                b"active",
                Some("voice screen capture".to_string()),
                Some(capture_context.clone()),
            )
            .await
            .expect("stage active-owned capture");
        let active_token = CancellationToken::new();
        assert!(
            service
                .try_register_owned_active_chat_run_with_token_admitted(
                    &session.id,
                    active_token.clone(),
                    "voice-owner",
                )
                .await
        );
        assert!(!service
            .discard_unreferenced_screen_capture_attachment(&session.id, &active_owned.id)
            .await
            .expect("retain capture reserved by active turn"));
        assert!(!service
            .discard_unreferenced_screen_capture_attachment_for_owner(
                &session.id,
                &active_owned.id,
                "different-voice-owner",
            )
            .await
            .expect("a different voice call must not discard the capture"));
        assert!(service
            .discard_unreferenced_screen_capture_attachment_for_owner(
                &session.id,
                &active_owned.id,
                "voice-owner",
            )
            .await
            .expect("owning turn may discard its uncommitted capture"));
        active_token.cancel();
        assert!(service.clear_cancelled_active_chat_run(&session.id));

        let committed = service
            .store_attachment_with_context(
                &session.id,
                "committed.png",
                "image/png",
                b"committed",
                Some("voice screen capture".to_string()),
                Some(capture_context),
            )
            .await
            .expect("stage committed capture");
        store
            .append_message(
                &session.id,
                ChatService::build_attachment_message(
                    &session.id,
                    committed.stored_name.clone(),
                    committed.mime_type.clone(),
                    committed.size,
                    None,
                    committed.label.clone(),
                    11,
                    Some("turn-committed".to_string()),
                    Some("chat-web".to_string()),
                    None,
                ),
            )
            .await
            .expect("persist committed capture reference");
        assert!(!service
            .discard_unreferenced_screen_capture_attachment(&session.id, &committed.id)
            .await
            .expect("retain committed capture"));
        assert!(service
            .resolve_session_output(&session.id, &committed.stored_name)
            .await
            .is_ok());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn file_index_transactions_serialize_across_chat_service_instances() {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let (artifact_service, _orchestrator) =
            build_test_artifact_v2_harness(&temp_dir.path().join("artifact-v2"));
        let store = Arc::new(FileChatStore::with_workspace_layout(
            artifact_service.workspace().clone(),
        ));
        let session = store
            .get_or_create_active_session(
                "user",
                "workspace",
                "thread",
                &ChatChannel::web(),
                DEFAULT_AGENT_ID,
            )
            .await
            .expect("session");

        let build_service = || {
            let prompt_manager = Arc::new(PromptManager::new(Arc::new(DummyPromptStore)));
            let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
            let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
                HashMap::new(),
                HashMap::new(),
            )));
            let chat_store: Arc<dyn ChatStore> = store.clone();
            Arc::new(
                ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster)
                    .with_artifact_v2_service(Arc::clone(&artifact_service)),
            )
        };
        let first = build_service();
        let second = build_service();
        let start = Arc::new(Barrier::new(2));
        let active = Arc::new(AtomicUsize::new(0));
        let maximum = Arc::new(AtomicUsize::new(0));

        let spawn_update = |service: Arc<ChatService>, id: &'static str| {
            let session = session.clone();
            let start = Arc::clone(&start);
            let active = Arc::clone(&active);
            let maximum = Arc::clone(&maximum);
            tokio::spawn(async move {
                start.wait();
                service
                    .update_session_file_index(&session, |index| {
                        let in_flight = active.fetch_add(1, Ordering::SeqCst) + 1;
                        maximum.fetch_max(in_flight, Ordering::SeqCst);
                        std::thread::sleep(std::time::Duration::from_millis(25));
                        index.files.push(ChatSessionFileRecord {
                            id: id.to_string(),
                            stored_name: format!("{id}.txt"),
                            original_name: format!("{id}.txt"),
                            mime_type: "text/plain".to_string(),
                            size: 1,
                            label: None,
                            screen_capture: None,
                            prompt_image: false,
                            origin: ChatSessionFileOrigin::Attachment,
                            source_task_output_id: None,
                            source_task_id: None,
                            created_at: 1,
                        });
                        active.fetch_sub(1, Ordering::SeqCst);
                        Ok(())
                    })
                    .await
            })
        };

        let first_update = spawn_update(first, "first");
        let second_update = spawn_update(Arc::clone(&second), "second");
        first_update
            .await
            .expect("first join")
            .expect("first update");
        second_update
            .await
            .expect("second join")
            .expect("second update");

        assert_eq!(maximum.load(Ordering::SeqCst), 1);
        let index = second
            .load_session_file_index(&session)
            .await
            .expect("final file index");
        assert_eq!(index.files.len(), 2);
        assert!(index.files.iter().any(|record| record.id == "first"));
        assert!(index.files.iter().any(|record| record.id == "second"));
    }

