    #[test]
    fn task_user_summary_scan_has_exact_preview_boundary_and_finds_late_tutor_result() {
        let exact = vec![b'x'; TASK_USER_SUMMARY_PREVIEW_MAX_BYTES];
        let exact_source =
            scan_task_user_summary_source(std::io::Cursor::new(exact)).expect("exact scan");
        assert_eq!(
            exact_source.preview.len(),
            TASK_USER_SUMMARY_PREVIEW_MAX_BYTES
        );
        assert!(!exact_source.truncated);

        let sentinel = concat!(
            "TUTOR_ACTION_RESULT: ",
            "{\"run_id\":\"run-late\",\"status\":\"succeeded\",\"evidence\":\"visible\"}"
        );
        let mut late = vec![b'x'; TASK_USER_SUMMARY_PREVIEW_MAX_BYTES + 1];
        late.push(b'\n');
        late.extend_from_slice(sentinel.as_bytes());
        let late_source = scan_task_user_summary_source(TinyChunkReader {
            inner: std::io::Cursor::new(late),
            chunk_bytes: 11,
        })
        .expect("late tutor scan");
        assert_eq!(
            late_source.preview.len(),
            TASK_USER_SUMMARY_PREVIEW_MAX_BYTES
        );
        assert!(late_source.truncated);
        assert_eq!(
            late_source
                .tutor_action_line
                .expect("late tutor sentinel")
                .expect("bounded tutor sentinel"),
            sentinel
        );
    }

    #[test]
    fn task_user_summary_scan_admits_exact_tutor_line_and_rejects_one_byte_over() {
        let shell = "TUTOR_ACTION_RESULT: {\"run_id\":\"run-exact\",\"status\":\"succeeded\",\"evidence\":\"\"}";
        let evidence_bytes = TUTOR_ACTION_RESULT_MAX_LINE_BYTES
            .checked_sub(shell.len())
            .expect("line ceiling fits fixture shell");
        let exact = shell.replacen("\"\"}", &format!("\"{}\"}}", "x".repeat(evidence_bytes)), 1);
        assert_eq!(exact.len(), TUTOR_ACTION_RESULT_MAX_LINE_BYTES);
        let exact_source = scan_task_user_summary_source(std::io::Cursor::new(exact.as_bytes()))
            .expect("exact action scan");
        assert!(matches!(exact_source.tutor_action_line, Some(Ok(_))));

        let mut over = exact.into_bytes();
        over.push(b'x');
        let over_source =
            scan_task_user_summary_source(std::io::Cursor::new(over)).expect("over-limit scan");
        assert!(matches!(over_source.tutor_action_line, Some(Err(_))));
    }

