    #[tokio::test]
    async fn load_task_user_summary_requires_current_output_revision() {
        use crate::magician_v2::artifact_v2::service::{
            task_summary_output_revision, TaskSummarySidecar, TASK_SUMMARY_SIDECAR_FILE,
        };

        let tmp = TempDir::new().expect("temp dir");
        let workspace = ArtifactV2Workspace::new(tmp.path().join("magician_data_v3"));
        let principal = "anonymous";
        let workspace_name = "default";
        let task_id = "task-revision-authority";
        let output = OutputRef {
            output_id: "out_task_user_task-revision-authority".to_string(),
            scope: "task".to_string(),
            audience: "user".to_string(),
            role: "primary_task_user".to_string(),
            relative_path: "outputs/out_task_user_task-revision-authority.md".to_string(),
            media_type: "text/markdown".to_string(),
            created_at: "2026-08-02T10:00:00Z".to_string(),
            source_execution_id: Some("exec-current".to_string()),
            source_plan_id: Some("plan-current".to_string()),
            source_output_ids: vec!["out-exec-current".to_string()],
        };
        let outputs_dir = workspace.task_outputs_dir(principal, workspace_name, task_id);
        fs::create_dir_all(&outputs_dir)
            .await
            .expect("create task outputs dir");
        workspace
            .write_path(
                workspace
                    .task_dir(principal, workspace_name, task_id)
                    .join(&output.relative_path),
                b"Current primary output text.",
            )
            .await
            .expect("write current primary output");
        workspace
            .write_json_atomic_path(
                workspace.task_refs_path(principal, workspace_name, task_id),
                &TaskRefs {
                    task_id: task_id.to_string(),
                    outputs: vec![output.clone()],
                    default_task_agent_output_id: None,
                    primary_user_output_id: Some(output.output_id.clone()),
                    updated_at: Some(output.created_at.clone()),
                },
            )
            .await
            .expect("write authoritative task refs");

        workspace
            .write_json_atomic_path(
                outputs_dir.join(TASK_SUMMARY_SIDECAR_FILE),
                &TaskSummarySidecar {
                    text: "Stale fabricated summary".to_string(),
                    generated_by: "llm".to_string(),
                    source_output_id: output.output_id.clone(),
                    source_output_revision: Some("stale-revision".to_string()),
                },
            )
            .await
            .expect("write stale sidecar");
        let stale_rejected = load_task_user_summary(&workspace, principal, workspace_name, task_id)
            .await
            .expect("raw fallback summary");
        assert_eq!(stale_rejected, "Current primary output text.");

        workspace
            .write_json_atomic_path(
                outputs_dir.join(TASK_SUMMARY_SIDECAR_FILE),
                &TaskSummarySidecar {
                    text: "Current compact summary".to_string(),
                    generated_by: "llm".to_string(),
                    source_output_id: output.output_id.clone(),
                    source_output_revision: Some(task_summary_output_revision(&output)),
                },
            )
            .await
            .expect("write current sidecar");
        let current_accepted =
            load_task_user_summary(&workspace, principal, workspace_name, task_id)
                .await
                .expect("current sidecar summary");
        assert!(current_accepted.starts_with("Current compact summary"));
        assert!(current_accepted.contains("LLM generated"));
    }

