    // ---- P3 Task 3.3: a chat answer that is a secret never reaches the model

    #[tokio::test]
    async fn a_sensitive_chat_answer_is_held_for_the_turn_and_never_shown_to_the_model() {
        use crate::magician_v2::user_requests::{UserRequestService, UserResponse};
        const CANARY: &str = "p3-chat-pw-canary-7";
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let store = Arc::new(FileChatStore::new(temp_dir.path().join("chat")));
        let session = store
            .get_or_create_active_session(
                "owner",
                "workspace",
                "thread",
                &ChatChannel::web(),
                DEFAULT_AGENT_ID,
            )
            .await
            .expect("session");
        let prompt_manager = Arc::new(PromptManager::new(Arc::new(DummyPromptStore)));
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
        let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
            HashMap::new(),
            HashMap::new(),
        )));
        let history_path = temp_dir.path().join("requests-history.json");
        let user_requests = Arc::new(
            UserRequestService::new(Arc::clone(&broadcaster))
                .with_history_persist_path(&history_path),
        );
        let chat_store: Arc<dyn ChatStore> = store.clone();
        let service = Arc::new(
            ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster)
                .with_user_request_service(Arc::clone(&user_requests)),
        );

        let call = LLMToolCall {
            id: "tc-1".into(),
            name: "need_user_input".into(),
            arguments: json!({ "question": "Your account password", "input_type": "password" }),
        };
        let asked = {
            let service = Arc::clone(&service);
            let session = session.clone();
            tokio::spawn(async move {
                service
                    .dispatch_chat_need_user_input(
                        &session,
                        DEFAULT_AGENT_ID,
                        &call,
                        Some("turn-1"),
                        None,
                    )
                    .await
            })
        };
        // The operator answers through the canonical owner.
        let pending = loop {
            let pending = user_requests
                .list_pending_for_scope("owner", "workspace")
                .await;
            if let Some(request) = pending.into_iter().next() {
                break request;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        };
        assert_eq!(
            pending.sensitive.as_ref().and_then(|spec| spec.kind),
            Some(crate::magician_v2::user_requests::SensitiveKind::Password)
        );
        user_requests
            .respond_scoped(
                UserResponse {
                    request_id: pending.id.clone(),
                    decision: "provide_input".into(),
                    input: Some(CANARY.into()),
                    channel: "web".into(),
                    sensitive: Vec::new(),
                },
                Some("owner"),
                Some("workspace"),
            )
            .await;
        let result = asked.await.expect("dispatch");

        // What the model sees: a placeholder and a status, never the value.
        let rendered = serde_json::to_string(&result).unwrap();
        assert!(
            !rendered.contains(CANARY),
            "the tool result carried the value: {rendered}"
        );
        assert_eq!(result["status"], "answered");
        assert_eq!(result["sensitive"][0]["kind"], "password");
        assert_eq!(result["sensitive"][0]["status"], "held");
        assert_eq!(result["sensitive"][0]["placeholder"], "[REF:password]");
        assert!(result["input"].is_null());
        // The turn holds it for the pack sub-runs it starts ...
        assert_eq!(
            service.held_turn_secret_keys(&session.id),
            vec!["password".to_string()]
        );
        // ... custody has nothing left for anyone else ...
        assert!(user_requests
            .take_sensitive(
                result["sensitive"][0]["reference"].as_str().unwrap(),
                &pending.id,
                "owner",
                "workspace"
            )
            .is_none());
        // ... and the turn's end drops it: a later turn asks again.
        service.clear_active_chat_run(&session.id);
        assert!(service.held_turn_secret_keys(&session.id).is_empty());

        // History carries the value-free response only.
        let history = std::fs::read_to_string(&history_path).unwrap_or_default();
        assert!(
            history.contains(&pending.id),
            "the resolution itself was persisted"
        );
        assert!(
            !history.contains(CANARY),
            "request history carried the value"
        );
    }

    /// Everything a chat custody test needs: a session, the request service
    /// and a chat service wired to it.
    async fn chat_custody_fixture(
        temp_dir: &std::path::Path,
    ) -> (
        ChatSession,
        Arc<crate::magician_v2::user_requests::UserRequestService>,
        Arc<ChatService>,
    ) {
        use crate::magician_v2::user_requests::UserRequestService;
        let store = Arc::new(FileChatStore::new(temp_dir.join("chat")));
        let session = store
            .get_or_create_active_session(
                "owner",
                "workspace",
                "thread",
                &ChatChannel::web(),
                DEFAULT_AGENT_ID,
            )
            .await
            .expect("session");
        let prompt_manager = Arc::new(PromptManager::new(Arc::new(DummyPromptStore)));
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
        let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
            HashMap::new(),
            HashMap::new(),
        )));
        let user_requests = Arc::new(UserRequestService::new(Arc::clone(&broadcaster)));
        let chat_store: Arc<dyn ChatStore> = store.clone();
        let service = Arc::new(
            ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster)
                .with_user_request_service(Arc::clone(&user_requests)),
        );
        (session, user_requests, service)
    }

    #[tokio::test]
    async fn a_cancelled_turn_drops_its_hold_so_the_next_turn_seeds_nothing() {
        // Reviewer finding at the P3 gate: `cancel_chat_run` removed the slot
        // but left the hold, and the cancelled turn's guard skips the clear —
        // the next turn's pack would have been seeded with the secret.
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let (session, _user_requests, service) = chat_custody_fixture(temp_dir.path()).await;
        let token = CancellationToken::new();
        service.active_chat_runs.insert(
            session.id.clone(),
            ActiveChatRun {
                token: token.clone(),
                owner_id: None,
            },
        );
        service
            .turn_secrets
            .entry(session.id.clone())
            .or_default()
            .deposit(
                "password".to_string(),
                crate::magician_v2::user_requests::SensitiveKind::Password,
                zeroize::Zeroizing::new("p3-cancel-canary".to_string()),
                chrono::Utc::now().timestamp_millis(),
            );
        assert_eq!(
            service.held_turn_secret_keys(&session.id),
            vec!["password".to_string()]
        );
        assert!(service.cancel_chat_run(&session.id).await.expect("cancel"));
        assert!(token.is_cancelled());
        assert!(
            service.held_turn_secret_keys(&session.id).is_empty(),
            "the hold outlived the turn"
        );
    }

    #[tokio::test]
    async fn a_turn_cancelled_before_the_answer_withdraws_its_ask() {
        // Reviewer finding at the P3 gate: dropping the `ask` future left the
        // request pending for the operator to answer into custody with no
        // consumer. A cancelled turn now withdraws the ask it will never take.
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let (session, user_requests, service) = chat_custody_fixture(temp_dir.path()).await;
        let token = CancellationToken::new();
        let call = LLMToolCall {
            id: "tc-cancel".into(),
            name: "need_user_input".into(),
            arguments: json!({ "question": "Enter the verification code we sent", "input_type": "text" }),
        };
        let asked = {
            let service = Arc::clone(&service);
            let session = session.clone();
            let token = token.clone();
            tokio::spawn(async move {
                service
                    .dispatch_chat_need_user_input(
                        &session,
                        DEFAULT_AGENT_ID,
                        &call,
                        Some("turn-2"),
                        Some(token),
                    )
                    .await
            })
        };
        let pending = loop {
            let pending = user_requests
                .list_pending_for_scope("owner", "workspace")
                .await;
            if let Some(request) = pending.into_iter().next() {
                break request;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        };
        assert!(pending.sensitive.as_ref().is_some_and(|spec| spec.one_time));
        token.cancel();
        let result = asked.await.expect("dispatch");
        assert_eq!(result["status"], "cancelled");
        // The ask is gone with the turn; a code typed later has nowhere to go.
        assert!(
            user_requests
                .list_pending_for_scope("owner", "workspace")
                .await
                .is_empty(),
            "the cancelled turn left its ask pending"
        );
        let history = user_requests.list_history_for_scope("owner", "workspace", None);
        let row = history
            .iter()
            .find(|row| row.request.id == pending.id)
            .expect("resolved row");
        assert_eq!(
            row.response.as_ref().map(|r| r.decision.as_str()),
            Some("cancel")
        );
        assert_eq!(
            row.response.as_ref().map(|r| r.channel.as_str()),
            Some("chat_turn_cancelled")
        );
    }

