    #[derive(Default)]
    struct MockChatLlmClient {
        text_responses: Mutex<VecDeque<String>>,
        streaming_responses: Mutex<VecDeque<LLMResponse>>,
        // Per-turn scripted deltas for `generate_response_with_tools_streaming`.
        // Each inner Vec is one turn's sequence; the mock pops the front,
        // drives `on_delta` for each delta in order, then returns a
        // `ChatLlmResponse` whose `content` is the concatenation of every
        // `StreamDelta::Token(text)` in that turn (so the response text
        // matches what was streamed).
        streaming_with_tools_scripts: Mutex<VecDeque<Vec<magicllm::StreamDelta>>>,
        histories: Mutex<Vec<Vec<ChatLlmTranscriptEntry>>>,
        default_profiles: Mutex<HashMap<String, String>>,
        adaptive_pairs: Mutex<HashMap<String, (String, String)>>,
        observed_profile_overrides: Mutex<Vec<Option<String>>>,
    }

    impl MockChatLlmClient {
        fn record_history(&self, history: &[ChatLlmTranscriptEntry]) {
            self.histories
                .lock()
                .expect("history lock")
                .push(history.to_vec());
        }

        #[allow(dead_code)]
        fn queue_streaming_with_tools_deltas(&self, deltas: Vec<magicllm::StreamDelta>) {
            self.streaming_with_tools_scripts
                .lock()
                .expect("streaming-with-tools script lock")
                .push_back(deltas);
        }
    }

    #[async_trait]
    impl ChatLlmClient for MockChatLlmClient {
        fn list_chat_profiles(&self) -> Vec<ChatProfileInfo> {
            Vec::new()
        }

        fn list_chat_profile_warnings(&self) -> Vec<ChatProfileWarning> {
            Vec::new()
        }

        fn adaptive_pair_for_profile(&self, profile_name: &str) -> Option<(String, String)> {
            self.adaptive_pairs
                .lock()
                .expect("adaptive pairs lock")
                .get(profile_name)
                .cloned()
        }

        fn default_profile_for_operation(&self, operation_key: &str) -> Option<String> {
            self.default_profiles
                .lock()
                .expect("default profiles lock")
                .get(operation_key)
                .cloned()
        }

        fn local_default_profile_for_operation(&self, operation_key: &str) -> Option<String> {
            self.default_profiles
                .lock()
                .expect("default profiles lock")
                .get(operation_key)
                .cloned()
        }

        fn telemetry_hint_for_profile(
            &self,
            _profile_override: Option<&str>,
        ) -> Option<
            crate::magician_v2::query_analysis::multi_llm_service::ChatCompletionTelemetryHint,
        > {
            None
        }

        async fn generate_response(
            &self,
            _system_prompt: &str,
            history: &[ChatLlmTranscriptEntry],
            _transcript_context: Option<&ChatTranscriptContext>,
            profile_override: Option<&str>,
        ) -> Result<ChatLlmResponse> {
            self.record_history(history);
            self.observed_profile_overrides
                .lock()
                .expect("profile overrides lock")
                .push(profile_override.map(str::to_string));
            Ok(ChatLlmResponse {
                content: Some(
                    self.text_responses
                        .lock()
                        .expect("text response lock")
                        .pop_front()
                        .expect("queued text response"),
                ),
                tool_calls: Vec::new(),
                provider_state: None,
                reasoning_text: None,
                usage: None,
                telemetry: None,
            })
        }

        async fn generate_response_with_tools(
            &self,
            _system_prompt: &str,
            _history: &[ChatLlmTranscriptEntry],
            _tools: Vec<LLMToolSpec>,
            _transcript_context: Option<&ChatTranscriptContext>,
            _profile_override: Option<&str>,
        ) -> Result<ChatLlmResponse> {
            Err(anyhow::anyhow!(
                "chat-local tool generation should not be used after chat-local registry removal"
            ))
        }

        async fn generate_response_streaming(
            &self,
            _system_prompt: &str,
            history: &[ChatLlmTranscriptEntry],
            _tools: Vec<LLMToolSpec>,
            tx: tokio::sync::mpsc::Sender<StreamDelta>,
            _transcript_context: Option<&ChatTranscriptContext>,
            _profile_override: Option<&str>,
        ) -> Result<()> {
            self.record_history(history);
            let response = self
                .streaming_responses
                .lock()
                .expect("streaming response lock")
                .pop_front()
                .expect("queued streaming response");
            if let Some(text) = response.text.clone() {
                tx.send(StreamDelta::Token(text.to_string()))
                    .await
                    .expect("stream token");
            }
            tx.send(StreamDelta::Done(response))
                .await
                .expect("stream done");
            Ok(())
        }

        async fn generate_response_with_tools_streaming(
            &self,
            _system_prompt: &str,
            history: &[ChatLlmTranscriptEntry],
            _tools: Vec<LLMToolSpec>,
            _transcript_context: Option<&ChatTranscriptContext>,
            profile_override: Option<&str>,
            _disclosure_guard: Option<magicllm::LlmDisclosureGuard>,
            on_delta: Box<dyn Fn(StreamDelta) + Send + Sync>,
        ) -> Result<ChatLlmResponse> {
            self.record_history(history);
            self.observed_profile_overrides
                .lock()
                .expect("profile overrides lock")
                .push(profile_override.map(str::to_string));
            // Pop the next scripted delta sequence for this turn. Tests
            // pre-load these via `queue_streaming_with_tools_deltas`.
            // Empty queue = the mock falls back to a quiet success
            // (matches the `text_responses` shape for backward compat).
            let deltas = self
                .streaming_with_tools_scripts
                .lock()
                .expect("streaming-with-tools script lock")
                .pop_front()
                .unwrap_or_default();
            // Drive `on_delta` synchronously, mirroring what magicllm's
            // real streaming loop does. Token deltas land on the SSE
            // forwarding path; reasoning + tool-call deltas land on
            // the broadcaster path (in production); both are exercised
            // here by callers that supply them.
            let mut assembled = String::new();
            for delta in &deltas {
                if let StreamDelta::Token(text) = delta {
                    assembled.push_str(text);
                }
                on_delta(delta.clone());
            }
            Ok(ChatLlmResponse {
                content: if assembled.is_empty() {
                    None
                } else {
                    Some(assembled)
                },
                tool_calls: Vec::new(),
                provider_state: None,
                reasoning_text: None,
                usage: None,
                telemetry: None,
            })
        }
    }

    async fn create_test_service(
        llm_client: Arc<MockChatLlmClient>,
    ) -> (ChatService, Arc<FileChatStore>, ChatSession, TempDir) {
        create_test_service_with_agents(llm_client, &[]).await
    }

    async fn create_test_service_with_agents(
        llm_client: Arc<MockChatLlmClient>,
        extra_agent_ids: &[&str],
    ) -> (ChatService, Arc<FileChatStore>, ChatSession, TempDir) {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let store = Arc::new(FileChatStore::new(temp_dir.path().join("chat")));
        // Use the real prompt storage (committed JSON templates under
        // `data/magician_v2/prompts/`) so tests that exercise prompt
        // rendering — e.g. anything that triggers
        // `render_chat_outer_loop_prompt` — actually get a working
        // template instead of failing on a stub `DummyPromptStore`.
        // The store is read-only from the test's perspective (no
        // `save_prompt` calls happen), so parallel tests hitting the
        // same on-disk files is safe.
        use crate::magician_v2::prompts::{json_storage::JsonStorageConfig, JsonPromptStorage};
        let prompt_storage = JsonPromptStorage::new(JsonStorageConfig {
            storage_dir: crate::magician_v2::prompts::json_storage::default_prompt_dir(),
            enable_cache: false,
            max_cache_entries: 10,
        })
        .expect("json prompt storage");
        let prompt_manager = Arc::new(PromptManager::new(Arc::new(prompt_storage)));
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
        let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
            HashMap::new(),
            HashMap::new(),
        )));

        let chat_store: Arc<dyn ChatStore> = store.clone();
        let definition_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("workspace root")
            .join("magician_data_v3/system/agent_templates");
        // Use a writable, scoped runtime store just like production. Pointing
        // the store directly at the read-only seed made definition lookup work
        // but left the scoped trust-policy file absent, so inline chat failed
        // before the streaming contract under test could run.
        let definition_store =
            AgentDefinitionStore::with_workspace_root(temp_dir.path().join("agent-runtime"));
        let personal_assistant_yaml = tokio::fs::read_to_string(
            definition_root.join("agents/personal-assistant/definition.agent.yaml"),
        )
        .await
        .expect("shipped personal-assistant definition");
        let mut personal_assistant =
            crate::magician_v2::agents::AgentDefinition::from_yaml_str(&personal_assistant_yaml)
                .expect("valid shipped personal-assistant definition");
        // `create_definition` is the same public create boundary exercised by
        // the API and therefore only accepts a v1 seed. The shipped template
        // may already have accumulated revisions in git.
        personal_assistant.version = 1;
        for agent_id in extra_agent_ids {
            let mut test_agent = personal_assistant.clone();
            test_agent.agent_id = (*agent_id).to_string();
            test_agent.name = format!("Test {agent_id}");
            test_agent.aliases.clear();
            test_agent.is_primary = false;
            definition_store
                .create_definition(test_agent)
                .await
                .unwrap_or_else(|error| panic!("seed {agent_id} test definition: {error}"));
        }
        definition_store
            .create_definition(personal_assistant)
            .await
            .expect("seed personal-assistant test template");
        definition_store
            .for_scope("user", "workspace")
            .storage()
            .ensure_base_layout()
            .await
            .expect("seed scoped trust policy");
        let service = ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster)
            .with_llm_client(llm_client)
            // Inline chat now fails closed without an authenticated agent
            // definition and scoped trust policy.
            .with_definition_store(Arc::new(definition_store));

        let session = store
            .get_or_create_active_session(
                "user",
                "workspace",
                "thread",
                &ChatChannel::web(),
                DEFAULT_AGENT_ID,
            )
            .await
            .expect("session");

        (service, store, session, temp_dir)
    }

    #[tokio::test]
    async fn unchanged_tutor_authorization_revision_survives_definition_reload() {
        let llm = Arc::new(MockChatLlmClient::default());
        let (service, _store, session, _tmp) = create_test_service(llm).await;
        let definition = service
            .load_agent_definition(&session, &session.agent_id)
            .await
            .expect("scoped personal-assistant definition");
        let trust_policy = load_chat_trust_dispatch_policy(
            service.definition_store.as_ref(),
            &session.principal,
            &session.workspace,
            &definition,
        )
        .await
        .expect("scoped trust policy");
        let expected = ChatTurnAuthorizationRevision {
            definition_digest: chat_definition_digest(&definition)
                .expect("canonical chat definition digest"),
            trust_policy_digest: trust_policy.policy_digest,
            registry_tool_names: BTreeSet::new(),
            delegation_target_ids: BTreeSet::new(),
            handover_target_ids: BTreeSet::new(),
            invocation_surface: crate::magician_v2::agents::InvocationSurface::Tutor,
            feature_mode: crate::magician_v2::agents::FeatureMode::Tutor,
        };

        assert!(
            service
                .chat_turn_authorization_is_current(&session, &session.agent_id, &expected)
                .await
                .expect("authorization revalidation"),
            "reloading an unchanged map-bearing definition must not reject a Tutor tool call"
        );
    }

    #[test]
    fn select_preferred_agent_id_for_thread_prefers_active_session_then_newest_created() {
        let sessions = vec![
            ChatSession {
                internal_voice: None,
                id: "archived-newly-retitled".to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                agent_id: "old-archived-agent".to_string(),
                ui_thread_id: "thread-a".to_string(),
                title: None,
                origin_channel: ChatChannel::web(),
                status: ChatSessionStatus::Archived,
                history_lane: crate::magician_v2::history::HistoryLane::Personal,
                is_default_session: false,
                created_at: 10,
                updated_at: 999,
            },
            ChatSession {
                internal_voice: None,
                id: "latest-created".to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                agent_id: "newest-created-agent".to_string(),
                ui_thread_id: "thread-a".to_string(),
                title: None,
                origin_channel: ChatChannel::web(),
                status: ChatSessionStatus::Archived,
                history_lane: crate::magician_v2::history::HistoryLane::Personal,
                is_default_session: false,
                created_at: 200,
                updated_at: 200,
            },
            ChatSession {
                internal_voice: None,
                id: "active-thread".to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                agent_id: "active-agent".to_string(),
                ui_thread_id: "thread-a".to_string(),
                title: None,
                origin_channel: ChatChannel::web(),
                status: ChatSessionStatus::Active,
                history_lane: crate::magician_v2::history::HistoryLane::Personal,
                is_default_session: false,
                created_at: 150,
                updated_at: 300,
            },
        ];

        assert_eq!(
            select_preferred_agent_id_for_thread(&sessions, "thread-a").as_deref(),
            Some("active-agent")
        );

        let archived_only: Vec<ChatSession> = sessions
            .into_iter()
            .map(|mut session| {
                session.status = ChatSessionStatus::Archived;
                session
            })
            .collect();

        assert_eq!(
            select_preferred_agent_id_for_thread(&archived_only, "thread-a").as_deref(),
            Some("newest-created-agent")
        );
    }

