    #[tokio::test]
    async fn get_or_create_session_seeds_default_personality() {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let v3_root = temp_dir.path().join("v3");
        // Personality seeds resolve through the skills catalog only —
        // the legacy `system/capability_templates/personality/*.yaml`
        // loader was removed in P4-1 and the YAMLs themselves were
        // deleted in the personality-decommission cleanup. The
        // system-shared `system/skills/` tier was retired in v0.6.572,
        // so author the witty personality-mode skill at the workspace
        // skills layer so `seed_personality_if_empty` finds it.
        let skill_dir = v3_root
            .join("scopes")
            .join("user")
            .join("workspace")
            .join("skills")
            .join("witty");
        std::fs::create_dir_all(&skill_dir).expect("skill dir");
        std::fs::write(
            skill_dir.join("SKILL.md"),
            "---\nname: witty\ndescription: Witty persona for the seed test.\n\
             metadata:\n  magician:\n    personality:\n      \
             active_mode: witty\n      \
             voice: |\n        Dry and sharp.\n      \
             expression_bias: |\n        Prefer GIFs for wins.\n      \
             expression_triggers: |\n        Success -> use a GIF.\n      \
             suppression_rules: |\n        No artifacts for terse input.\n---\n\
             # Witty\n\nDry and sharp persona used by the seed test.\n",
        )
        .expect("skill md");

        let memory_resolver = AgentMemoryResolver::new(&v3_root);
        let capability_workspace = Arc::new(CapabilityWorkspaceManager::new(
            ArtifactV2Workspace::new(&v3_root),
            temp_dir.path(),
        ));

        let mut agents = HashMap::new();
        agents.insert(
            DEFAULT_AGENT_ID.to_string(),
            AgentPersona {
                persona: "Base persona".to_string(),
                kind: PromptAgentKind::User,
                default_personality: Some("witty".to_string()),
            },
        );

        let store = Arc::new(FileChatStore::new(temp_dir.path().join("chat")));
        let prompt_manager = Arc::new(PromptManager::new(Arc::new(DummyPromptStore)));
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
        let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
            HashMap::new(),
            HashMap::new(),
        )));
        let chat_store: Arc<dyn ChatStore> = store;
        let service = ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster)
            .with_persona_provider(Arc::new(ConfigAgentPersonaProvider::new(agents)))
            .with_memory_resolver(memory_resolver.clone())
            .with_capability_workspace(capability_workspace);

        service
            .get_or_create_session("user", "workspace", "thread", &ChatChannel::web(), None)
            .await
            .expect("session");

        let memory_service = memory_resolver
            .resolve_for_scope("user", "workspace")
            .expect("memory service");
        let tier_def = ChatService::personality_profile_tier_definition();
        let seeded = memory_service
            .load_native_tier(DEFAULT_AGENT_ID, &tier_def, None)
            .await
            .expect("load personality tier")
            .expect("seeded personality tier");

        assert_eq!(
            seeded
                .fields
                .get("active_mode")
                .and_then(|value| value.as_str()),
            Some("witty")
        );
        assert_eq!(
            seeded
                .fields
                .get("expression_triggers")
                .and_then(|value| value.as_str()),
            Some("Success -> use a GIF.\n")
        );
    }

