    #[tokio::test]
    async fn new_feature_session_rotates_latest_agent_without_archiving_sibling_agent() {
        let llm = Arc::new(MockChatLlmClient::default());
        let (service, store, _session, _tmp) =
            create_test_service_with_agents(llm, &["agent-a", "agent-b"]).await;

        let sibling = store
            .new_session(
                "user",
                "workspace",
                "screens",
                &ChatChannel::web(),
                "agent-a",
            )
            .await
            .expect("sibling session");
        tokio::time::sleep(std::time::Duration::from_millis(2)).await;
        let prior = store
            .new_session(
                "user",
                "workspace",
                "screens",
                &ChatChannel::web(),
                "agent-b",
            )
            .await
            .expect("prior preferred session");

        let fresh = service
            .new_session("user", "workspace", "screens", &ChatChannel::web())
            .await
            .expect("fresh rolling session");

        assert_eq!(fresh.agent_id, "agent-b");
        assert_eq!(
            store.get_session(&prior.id).await.unwrap().unwrap().status,
            ChatSessionStatus::Archived
        );
        assert_eq!(
            store
                .get_session(&sibling.id)
                .await
                .unwrap()
                .unwrap()
                .status,
            ChatSessionStatus::Active
        );
    }

