    #[tokio::test]
    async fn cancelled_owner_cleanup_does_not_clear_a_newer_active_run() {
        let llm = Arc::new(MockChatLlmClient::default());
        let (service, _store, _session, _tmp) = create_test_service(llm).await;
        let sid = "sess_voice_owner_replaced";
        let old = CancellationToken::new();
        service.register_active_chat_run_with_token(sid, old.clone());
        old.cancel();

        let newer = CancellationToken::new();
        service.register_active_chat_run_with_token(sid, newer.clone());
        assert!(!service.clear_cancelled_active_chat_run(sid));
        assert!(service.has_active_chat_run(sid));
        assert!(!newer.is_cancelled());
    }

