    #[tokio::test]
    async fn delete_queued_message_by_id_is_idempotent() {
        let llm = Arc::new(MockChatLlmClient::default());
        let (service, _store, _session, _tmp) = create_test_service(llm).await;
        let sid = "sess_phase2_c";
        let r1 = service.enqueue_chat_message(
            sid,
            Some("a"),
            &[],
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        );
        let r2 = service.enqueue_chat_message(
            sid,
            Some("b"),
            &[],
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        );
        let r3 = service.enqueue_chat_message(
            sid,
            Some("c"),
            &[],
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        );
        // Delete middle by id
        assert!(service.delete_queued_message(sid, &r2.id));
        let after = service.list_queued_messages(sid);
        assert_eq!(after.len(), 2);
        assert_eq!(after[0].id, r1.id);
        assert_eq!(after[1].id, r3.id);
        // Deleting an unknown id is a no-op
        assert!(!service.delete_queued_message(sid, "nope"));
        // Deleting the same id twice is idempotent
        assert!(!service.delete_queued_message(sid, &r2.id));
    }

