    /// Token streaming contract: when the inline turn runs under the
    /// streaming wrapper, `StreamDelta::Token(...)` events from the
    /// LLM streaming loop flow onto the SSE `tx` channel verbatim, in
    /// order, before the wrapper's canonical `Done` lands. Reasoning
    /// events stay on the broadcaster (not asserted here). This test
    /// pins the forwarding behavior so a regression at
    /// `process_chat_inline_turn`'s `on_delta` closure surfaces
    /// immediately.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn streaming_inline_turn_forwards_token_deltas_to_sse_channel() {
        let llm = Arc::new(MockChatLlmClient::default());
        // Three tokens + a reasoning block in the middle. Only the
        // tokens should land on the SSE channel; the reasoning block
        // is broadcaster-only and exercised separately.
        llm.queue_streaming_with_tools_deltas(vec![
            StreamDelta::Token("Hello".to_string()),
            StreamDelta::ReasoningStart {
                index: 0,
                signature: None,
            },
            StreamDelta::ReasoningDelta {
                index: 0,
                delta: "internal thinking".to_string(),
            },
            StreamDelta::ReasoningEnd {
                index: 0,
                total_chars: "internal thinking".len(),
            },
            StreamDelta::Token(", world".to_string()),
            StreamDelta::Token("!".to_string()),
        ]);
        let (service, _store, session, _tmp) = create_test_service(llm).await;
        let service = Arc::new(service);

        let (tx, mut rx) = tokio::sync::mpsc::channel::<StreamDelta>(64);
        // Exercise the production entry point so construction and first poll
        // happen behind the same lazy execution-runtime boundary as Actix.
        // A test-only forwarding async fn would rebuild the large inner future
        // on the caller stack and would not verify the production contract.
        let response = service
            .process_message_streaming_with_mode_on_execution_runtime(
                &session.id,
                Some("hi"),
                &[],
                tx,
                None,
                ChatMessageMode::Ask,
                None,
                None,
                None,
                false,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("streaming inline turn");

        // Drain the SSE channel into a Vec for ordered assertion.
        let mut received: Vec<StreamDelta> = Vec::new();
        while let Ok(delta) = rx.try_recv() {
            received.push(delta);
        }

        // Three tokens forwarded in order; reasoning deltas dropped
        // (broadcaster handles them); final Done from the wrapper.
        let token_texts: Vec<&str> = received
            .iter()
            .filter_map(|d| match d {
                StreamDelta::Token(text) => Some(text.as_str()),
                _ => None,
            })
            .collect();
        assert_eq!(token_texts, vec!["Hello", ", world", "!"]);

        // No Reasoning* variants reached the SSE channel.
        assert!(received.iter().all(|d| !matches!(
            d,
            StreamDelta::ReasoningStart { .. }
                | StreamDelta::ReasoningDelta { .. }
                | StreamDelta::ReasoningEnd { .. }
        )));

        // Exactly one Done envelope at the tail, carrying the
        // assembled assistant text.
        let done_count = received
            .iter()
            .filter(|d| matches!(d, StreamDelta::Done(_)))
            .count();
        assert_eq!(done_count, 1, "wrapper emits exactly one Done");
        match received.last().expect("Done last") {
            StreamDelta::Done(resp) => {
                assert_eq!(resp.text.as_deref(), Some("Hello, world!"));
            },
            _ => panic!("last delta must be Done"),
        }

        // ChatResponse mirrors the assembled text on the assistant
        // message — the ledger has what the user saw, end to end.
        let assistant_text = response
            .assistant_message
            .as_ref()
            .and_then(|m| m.content.text_content())
            .map(str::to_string);
        assert_eq!(assistant_text.as_deref(), Some("Hello, world!"));
    }

