    #[tokio::test]
    async fn nested_user_memory_merge_retains_siblings_and_retracts_one_exact_key() {
        let temporary = tempfile::TempDir::new().unwrap();
        let layout =
            crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(temporary.path());
        let resolver =
            crate::magician_v2::agents::memory::AgentMemoryResolver::with_workspace_layout(layout);
        let mut first = serde_json::Map::new();
        first.insert(
            "writing:gmail:personal:sender:one".to_string(),
            serde_json::json!({ "statement": "Keep replies concise." }),
        );
        let mut second = serde_json::Map::new();
        second.insert(
            "writing:gmail:personal:domain:two".to_string(),
            serde_json::json!({ "statement": "Use a friendly greeting." }),
        );
        assert_eq!(
            super::merge_user_memory_tier_fields(
                &resolver,
                "principal",
                "workspace",
                "user.channel_writing_preferences",
                &first,
            )
            .await["status"],
            "ok"
        );
        assert_eq!(
            super::merge_user_memory_tier_fields(
                &resolver,
                "principal",
                "workspace",
                "user.channel_writing_preferences",
                &second,
            )
            .await["status"],
            "ok"
        );
        assert_eq!(
            super::remove_user_memory_tier_field(
                &resolver,
                "principal",
                "workspace",
                "user.channel_writing_preferences",
                "writing:gmail:personal:sender:one",
            )
            .await["status"],
            "ok"
        );

        let knowledge = resolver
            .resolve_for_scope("principal", "workspace")
            .unwrap()
            .load_user_knowledge()
            .await
            .unwrap();
        let entries = super::read_json_path(&knowledge, "user.channel_writing_preferences")
            .and_then(serde_json::Value::as_array)
            .unwrap();
        assert_eq!(entries.len(), 2, "retractions retain the source history");
        let active = entries
            .iter()
            .filter(|entry| !crate::magician_v2::agents::memory_lifecycle::retired(entry))
            .collect::<Vec<_>>();
        assert_eq!(active.len(), 1);
        assert_eq!(active[0]["key"], "writing:gmail:personal:domain:two");
        let retracted = entries
            .iter()
            .find(|entry| entry["key"] == "writing:gmail:personal:sender:one")
            .unwrap();
        assert_eq!(retracted["memory_lifecycle"], "retracted");
        assert_eq!(retracted["retirement_reason"], "explicit_owner_retraction");
        assert_eq!(retracted["statement"], "Keep replies concise.");
    }

    /// Regression: the chat-turn trace context must carry `execution_id`.
    ///
    /// It used to be left unset, and the activation layer backfilled it onto
    /// the CALL fact only (from the `LLMResponseReceived` event). Tool facts
    /// cloned the same context and kept `NULL`, so the read service's
    /// cross-dataset integrity guard saw every chat-inline tool row disagree
    /// with its owning call on `execution_id` and failed every governed LLM
    /// read. Stamping it here is what keeps call/attempt/tool lineage equal.
    #[test]
    fn chat_turn_trace_context_stamps_execution_id_for_every_downstream_fact() {
        let context = super::chat_turn_trace_context(
            "anonymous",
            "default",
            "session-1",
            "chat-turn-abc",
            Some("user-message-1".to_string()),
        );

        assert_eq!(context.execution_id.as_deref(), Some("chat-turn-abc"));
        assert_eq!(context.chat_turn_id.as_deref(), Some("chat-turn-abc"));
        assert_eq!(context.chat_session_id.as_deref(), Some("session-1"));
        assert_eq!(context.trace_id, "chat-turn-abc");
        assert_eq!(context.user_message_id.as_deref(), Some("user-message-1"));
        // The activation layer asserts equality when the field is already set,
        // so this must match the `execution_id` the turn broadcasts on its
        // `LLMResponseReceived` event (also the chat turn id) or the call fact
        // is rejected outright rather than silently drifting.
        assert_eq!(
            context.execution_id.as_deref(),
            context.chat_turn_id.as_deref(),
            "call-event execution_id is the chat turn id; the context must agree"
        );
    }

    /// The parent engine is scoped at the one entry every inbound turn
    /// converges on, around the turn body, and the turn's execution-runtime
    /// hops carry it across — the prompt render and the memory consolidation
    /// are other tasks.
    #[test]
    fn the_chat_turn_runs_under_the_chat_mouth_as_parent() {
        let source = include_str!("service.rs");
        let entry = source
            .split_once("    async fn process_chat_inline_turn(")
            .expect("chat turn entry")
            .1
            .split_once("    async fn process_chat_inline_turn_inner(")
            .expect("chat turn body")
            .0;
        assert!(entry.contains("plane::chat_turn_parent_engine()"));
        assert!(entry.contains("parent_engine::with_parent_engine("));
        assert!(entry.contains(".process_chat_inline_turn_inner("));

        let prompt_hop = source
            .split_once("    async fn render_chat_outer_loop_prompt_on_execution_runtime(")
            .expect("prompt render hop")
            .1
            .split_once("    async fn render_chat_outer_loop_prompt(")
            .expect("prompt render body")
            .0;
        assert!(prompt_hop.contains("parent_engine::current_parent_engine()"));
        assert!(prompt_hop.contains("parent_engine::with_parent_engine("));

        let consolidation = source
            .split_once("    async fn persist_chat_turn_memory_episode(")
            .expect("memory episode")
            .1
            .split_once("    async fn record_chat_memory_temperature_outcome(")
            .expect("memory episode end")
            .0;
        assert!(consolidation.contains("parent_engine::current_parent_engine()"));
        let spawn = consolidation
            .find("tokio::spawn(")
            .expect("the consolidation task");
        let scoped = consolidation
            .find("parent_engine::with_parent_engine(")
            .expect("the consolidation task is scoped");
        assert!(spawn < scoped);
    }

    #[test]
    fn active_chat_turn_decodes_the_canonical_transcript_only_once() {
        let source = include_str!("service.rs");
        let active_turn = source
            .split_once("    async fn process_chat_inline_turn(")
            .expect("active chat turn")
            .1
            .split_once("    async fn persist_chat_turn_memory_episode(")
            .expect("active chat turn end")
            .0;
        assert_eq!(
            active_turn
                .match_indices(".get_llm_history(&session.id)")
                .count(),
            1,
            "prompt retrieval and provider dispatch must reuse one canonical snapshot"
        );
        assert!(active_turn.contains("let mut history = canonical_history;"));
        assert!(active_turn.contains("CHAT_PROCEDURE_HISTORY_ENTRY_WINDOW"));
        assert!(active_turn.contains(".render_chat_outer_loop_prompt_on_execution_runtime("));
        assert!(active_turn.contains("history_for_procedure_retrieval.to_vec(),"));
        let history_load = active_turn
            .split_once(".get_llm_history(&session.id)")
            .expect("canonical transcript read")
            .1
            .split_once("let history_for_procedure_retrieval")
            .expect("canonical transcript read boundary")
            .0;
        assert!(history_load.contains(".with_context("));
        assert!(history_load.contains("failed to load canonical chat transcript"));
        assert!(history_load.contains("?;"));
        assert!(
            !history_load.contains("unwrap_or_default"),
            "corrupt segmented authority must fail the turn, not erase provider history"
        );
    }

    #[tokio::test]
    async fn voice_delegation_reads_only_the_bounded_canonical_tail() {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let store = Arc::new(FileChatStore::new(temp_dir.path()));
        let session = store
            .get_or_create_active_session(
                "user",
                "workspace",
                "voice",
                &ChatChannel::web(),
                DEFAULT_AGENT_ID,
            )
            .await
            .expect("voice session");
        store
            .append_llm_history_entries(
                &session.id,
                (0..5)
                    .map(|index| ChatLlmTranscriptEntry::UserText {
                        text: format!("turn-{index}"),
                    })
                    .collect(),
            )
            .await
            .expect("older canonical history group");
        store
            .append_llm_history_entries(
                &session.id,
                (5..125)
                    .map(|index| ChatLlmTranscriptEntry::UserText {
                        text: format!("turn-{index}"),
                    })
                    .collect(),
            )
            .await
            .expect("bounded canonical tail group");
        let prompt_manager = Arc::new(PromptManager::new(Arc::new(DummyPromptStore)));
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(16));
        let fallback_llm = ChatLlmService::new(Arc::new(MultiLLMService::new(
            HashMap::new(),
            HashMap::new(),
        )));
        let chat_store: Arc<dyn ChatStore> = store;
        let service = ChatService::new(chat_store, fallback_llm, prompt_manager, broadcaster);

        let history = service
            .load_voice_delegation_history(&session.id)
            .await
            .expect("bounded voice history");
        assert_eq!(history.len(), VOICE_DELEGATION_HISTORY_ENTRY_LIMIT);
        assert!(matches!(
            history.first(),
            Some(ChatLlmTranscriptEntry::UserText { text }) if text == "turn-5"
        ));
        assert!(matches!(
            history.last(),
            Some(ChatLlmTranscriptEntry::UserText { text }) if text == "turn-124"
        ));

        // Keep both entry points on the tested bounded loader. This assertion
        // deliberately names the semantic boundary, not the store call's
        // formatting or numeric spelling.
        let source = include_str!("service.rs");
        for (start, end) in [
            (
                "    pub async fn delegate_for_voice(",
                "    pub async fn delegate_for_voice_streaming(",
            ),
            (
                "    pub async fn delegate_for_voice_streaming(",
                "fn voice_delegated_reasoning_profile(",
            ),
        ] {
            let body = source
                .split_once(start)
                .expect("voice delegation entry point")
                .1
                .split_once(end)
                .expect("voice delegation boundary")
                .0;
            assert!(body.contains(".load_voice_delegation_history(chat_session_id)"));
            assert!(body.contains("let mut history = recent_history;"));
            assert!(
                !body.contains(".get_llm_history"),
                "voice delegation entry points must not bypass the bounded loader"
            );
        }
    }

    #[test]
    fn prompt_size_telemetry_walks_deep_json_without_payload_sized_serialization() {
        std::thread::Builder::new()
            .name("chat-prompt-size-small-stack".to_string())
            .stack_size(256 * 1024)
            .spawn(|| {
                let deep_value = || {
                    let mut value = serde_json::Value::Null;
                    for _ in 0..10_000 {
                        value = serde_json::Value::Array(vec![value]);
                    }
                    value
                };

                let mut entry = ChatLlmTranscriptEntry::AssistantTurn {
                    text: Some("answer".to_string()),
                    tool_calls: vec![StoredToolCall {
                        id: "call-deep".to_string(),
                        name: "inspect".to_string(),
                        arguments: deep_value(),
                    }],
                    provider_state: None,
                };
                assert!(chat_llm_transcript_entry_char_len(&entry) > 20_000);

                let mut spec = LLMToolSpec {
                    name: "inspect".to_string(),
                    description: "deep schema".to_string(),
                    parameters: deep_value(),
                };
                assert!(chat_tool_spec_char_len(&spec) > 20_000);

                if let ChatLlmTranscriptEntry::AssistantTurn { tool_calls, .. } = &mut entry {
                    crate::magician_v2::json_traversal::discard_json_iteratively(std::mem::take(
                        &mut tool_calls[0].arguments,
                    ));
                }
                crate::magician_v2::json_traversal::discard_json_iteratively(std::mem::take(
                    &mut spec.parameters,
                ));
            })
            .expect("spawn prompt-size telemetry regression")
            .join()
            .expect("prompt-size telemetry must fit a 256 KiB stack");
    }

